(window.GIM_TS=window.GIM_TS||{})["Bekhorot.2"]={"from":48,"a":[["\u0003הא\u0004 \u0005[אבל]\u0006 שער \u0003בעל מום שרי\u0004 \u0005[מותר],\u0006 \u0003אף על פי שלא התירו מומחה!\u0004 ודוחים: יש לומר כי ה\u0003תנא\u0004 של ברייתא זו, \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003לא התירו מומחה\u0004 — \u0003\"תם\" קרי ליה\u0004 \u0005[\u0006הוא קורא לו], ואפילו אם היה בעל מום.","ומציעים: אם כך אתה מפרש את הברייתא, \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שדברי ריש לקיש שנויים \u0005כ\u0006מחלוקת \u0005תנאים]?\u0006 שכך שנויה ברייתא זו בשלימותה: \u0003התולש צמר מבכור תם, אף על פי שנולד בו\u0004 אחר כך \u0003מום ושחטו\u0004 — \u0003אסור\u0004 הצמר. \u0003בכור בעל מום שתלש ממנו\u0004 צמר, \u0003ואחר כך מת\u0004 — \u0003עקביא בן מהללאל מתיר\u0004 את הצמר, \u0003וחכמים אוסרים. אמר ר' יהודה: לא ב\u0004מקרה \u0003זה,\u0004 שתלש ממנו ואחר כך מת, \u0003התיר עקביא בן מהללאל\u0004 את הצמר לאחר שחיטה, \u0003אלא בשער בכור בעל מום שנשר והניחו בחלון, ואחר כך שחטו\u0004 — \u0003בזה עקביא בן מהללאל מתיר וחכמים אוסרין.\u0004","\u0003אמר ר' יוסי: מודה אבא\u0004 (אבי) \u0003חלפתא,\u0004 ההולך בשיטת חכמים, \u0003ב\u0004מקרה \u0003זה\u0004 של שער בעל מום שנשר, שאם שחטו — \u0003שהוא מותר,\u0004 שהרי \u0003אבל בייחוד\u0004 (באמת ובבירור) \u0003אמרו חכמים:\u0004 אם נשר שער בכור בעל מום — \u0003יניחנו בחלון, שמא יש תקוה,\u0004 כלומר, שמא יתירוהו, שכן אם \u0003שחטו\u0004 — \u0003דברי הכל מותר,\u0004 ודוקא אם \u0003מת\u0004 — בזה \u0003עקביא בן מהללאל מתיר, וחכמים אוסרים.\u0004 עד כאן לשון הברייתא.","ותוהים: מה שאמר \u0003ר' יוסי\u0004 בשם אביו — \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק מה שאמר \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 בברייתא, שדווקא אם מת הבכור אוסרים חכמים את הצמר, אבל אם שחטו — הריהו מותר! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 דין \u0003התירו מומחה איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006","\u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון סבור]:\u0006 \u0003התירו מומחה\u0004 קודם שנתלש הצמר — \u0003אין\u0004 \u0005[כן],\u0006 הועילה שחיטתו להתיר את הצמר שנתלש, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 התירו מומחה — \u0003לא,\u0004 הריהו אסור לדעת חכמים. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא התירו מומחה\u0004 הצמר מותר? ואם כן נחלקו תנאים בדברי ריש לקיש.","\u0003אמר רבא: לא,\u0004 יש לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003התירו מומחה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר, ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003לא התירו\u0004 — \u0003לא. ושלש מחלוקת בדבר,\u0004 שלוש דעות. \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון סבור]:\u0006 \u0003פליגי\u0004 \u0005[חלוקים]\u0006 עקביא וחכמים \u0003ב\u0004בכור ש\u0003מת, והוא הדין לשחטו\u0004 שגם בזה אוסרים חכמים את הצמר. \u0003והאי דקמיפלגי\u0004 \u0005[וזה\u0006 שהוא שונה \u0005שהם חלוקים]\u0006 \u0003במת\u0004 — הרי זה \u0003להודיעך כחו\u0004 של \u0003עקביא,\u0004 שהוא מתיר את הצמר שנשר בחייו, למרות שהצמר שעל גופו אסור.","\u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003במת\u0004 — \u0003דברי הכל אסור,\u0004 וגם לדעת עקביא. \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003ב\u0004מקרה ש\u0003שחטו,\u0004 שעקביא מתיר את הצמר, וחכמים אוסרים. \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003בשחטו\u0004 — \u0003דברי הכל,\u0004 וגם לדעת חכמים, הצמר \u0003מותר,\u0004 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — הרי זה \u0003במת.\u0004","ובפסיקת ההלכה במחלוקת שבמשנתינו, \u0003אמר רב נחמן: הלכה כר' יהודה, הואיל ותנן בבחירתא כוותיה\u0004 \u0005[ושנינו ב\u0006מסכת \u0005המובחרת,\u0006 מסכת עדויות, \u0005כשיטתו].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 שם במשנה\u0005]:\u0006 \u0003שער בכור בעל מום שנשר והניחו בחלון, ואחר כך שחטו\u0004 — \u0003עקביא בן מהללאל מתיר, וחכמים אוסרין.\u0004","\u0003אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דתנן\u0004 \u0005[ששנינו ב\u0006סופה\u0005]:\u0006 \u0003צמר המדולדל בבכור,\u0004 שאינו מחובר לגופו, \u0003את ש\u0004הוא \u0003נראה עם הגיזה,\u0004 כשגוזז אותו — \u0003מותר, ואת שאינו נראה\u0004 — \u0003אסור,\u0004 שדינו כדין צמר שנשר והניחו בחלון.","ונברר: משנתנו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' יוסי; ובמאי\u0004 \u0005[ובמה],\u0006 באיזה מקרה מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשחטו\u0004 — הרי לשיטת ר' יוסי, \u0003בין עקביא בין רבנן\u0004 \u0005[חכמים]\u0006 \u0003אידי ואידי משרא שרי\u0004 \u0005[זה וזה מתירים הם],\u0006 גם את הצמר הנראה מן הגיזה, וגם את הצמר שאינו נראה מן הגיזה!","\u0003ואלא\u0004 צריך לומר שמדובר \u0003במת. ואי רבנן\u0004 \u0005[ואם\u0006 לשיטת \u0005חכמים]\u0006 — הרי \u0003אידי ואידי מיסר אסרי\u0004 \u0005[זה וזה הם אוסרים],\u0006 בין זה שנראה מן הגיזה — שהרי גיזת הבכור שמת אסורה בהנאה, ובין זה שאינו נראה מן הגיזה — כדין צמר שנשר והניחו בחלון! \u0003ואי\u0004 \u0005[ואם]\u0006 לשיטת \u0003עקביא,\u0004 המתיר צמר שנשר והניחו בחלון — הלוא \u0003איפכא מיבעיא ליה\u0004 \u0005[ההיפך היה צריך לו\u0006 לומר\u0005],\u0006 שדווקא הצמר ה\u0003נראה עם הגיזה אסור, דמיתה קאסרה ליה\u0004 \u0005[\u0006משום \u0005שהמיתה אוסרת אותו],\u0006 כמו הצמר המחובר לגוף הבכור. ואילו הצמר ש\u0003אינו נראה עם הגיזה\u0004 — \u0003מותר, דמעיקרא תליש\u0004 \u0005[\u0006משום \u0005שמתחילה,\u0006 קודם שמת, כבר היה \u0005תלוש]!\u0006","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהוא כשיטת \u0003ר' יהודה\u0004 במשנתנו. \u0003ובמאי\u0004 \u0005[ובמה]?\u0006 באיזה מקרה מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003במת\u0004 — הלוא לדעתו \u0003בין לעקביא בין לרבנן\u0004 \u0005[לחכמים],\u0006 \u0003אידי ואידי מיסר אסרי\u0004 \u0005[זה וזה\u0006 הם \u0005אוסרים]\u0006 לא רק את הצמר הנראה מן הגיזה — כדין הגיזה עצמה שהיא אסורה, אלא גם את זה שאינו נראה כחלק ממנה — כדין צמר שנשר והניחו בחלון!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בשחטה,\u0004 ששחט את הבכור? \u0003ואי\u0004 \u0005[ואם]\u0006 לשיטת \u0003עקביא\u0004 — \u0003אידי ואידי משרא שרי\u0004 \u0005[זה וזה מותרים],\u0006 גם הנראה מן הגיזה, וגם שאינו נראה חלק ממנה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא? ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003בשחטו פליגי\u0004 \u0005[חלוקים הם],\u0006 וכשם שהם אוסרים במקרה זה את הצמר שנשר והניחו בחלון — כך הם אוסרים את הצמר שאינו נראה חלק מן הגיזה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ינאי: התולש צמר מעולה תמימה,\u0004 ולאחר מכן נשחטה, והותר הצמר שעליה לכהנים, \u0003מהו\u0004 דין הצמר שנתלש בחייה? ותמהים: \u0003תולש? מי איכא מאן דשרי\u0004 \u0005[האם יש מי שמתיר]\u0006 את הצמר במקרה שתלש במתכוון? \u0003אלא\u0004 כך שאל: \u0003צמר שנתלש\u0004 מעצמו \u0003מעולה תמימה,\u0004 ונשחטה, \u0003מהו?\u0004 האם גזרו חכמים שלא ליהנות ממנו, מחשש שמא ישהה אותה אצלו כדי ליהנות מצמרה?","ומסבירים: לגבי צמר שנתלש מ\u0003חטאת ואשם לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ובוודאי אין לאסור את הצמר, ש\u0003כיון\u0004 ש\u0003לכפרה אתו\u0004 \u0005[\u0006הם \u0005באים]\u0006 — \u0003לא משהו להו\u0004 \u0005[משהים אותם],\u0006 אלא ממהרים להקריבם, כדי לזכות בכפרה. וכן מצד אחר, \u0003בכור ומעשר נמי\u0004 \u0005[גם כן],\u0006 בוודאי אסרו חכמים את הצמר שנתלש ממנה בחייה, ש\u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003לכפרה אתו\u0004 \u0005[\u0006הם \u0005באים]\u0006 — יש לחשוש שמא \u0003משהו להו\u0004 \u0005[משהים אותם].\u0006 \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה לענין \u0003עולה, מאי\u0004 \u0005[מה הדין]?\u0006 האם \u0003כיון\u0004"],["\u0003דעיקר לאו לכפרה אתי\u0004 \u0005[שעיקרה לא לכפרה\u0006 היא \u0005באה]\u0006 — \u0003משהי לה\u0004 \u0005[משהה אותה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כיון\u0004 שעל כל פנים, \u0003עולה נמי מכפרא\u0004 \u0005[גם כן מכפרת]\u0006 על ביטול מצות \u0003עשה\u0004 — \u0003לא משהי לה\u0004 \u0005[אין משהה אותה]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003התולש צמר מבכור תם, אף על פי\u0004 שתלש אחר \u0003שנולד בו מום,\u0004 ו\u0003שחטו\u0004 — \u0003אסור.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003תולש\u0004 בכוונה הריהו אסור גם לאחר שחיטה, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003נתלש\u0004 מעצמו — \u0003שרי\u0004 \u0005[מותר].\u0006 שאין חוששים שמא יבוא להשהות את הבכור, כדי לשמור את הצמר שייתלש ממנו. \u0003וכל שכן עולה,\u0004 שיש בה כפרה, שצמרה מותר, \u0003דלא משהי לה\u0004 \u0005[שאין\u0006 לחשוש ש\u0005משהה אותה]!\u0006","","ודוחים: \u0003הוא הדין אפילו נתלש נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור, והאי דקתני\u0004 \u0005[וזה שהוא שונה]\u0006 בלשון \u0003\"תולש\"\u0004 — הרי זה כדי \u0003להודיעך כחו\u0004 של \u0003עקביא,\u0004 עד כמה הוא מתיר, ש\u0003ב\u0004דינו של \u0003בעל מום,\u0004 השנוי מיד אחר כך — \u0003אפילו בתולש\u0004 במתכוון \u0003נמי שרי\u0004 \u0005[גם כן\u0006 הוא \u0005מתיר].\u0006","ומקשים: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"נשר\" תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, במחלוקת עקביא וחכמים לגבי בעל מום, ולא בתולש! ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 במשנתנו \u0003\"נשר\",\u0004 כדי \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים],\u0006 שהם אוסרים את הצמר אפילו במקרה זה, ואילו בברייתא \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"תולש\",\u0004 כדי \u0003להודיעך כחו\u0004 של \u0003עקביא,\u0004 כמה הוא מתיר.","שנינו במשנה: \u0003צמר המדולדל\u0004 בבכור (שנתלש אבל לא נשר ממנו), את שהוא נראה עם הגיזה — מותר לאחר שחיטתו, יחד עם שאר הגיזה. ואת שאינו נראה עם הגיזה — אסור, כדין צמר שנשר מחיים (לדעת חכמים במשנה). ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003\"אינו נראה עם הגיזה\"? אמר ר' אלעזר אמר ריש לקיש: כל שעיקרו\u0004 של הצמר התלוש, חלקו התחתון, \u0003הפוך כלפי ראשו,\u0004 כלפי מעלה. \u0003רב נתן בר אושעיא אמר: כל שאינו מתמעך עם הגיזה,\u0004 שבולט מחוץ לשאר הצמר כשמועכים את הגיזה.","ושואלים: \u0003וריש לקיש,\u0004 שהוצרך לפרש שנתהפך השיער, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב נתן בר אושעיא?\u0004 והרי זו היא משמעותו הפשוטה של \"אינו נראה מן הגיזה\"! \u0003אמר ר' אילעא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ריש לקיש:\u0004 בוודאי לא אסרו חכמים צמר זה, \u0003לפי שאי אפשר לגיזה בלא\u0004 שיהיו בה \u0003נימין\u0004 (שערות) \u0003המדולדלות,\u0004 ואם חוששים לכך — לא ניתן להשתמש לעולם בגיזת הבכור שמת. ולכן בעל כרחנו יש לומר שמדובר במקרה אחר, והוא שנתהפך השיער.","","\u0003עד כמה ישראל חייבין ליטפל בבכור\u0004 בהמה טהורה, לגדלו, קודם שימסרנו לכהן? \u0003ב\u0004בהמה \u0003דקה\u0004 (כבשים ועזים) — \u0003שלשים יום, ובגסה\u0004 (בקר) — \u0003חמשים יום. רבי יוסי אומר: בדקה\u0004 — \u0003שלשה חדשים. אמר לו הכהן בתוך הזמן\u0004 הזה: \u0003\"תנהו לי\"\u0004 — \u0003הרי זה לא יתננו לו. ואם\u0004 בכור זה \u0003בעל מום הוא, ואמר לו\u0004 הכהן: \u0003\"תנהו לי שאוכלנו\"\u0004 — \u0003מותר\u0004 ליתן לו. \u0003ובשעת המקדש, אם היה תמים,\u0004 ו\u0003אמר לו: \"תן\u0004 לי \u0003ואקרבנו\"\u0004 — \u0003מותר.\u0004","\u0003הבכור נאכל שנה בשנה,\u0004 כלומר, בתוך שנתו הראשונה, \u0003בין\u0004 שהוא \u0003תם בין\u0004 שהוא \u0003בעל מום, שנאמר: \"לפני ה' אלהיך תאכלנו שנה בשנה\"\u0004 (דברים טו, כ). \u0003נולד לו מום בתוך שנתו\u0004 — \u0003רשאי לקיימו כל שנים עשר חדש. לאחר שנים עשר חדש\u0004 — \u0003אינו רשאי לקיימו אלא שלשים יום.\u0004 שנינו במשנה כי ישראל חייב לגדל את הבכור, קודם שיתננו לכהן, בבהמה הדקה שלושים יום, ובגסה חמישים יום. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב כהנא: דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 \"מלאתך ודמעך לא תאחר, בכור בניך תתן לי. כן תעשה לשורך לצאנך\" (שמות כב, כח — כט). וכך דורשים את הכתוב: \u0003\"בכור בניך תתן לי\"\u0004 — \u0003\"כן תעשה לצאנך\",\u0004 כלומר, כדין בכור האדם, שצריך לתת לכהן חמשה סלעים בפדיונו לאחר שלושים יום (במדבר יח, טז) — כן דין בכור מן הצאן, שניתן לכהן לאחר שלושים יום.","","\u0003\"מלאתך ודמעך לא תאחר\"\u0004 — \u0003\"כן תעשה לשרך\",\u0004 כלומר, כדין הביכורים מן התבואה (\"מלאתך\"), שמביאים ביכורים בחג השבועות, חמישים יום לאחר שהחלה התבואה להבשיל — כן דין בכור השור, שניתן לכהן לאחר חמשים יום.","ומקשים: אם מכאן למדים, \u0003איפוך אנא\u0004 \u0005[אהפוך אני],\u0006 ואומר: דין בכור השור כדין בכור האדם, ודין בכור הצאן כדין ביכורי התבואה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 שמקישים \u0003דמקדם למקדם\u0004 \u0005[\u0006את \u0005המוקדם\u0006 בפסוק השני \u0005למוקדם\u0006 בפסוק הראשון\u0005],\u0006 \u0003דמאחר לדמאחר\u0004 \u0005[\u0006ואת \u0005שמאוחר\u0006 בפסוק השני \u0005למאוחר\u0006 שבפסוק הראשון\u0005].\u0006 ודוחים: \u0003אדרבה,\u0004 מקישים \u0003דסמיך ליה לדסמיך ליה\u0004 \u0005[\u0006את \u0005שסמוך לו ל\u0006מה \u0005שסמוך לו],\u0006 כלומר, את בכור השור לבכור אדם!","אלא אמר רבא: $1בכודרות גם בכור צאן וגם בכור שור הוקשו בפסוק זה לבכור אדם, שצריך ליתנם לכהן לאחר שלשים יום, ואולם \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"כן \u0003תעשה\u0004 לשורך\", \u0003הוסיף לך הכתוב עשייה אחרת בשורך,\u0004 יתר על עשייה שבבכור אדם.","ומקשים: לפי זה, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003שיתין\u0004 \u0005[שישים\u0006 יום\u0005],\u0006 פי שניים מבכור אדם, ולא רק חמישים! ומשיבים: הואיל ולא נתפרש הדבר בכתוב, \u0003לא מסרך הכתוב אלא לחכמים\u0004 שיקבעו בדבר, והם קבעו חמישים יום.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"בכור בניך תתן לי\"\u0004 — \u0003\"כן תעשה לצאנך\",\u0004 כלומר, שיינתן לכהן לאחר שלושים יום. \u0003יכול אף לשורך\u0004 שלושים יום? \u0003תלמוד לומר: \"תעשה\"\u0004 — \u0003הוסיף לך הכתוב עשייה אחרת בשורך,\u0004 והואיל ולא נאמר בכתוב בכמה זמן מדובר, \u0003לא מסרך הכתוב אלא לחכמים\u0004 להגדיר את הדבר.","\u0003מכאן אמרו\u0004 חכמים: \u0003עד כמה ישראל חייבין להטפל\u0004 (לטפל) \u0003בבכור: בבהמה דקה\u0004 — \u0003שלשים יום,\u0004 \u0003בגסה\u0004 — \u0003חמשים יום. ר' יוסי אומר: בדקה\u0004 — \u0003שלשה חדשים, מפני שטפולה מרובה,\u0004 שצריך לטרוח הרבה בגידולה ובהאכלתה קודם שתהא ראויה לינתן לכהן. ומעירים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בהסבר דבר זה: \u0003מפני ששיניה דקות,\u0004 ועדיין אינה מסוגלת לאכול הכל.","שנינו במשנה: \u0003אם אמר לו הכהן בתוך הזמן \"תנהו לי\"\u0004 — \u0003הרי זה לא יתן לו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב ששת: מפני שנראה ככהן המסייע\u0004 לבעלים \u0003בבית הגרנות,\u0004 כלומר, בעבודת התבואה בגורן, שאסור ליתן לו את התרומה בשכר עבודתו. שהרי כהן זה, נראה כמציע לבעלים לחסוך את הטרחה וההוצאות הכרוכים בטיפול בבכור, ובתמורה הוא מקבל את הבכור.","בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכהנים והלוים והעניים המסייעים בבית הרועים,\u0004 כלומר, בעבודת הצאן, \u0003ובבית הגרנות,\u0004 באיסוף ועימור התבואה, \u0003ובבית המטבחים,\u0004 בעבודת השחיטה — \u0003אין נותנין להם תרומה ומעשר בשכרן, ואם עושין כן\u0004 — \u0003חיללו\u0004 את הקודש. \u0003ועליהן,\u0004 על כהנים ולויים העושים כן, \u0003הכתוב אומר: \"שחתם ברית הלוי\"\u0004 (מלאכי ב, ח), \u0003ואומר: \"ואת קדשי בני ישראל לא תחללו ולא תמותו\"\u0004 (במדבר יח, לב).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הטעם\u0005]\u0006 של התוספת \u0003\"ואומר\"?\u0004 מה הוסיף בכך? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 מן הכתוב \"שחתם ברית הלוי\" יש להבין שחיללו את התרומה והמעשר, אבל בעונש \u0003מיתה לא\u0004 ייענשו בעוון זה — לכן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 דבר זה מן הכתוב: \u0003\"ואת קדשי בני ישראל לא תחללו ולא תמותו\".\u0004","וממשיכה הברייתא: \u0003ובקשו חכמים לקונסן\u0004 את הנותנים תרומה ומעשר לכהנים, ללויים ולעניים שעושים כן, \u0003ולהיות\u0004 חוזרים ו\u0003מפרישין עליהן תרומה משלם\u0004 (שלימה), כדי שלא ירויחו כלל בדבר. \u0003ומפני מה לא קנסום?\u0004 \u0003דלמא\u0004 \u0005[שמא]\u0006 יטעו לומר שתבואה זו הריהי טבל גמור, ומתוך כך \u0003אתי לאפרושי\u0004 \u0005[יבואו להפריש]\u0006 תרומות ומעשרות \u0003מן הפטור על החיוב,\u0004 כלומר, מתבואה זו שכבר נפטרה מדין תורה מתרומות ומעשרות, על תבואה אחרת, החייבת מן התורה בתרומות ומעשרות, ואין זה מועיל לפוטרה.","ומוסיפה הברייתא: \u0003ובכולן,\u0004 אף שאסור ליתן תרומה ומעשר לכהנים בשכר עבודתם, מכל מקום \u0003יש בהן\u0004"],["\u0003טובת הנאה לבעלים,\u0004 כלומר, יכולים הבעלים ליהנות מן הזכות ליתן את המתנות לכהן מסויים.","\u0003כיצד? ישראל שהפריש תרומה מכריו\u0004 (מערימת התבואה שלו), \u0003ומצאו ישראל אחר, ואמר לו: \"הא לך סלע\u0004 (מטבע ששוויו ארבעה זוזים) \u0003זה, ותנהו\u0004 את מה שהפרשת כתרומה \u0003לבן בתי\u0004 שהוא \u0003כהן\"\u0004 — הרי זה \u0003מותר.\u0004 אבל \u0003אם היה\u0004 זה \u0003כהן\u0004 שנתן סלע לבעלים, כדי שיתן את התרומה \u0003לכהן\u0004 אחר — \u0003אסור,\u0004 שהכהנים אינם רשאים ליתן דבר תמורת מתנותיהם.","ושואלים: \u0003ותנא מאי טעמא לא קאמר\u0004 \u0005[והתנא, מה טעם אינו אומר],\u0006 אינו מזכיר שיש טובת הנאה לבעלים גם ב\u0003מתנות כהונה,\u0004 כלומר, בזרוע לחיים וקיבה שצריך כל שוחט בהמה לתת לכהן, אלא רק בתרומה? ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 בתשובה: \u0003תרומה\u0004 — דבר שיש בו \u0003קדושת הגוף היא, דכיון דלא מתחלא\u0004 \u0005[שכיון שאינה מתחללת],\u0006 שלא ניתן לפדותה, ולעולם יש לה דין תרומה — \u0003לא אתי למיטעי בה\u0004 \u0005[יבוא\u0006 הכהן \u0005לטעות בה],\u0006 ולנהוג בה מנהג חולין, גם אם יקבל הבעלים מטבע של סלע בטובת הנאתה, שלא יחשוב שנתחללה באותה מטבע.","אבל \u0003הני\u0004 \u0005[אלה],\u0006 מתנות כהונה, \u0003כיון\u0004 ש\u0003קדושת דמים נינהו\u0004 \u0005[הם],\u0006 שיכול הכהן שקיבלם למוכרם, ומאותה שעה חולין גמורים הם, הרי אם יתנם הבעלים לכהן בטובת הנאה — \u0003אתי למיטעי בהון\u0004 \u0005[יבוא\u0006 הכהן \u0005לטעות בהם],\u0006 ולומר \u0003דבר מיתחל קדושתייהו אארבעה זוזי\u0004 \u0005[שניתן היה לחלל את קדושתם על\u0006 אותם \u0005ארבעה זוזים],\u0006 כלומר, על אותו סלע שניתן לבעלים (שיש ארבעה זוזים בסלע), \u0003ואתא למינהג\u0004 \u0005[ויבוא לנהוג]\u0006 \u0003בהן מנהג\u0004 של \u0003חולין,\u0004 שלא כדין מתנות כהונה, שצריך הכהן לאוכלם בכבוד.","בענין האיסור לכהן לסייע לבעלים בבית הגרנות, ובתמורה לכך לקבל את התרומה, \u0003אמר רבא: תרומת חוצה לארץ,\u0004 שתיקנו חכמים להפריש מן התבואה בחוצה לארץ — \u0003אין בה משום\u0004 איסור \u0003כהן המסייע בבית הגרנות.\u0004 וכן מסופר ש\u0003רב חמא יהיב ליה לשמעיה\u0004 \u0005[היה נותן לו לשמשו],\u0006 שהיה כהן, תרומה בשכרו.","ועוד בענין תרומת חוצה לארץ, \u0003אמר שמואל: תרומת חוצה לארץ\u0004 שנתערבה בחולין — \u0003בטילה ברוב,\u0004 ולא באחד למאה, כתרומת ארץ ישראל. מסופר, \u0003רבה,\u0004 שהיה כהן, היה \u0003מבטלה ברוב\u0004 חולין לכתחילה, \u0003ו\u0004כך היה \u0003אוכל לה\u0004 \u0005[אותה]\u0006 \u0003בימי טומאתו,\u0004 למרות שאסור לאכול תרומה בטומאה.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, כי מתרמי ליה חמרא\u0004 \u0005[כאשר היה מזדמן לידו יין]\u0006 של \u0003תרומה\u0004 של חוצה לארץ, \u0003הוה רמי תרי נטלי\u0004 \u0005[היה מטיל,\u0006 שופך לכלי גדול, \u0005שני ספלים]\u0006 של יין חולין, וחדא נטלא \u0005[וספל אחד]\u0006 של יין \u0003תרומה,\u0004 כדי לבטל את התרומה ברוב, \u0003ושקיל חד\u0004 \u0005[ונוטל\u0006 משם ספל \u0005אחד]\u0006 ושותה אותו. \u0003מיכן ואילך, רמי חדא\u0004 \u0005[\u0006היה \u0005שופך ספל אחד\u0006 של יין תרומה\u0005]\u0006 לכלי זה שנתבטלה בו תרומה ברוב, \u0003ושקיל חדא\u0004 \u0005[ונוטל אחד],\u0006 ושותה. וכך היה חוזר ועושה בכל יין התרומה שבידו, שהיה מטיל ממנו ספל לכלי זה שבו התערובת, ונוטל מן הכלי ספל ושותה.","\u0003ואמר שמואל: תרומת חוצה לארץ\u0004 אינו צריך להפריש אותה תחילה, כדי להתיר את התבואה באכילה, אלא \u0003אוכל והולך\u0004 מן התבואה \u0003ואחר כך מפריש.\u0004","\u0003ואמר שמואל: אין תרומת חוצה לארץ אסורה\u0004 לכהן טמא \u0003אלא במי שהטומאה יוצאה עליו מגופו,\u0004 כגון בעל קרי, או נדה. אבל לא בכהן שנטמא במת, או בשרץ, או בנבילה. \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 \u0003באכילה,\u0004 שאסור לכהן שהוא טמא בטומאה כזו, לאוכלה. \u0003אבל בנגיעה\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 שאין איסור על הטמא לגעת בתרומת חוצה לארץ.","\u0003אמר רבינא: הילכך, נדה,\u0004 שהיא טמאה בטומאה היוצאת מגופה, \u0003קוצה\u0004 (מפרישה) בידה \u0003חלה\u0004 מן העיסה בחוצה לארץ, \u0003ואוכל לה\u0004 \u0005[אותה]\u0006 \u0003כהן קטן,\u0004 שלא ראה קרי, שדין חלת חוצה לארץ כדין תרומת חוצה לארץ. \u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 \u0003כהן קטן\u0004 שיאכלנה בטהרה — \u0003שקלה לה בריש מסא\u0004 \u0005[נוטלת אותה\u0006 הנדה \u0005בקצה שיפוד],\u0006 \u0003ושדיא בתנורא\u0004 \u0005[ומשליכה\u0006 אותה \u0005לתנור],\u0006 כדי שתישרף שם. \u0003והדר מפרשא חלה אחריתי\u0004 \u0005[וחוזרת ומפרישה חלה אחרת],\u0006 ולא מצד הדין, אלא \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תשתכח תורת חלה,\u0004 שלא יישכח החיוב ליתן חלה לכהן. \u0003ו\u0004חלה זו \u0003אוכל לה\u0004 \u0005[אותה]\u0006 \u0003כהן\u0004 שהוא \u0003גדול,\u0004 גם כשהוא טמא.","מסופר, \u0003רב נחמן ורב עמרם ורמי בר חמא הוו קאזלי בארבא\u0004 \u0005[היו הולכים,\u0006 מפליגים, \u0005בספינה],\u0006 \u0003סליק\u0004 \u0005[הלך]\u0006 \u0003רב עמרם לאפנויי\u0004 \u0005[להתפנות\u0006 לצרכיו\u0005],\u0006 \u0003אתאי ההיא איתתא עלת קמייהו\u0004 \u0005[באה אישה אחת\u0006 ו\u0005נכנסה לפניהם],\u0006 לפני רב נחמן ורמי בר חמא, \u0003אמרה להו\u0004 \u0005[להם]:\u0006 \u0003טמא מת מהו שיטבול, ו\u0004כך \u0003אוכל תרומת חוצה לארץ? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרמי בר חמא:\u0004"],["\u0003וכי הזאה\u0004 של מי פרה אדומה \u0003יש לנו\u0004 לטהר את מי שנטמא במת? ומה תועלת יש בכך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא:\u0004 וכי \u0003לא ליחוש ליה לסבא\u0004 \u0005[נחשוש לו לזקן],\u0006 לרב עמרם, שלא לענות תשובה עד שישוב? \u0003אדהכי אתא\u0004 \u0005[בינתיים בא]\u0006 \u0003רב עמרם, אמר להו\u0004 \u0005[להם],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: טמא מת טובל ואוכל בתרומת חוצה לארץ.\u0004","ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006 שהרי \u0003אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב ששת:\u0004 \u0003טמא שרץ טובל ואוכל בתרומת חוצה לארץ,\u0004 והוסיף מר זוטרא: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו].\u0006","שנינו במשנה: \u0003בכור נאכל שנה בשנה כו'.\u0004 ומעירים: \u0003מדקאמר\u0004 \u0005[ממה ש\u0006הוא \u0005אומר]\u0006 בהמשך הדברים: \u0003\"נולד בו מום בתוך שנתו\",\u0004 ולא \"בתוך שנה\", \u0003למימרא\u0004 \u0005[\u0006יש \u0005לומר]\u0006 ש\u0003לשנה דידיה\u0004 \u0005[שלו],\u0006 כלומר, לפי שנתו שלו \u0003מנינן\u0004 \u0005[מונים אנו],\u0006 שהוא נאכל עד שתימלא לו שנה מיום שנולד, ולא עד ראש השנה. ואומרים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006","ש\u0003אמר רב יהודה אמר רב, דאמר קרא\u0004 \u0005[שאומר הכתוב]\u0006 בענין זה: \u0003\"לפני ה' אלהיך תאכלנו שנה בשנה\"\u0004 (דברים טו, כ), \u0003איזוהי שנה שנכנסת בחברתה,\u0004 כלומר, בתוך שנה אחרת? \u0003הוי אומר: שנה של בכור,\u0004 שאם נולד באמצע השנה — שנתו הראשונה נכנסת לשנה הבאה למנין העולם.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב תנא\u0004 \u0005[שנה]\u0006 דרשה אחרת על פסוק זה: \"תאכלנו \u0003שנה בשנה\"\u0004 יש להבינו — שיהא נאכל \u0003יום אחד בשנה זו, ויום אחד בשנה זו\u0004 שאחריה, ובכך \u0003לימד על הבכור, ש\u0004הוא \u0003נאכל\u0004 ( כשמקריבים אותו בבית המקדש) \u0003לשני ימים ולילה אחד\u0004 (שביניהם), וכדין קרבן שלמים.","ושואלים: ולפי זה, \u0003דבי\u0004 \u0005[\u0006החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב, מנא להו\u0004 \u0005[מנין להם]\u0006 שמונים לבכור שנה מיום הולדתו, ולא למנין העולם? ומשיבים: \u0003ילפי\u0004 \u0005[לומדים\u0006 הם\u0005]\u0006 \u0003מ\u0004שאר ה\u0003קדשים\u0004 שכאשר נאמר שיש להביא בן שנה או שנתיים, הרי זה למנין השנים שלו ולא של עולם. ושואלים: \u0003ו\u0004שאר \u0003קדשים גופייהו\u0004 \u0005[עצמם],\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך דינם? \u0003אמר רב אחא בר יעקב: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כבש בן שנתו\"\u0004 (ויקרא יב, ו) — לומר: \u0003שנתו שלו, ולא שנה של מנין עולם.\u0004","ושואלים: \u0003ורב,\u0004 אותה הלכה שבכור \u0003נאכל לשני ימים ולילה אחד, מנא ליה\u0004 \u0005[מנין לו]?\u0006 ואומרים: \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שנאמר לאהרן ולבניו ביחס לבכור: \u0003\"ובשרם יהיה לך כחזה התנופה וכשוק הימין\"\u0004 (במדבר יח, יח) — \u0003הקישו\u0004 (השווה אותו) \u0003הכתוב\u0004 את הבכור \u0003לחזה ושוק של\u0004 קרבן \u0003שלמים,\u0004 שצריך אדם לתת לכהן במתנה: \u0003מה להלן,\u0004 בשלמים — הריהם נאכלים ב\u0003שני ימים ולילה אחד,\u0004 כפי שמפורש בכתוב (ויקרא ז, טז), \u0003אף כאן\u0004 בבכור — \u0003שני ימים ולילה אחד.\u0004"],["ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 החכם מבית מדרשו של רב\u0005],\u0006 מה הוא אומר? מדוע אינו למד מחזה ושוק? ומשיבים: \u0003אי מהתם\u0004 \u0005[אם משם],\u0006 \u0003איכא למימר\u0004 \u0005[יש לומר]\u0006 שהכתוב משווה אותו ל\u0003חזה ושוק של\u0004 קרבן \u0003תודה,\u0004 הניתנים אף הם לכהן, והם נאכלים רק ליום אחד ולילה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רב יהודה בשם רב\u0005],\u0006 מה הוא משיב על כך? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בבכור: \"ובשרם יהיה לך כחזה התנופה וכשוק הימין \u0003לך יהיה\"\u0004 (במדבר יח, יח) — \u0003הוסיף לך הכתוב הויה אחרת בבכור,\u0004 שתהיה בו לכהן זכות נוספת, יום נוסף באכילה, יתר על חזה ושוק של תודה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מדוע אינו דורש באופן זה? ומשיבים: \u0003הא מהתם\u0004 \u0003איכא למימר\u0004 \u0005[הרי משם יש לומר]\u0006 באופן אחר: \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"יהיה לך\"\u0004 — \u0003לימד על בכור בעל מום שנותנו לכהן.\u0004 והוזקק לכתוב זה, \u0003ש\u0004הרי \u0003לא מצינו לו\u0004 \u0003בכל התורה כולה,\u0004 שיינתן קרבן בעל מום לכהן.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מהיכן הוא למד דין זה? ומשיבים: \u0003אמר\u0004 שם הכתוב \u0003\"ובשרם\u0004 יהיה לך\" בלשון רבים, כלומר, \u0003אחד\u0004 בכור \u0003תם ואחד\u0004 בכור \u0003בעל מום.\u0004 ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 מדוע אינו למד מ\"ובשרם\"? ומשיבים: לשיטתו, \u0003\"ובשרם\" דהני בכורות דכולהו ישראל קאמר\u0004 \u0005[של אותם הבכורות של כל ישראל הוא אומר],\u0006 שיהיו לאהרן ולבניו, ולכן הוא בלשון רבים.","שנינו במשנה: \u0003נולד לו מום בתוך שנתו רשאי לקיימו כל שנים עשר חדש,\u0004 לאחר שנתו — אינו רשאי לקיימו אלא שלושים יום. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה ללומדים: \u0003היכי קאמר\u0004 \u0005[כיצד הוא אומר]?\u0006 מה כוונת התנא? האם כוונתו: \u0003נולד לו בתוך שנתו\u0004 — \u0003רשאי לקיימו כל שנים עשר חדש,\u0004 עד שתשלם שנתו, \u0003ו\u0004כן \u0003לאחר שנתו נמי\u0004 \u0005[גם כן]\u0006 נותנים לו עוד \u0003שלשים\u0004 יום. \u0003או דלמא\u0004 \u0005[שמא]\u0006 מדובר בשני מקרים: \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003נולד בו מום בתוך שנתו\u0004 — \u0003רשאי לקיימו כל שנים עשר חדש, ותו לא\u0004 \u0005[ולא עוד].\u0006 \u0003והיכא\u0004 \u0005[ובמקום]\u0006 ש\u0003נולד לו\u0004 המום \u0003אחר שנתו\u0004 — \u0003אינו רשאי לקיימו אלא שלשים\u0004 יום?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003בכור בזמן הזה,\u0004 שלא ניתן להקריבו, \u0003עד שלא נראה\u0004 בו מום \u0003להראותו לחכם\u0004 — \u0003רשאי לקיימו שתים ושלש שנים. ומשנראה להראותו לחכם,\u0004 אם \u0003נולד לו מום בתוך שנתו\u0004 — \u0003רשאי לקיימו כל שנים עשר חדש.\u0004","אבל \u0003אחר שנתו אינו רשאי לקיימו אפילו יום אחד, ואפילו שעה אחת. אבל מפני השבת אבידה לבעלים,\u0004 כלומר, כדי שיוכל למצוא כהן, שהוא נחשב בעליו של הבכור, ולתת לו את הבכור, \u0003אמרו\u0004 חכמים: \u0003רשאי לקיימו\u0004 עוד שלשים יום. ושואלים:","\u0003ועדיין תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לי\u0004 השאלה על הברייתא עצמה: האם \u0003שלשים יום\u0004 אלו ניתנים לבכור שנולד בו מום \u0003אחר\u0004 שעברה \u0003שנתו, או דלמא\u0004 \u0005[שמא]\u0006 לבכור שנולד בו מום \u0003קודם\u0004 שעברה \u0003שנתו?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003נולד לו מום בחמשה עשר יום בתוך שנתו,\u0004 כלומר, חמישה עשר יום קודם שנסתיימה שנתו הראשונה — \u0003משלימין לו חמשה עשר יום אחר שנתו\u0004 לכדי שלושים יום. ומכאן יש ללמוד כי מה ששנינו שרשאי לקיימו שלושים יום מתייחס רק לבכור שנולד בו מום לאחר שנתו. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא. ומעירים: \u0003מסייע\u0004 הדבר \u0003לר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר:\u0004 בכור שנולד לו מום בסוף שנתו \u0003נותנין לו שלשים יום משעה שנולד בו מום.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ענין זה באופן הפוך, \u0003אמר ר' אלעזר: מנין לבכור שנולד בו מום בתוך שנתו שנותנין לו שלשים יום אחר שנתו? שנאמר: \"לפני ה' אלהיך תאכלנו שנה בשנה\"\u0004 (דברים טו, כ), ומשמע — שנה ועוד שנה; \u0003איזו\u0004 (אלו) \u0003הן ימים החשובין\u0004 (הנחשבים) כ\u0003שנה\u0004 שלימה — \u0003הוי אומר אלו שלשים יום,\u0004 שהם נחשבים בתורה כשנה שלימה לכמה עניינים. ומכאן שנותנים לבעל מום שלושים יום נוספים על השנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003נולד לו\u0004 לבכור \u0003מום בחמשה עשר יום\u0004 האחרונים \u0003בתוך שנתו\u0004 — \u0003משלימין לו חמשה עשר יום אחר שנתו.\u0004 ונדייק: \u0003השלמה\u0004 לכדי שלושים יום — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מיהבא\u0004 \u0005[לתת לו]\u0006 שלושים ימים נוספים לאחר שנתו — \u0003לא.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003ר' אלעזר.\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003השוחט\u0004 תחילה \u0003את הבכור ו\u0004רק לאחר מכן \u0003מראה את מומו\u0004 למומחה למומי הבכור, והרי זה מום — \u0003ר' יהודה מתיר\u0004 את הבכור לכהן. \u0003ר' מאיר אומר: הואיל ונשחט\u0004 הבכור \u0003שלא על פי מומחה\u0004 — \u0003אסור\u0004 בהנאה. \u0003מי שאינו מומחה\u0004 להכיר במומי בכור \u0003ורואה את הבכור,\u0004 ואמר שמום זה קבוע, \u0003ונשחט\u0004 הבכור \u0003על פיו,\u0004 הואיל ולא נשחט הבכור בהיתר — \u0003הרי זה יקבר,\u0004 כדין בכור שמת, שהוא אסור בהנאה, \u0003וישלם\u0004 המתיר לכהן את דמיו של הבכור \u0003מביתו\u0004 (מנכסיו).","במחלוקת ר' יהודה ור' מאיר במשנתנו, לגבי בכור שהראו את מומו לחכם לאחר שכבר נשחט, \u0003אמר רבה בר בר חנה:\u0004 אם היה המום \u0003בדוקין\u0004 (קרומים, כתמים) \u0003שבעין\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 וגם ר' יהודה מודה שהבכור \u0003אסור, מפני שהן משתנין\u0004 על ידי המיתה, וייתכן כי לפני השחיטה היה זה מום עובר שאינו פוסל את הבכור. \u0003לא נחלקו אלא במומין שבגוף,\u0004 שאינם משתנים על ידי המיתה, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 על \u0003מומין שבגוף אטו\u0004 \u0005[משום]\u0006 \u0003דוקין שבעין, ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 על \u0003מומין שבגוף אטו\u0004 \u0005[משום]\u0006 \u0003דוקין שבעין.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003השוחט את הבכור ו\u0004אחר כך \u0003מראה את מומיו\u0004 — \u0003ר' יהודה אומר: בדוקין שבעין\u0004 — \u0003אסור, מפני שהן משתנין, במומין שבגוף\u0004 — \u0003מותר, מפני שאין משתנין. ר' מאיר אומר: אחד זה ואחד זה\u0004 — \u0003אסור, מפני שהן משתנין.\u0004 ויש לתהות על דברי ר' מאיר: \u0003מפני שהן משתנין סלקא דעתך\u0004 \u0005[עולה בדעתך]!\u0006 \u0003מומין שבגוף מי\u0004 \u0005[האם]\u0006 \u0003משתנין? אלא\u0004 צריכים לומר שהכוונה היא שהוא אוסר גם במומים שבגוף, \u0003מפני\u0004 דוקין שבעין, שהם מומים \u0003המשתנין.\u0004","\u0003אמר רב נחמן בר יצחק:\u0004"],["\u0003מתניתין נמי דיקא\u0004 \u0005[\u0006לשון \u0005משנתנו גם כן מדוייקת]\u0006 כהסבר זה, ששנינו בה: השוחט את הבכור ומראה את מומו, \u0003ר' מאיר אומר: הואיל ונשחט שלא על פי מומחה\u0004 — \u0003אסור. שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003קנסא קא קניס\u0004 \u0005[קנס קונס]\u0006 \u0003ר' מאיר,\u0004 על שלא הראהו למומחה, ולא אסרו מספק שמא השתנה המום לאחר מיתה, ובעצם אין זה מום. ומכאן שמדובר במומי הגוף שאינם משתנים, ואין זה אלא גזירה משום דוקין שבעין, שהם משתנים על ידי המיתה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","בענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: מה ששנינו בברייתא \u0003מפני\u0004 הדוקין שבעין \u0003המשתנין,\u0004 האם כוונתו — \u0003וכולהו משתני\u0004 \u0005[וכולם,\u0006 כל הדוקין שבעין, \u0005משתנים].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003איכא דמשתני ואיכא דלא משתני\u0004 \u0005[יש שמשתנים ויש שאינם משתנים]?\u0006","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 איזו מסקנה הלכתית \u0005יוצאת ממנה,\u0006 משאלה זו\u0005]\u0006 — \u0003לאכחושי סהדי\u0004 \u0005[להכחיש עדים],\u0006 שמעידים שמומים אלו היו בו בחייו, ולא נשתנו. \u0003אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003כולהו משתני\u0004 \u0005[כולם משתנים]\u0006 — \u0003שקרי נינהו\u0004 \u0005[שקרנים הם],\u0006 \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 כי \u0003איכא דמשתני ואיכא דלא משתני\u0004 \u0005[יש שמשתנים ויש שאינם משתנים]\u0006 — \u0003סמכינן עלייהו\u0004 \u0005[סומכים אנו עליהם].\u0006 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רבה בר בר חנה: שח\u0004 (סיפר) \u0003לי ר' יאשיה דמן אושא: בא ואראך בדוקין\u0004 שבעין \u0003שהן משתנים. מדקאמר ליה\u0004 \u0005[ממה שאמר לו]\u0006 \u0003\"בא ואראך\"\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא דמשתני ואיכא דלא משתני\u0004 \u0005[שיש שמשתנים ויש שאינם משתנים],\u0006 והראהו אותם שהם משתנים.","שנינו במשנה: \u0003מי שאינו מומחה\u0004 להכיר במומי הבכור ולהתירו, \u0003וראה את הבכור ונשחט על פיו\u0004 — \u0003הרי זה יקבר, וישלם\u0004 לכהן \u0003מביתו.\u0004 ושואלים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר ששנינו\u0006 בסוף משנתנו ב\u0005סתם]\u0006 \u0003כר' מאיר,\u0004 בתחילת המשנה, שאוסר את הבכור בכל מקרה שנשחט שלא על פי מומחה? ודוחים: לא, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן \u0003בדוקין שבעין,\u0004 שהם משתנים לאחר מיתה, \u0003ו\u0004אז הוא \u0003דברי הכל,\u0004 וגם לשיטת ר' יהודה.","ובענין תשלום זה ששנינו, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשהוא משלם\u0004 לכהן על הבכור שאיבד ממנו — \u0003משלם רביע\u0004 (רבע) מערכו של הבכור \u0003ל\u0004בהמה \u0003דקה, ומחצה\u0004 מערכו של הבכור \u0003לגסה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר רב פפא: זה,\u0004 בבהמה גסה — \u0003הפסד\u0004 הכהן \u0003מרובה,\u0004 שהשקיע הרבה בגידולה, \u0003וזה,\u0004 בבהמה דקה — \u0003הפסד מועט.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שהולכים לפי ההפסד — \u0003לפום פסידא לישלם\u0004 \u0005[לפי ההפסד ישלם],\u0006 ומדוע לא ישלם מחצית לדקה גם כן? \u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בר איקא: משום גזירת מגדלי בהמה דקה נגעו בה,\u0004 שגזרו חכמים שלא לגדל בהמה דקה בארץ ישראל.","דיין ש\u0003דן את הדין\u0004 וטעה, כגון ש\u0003זיכה\u0004 בדיני ממונות \u0003את החייב וחייב את הזכאי,\u0004 או שבאה לפניו שאלה בדיני טומאה וטהרה, ו\u0003טימא את הטהור\u0004 או \u0003טיהר את הטמא\u0004 — \u0003מה שעשה עשוי,\u0004 כלומר, הדין שדן — קיים, \u0003וישלם\u0004 את ההפסד מביתו. ואם היה מומחה לבית דין, חכם שנטל רשות מבית דין לדון — \u0003פטור מלשלם.\u0004","שנינו במשנתנו שדיין שטעה בדינו צריך לשלם על הנזק שנגרם על ידי כך. ושואלים: \u0003לימא תנן סתמא\u0004 \u0005[האם לומר ששנינו\u0006 במשנתנו ב\u0005סתם]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר, דדאין דינא דגרמי\u0004 \u0005[ש\u0006הוא \u0005דן דין של גורמים],\u0006 שמחייב אדם על נזק שהוא גורם, גם אם אינו עושה מעשה בידו? \u0003אמר ר' אילעא אמר רב:\u0004 יש לפרש משנתנו גם למי שאינו דן \"דינא דגרמי\" ו\u0003כגון\u0004 באופן \u0003שנשא ונתן ביד,\u0004 כלומר, שהוא בעצמו לקח חפץ מאדם אחד ונתן לשני, ואם כן עשה מעשה.","ושואלים: וכיצד יכול אתה להסביר כך את משנתנו? \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה ששנינו ש\u0003חייב את הזכאי\u0004 — \u0003כגון שנשא ונתן ביד,\u0004 שלקח מן הזכאי ונתן לידו של החייב. \u0003אלא זיכה את החייב היכי דמי\u0004 \u0005[כיצד מדובר]?\u0006 \u0003אי דאמר ליה\u0004 \u0005[אם שאמר לו]\u0006 \u0003\"פטור אתה\"\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נשא ונתן ביד\u0004 שום דבר! \u0003אמר רבינא: כגון שהיה לו\u0004 למלוה \u0003משכון\u0004 של הלווה בידו, שעל ידו יכול היה להיפרע מן הלווה, \u0003ונטלו\u0004 הדיין בידיו \u0003הימנו\u0004 (ממנו), ונתנו ללווה בחזרה שלא כדין.","וכן מה ששנינו: \u0003טימא את הטהור\u0004 — \u0003דאגע בהו\u0004 \u0005[שהגיע בהם]\u0006 \u0003שרץ\u0004 בפירות, שהיה ספק אם הם טמאים, כדי להבטיח שינהגו בהם דין טומאה. וכיוצא בזה מה ששנינו: \u0003טיהר את הטמא\u0004 — \u0003שעירבן\u0004 את הפירות שהיה בהם ספק \u0003עם פירותיו\u0004 הטהורים של השואל, להראות שטהורים הם, ואחר כך הוכרע על פי חכם מומחה שהם טמאים, ואם כן עשה נזק בידיו ממש.","שנינו במשנה הקודמת, שדיין שהוא מומחה לבית דין וטעה — פטור מלשלם. ומוסיפים: \u0003ומעשה בפרה שניטלה האם\u0004 (רחם) \u0003שלה,\u0004 ובא הדבר לפני ר' טרפון, וסבר שהיא טריפה, ואסורה באכילה לבני אדם, \u0003והאכילה ר' טרפון לכלבים,\u0004 כלומר, עשו כן על פי פסיקתו. \u0003ובא מעשה\u0004 זה \u0003לפני חכמים\u0004 בבית הדין \u0003ביבנה, והתירוה\u0004 משום טריפה,","\u0003ו\u0004טעמם, שהרי \u0003אמר תודוס הרופא: אין פרה וחזירה יוצאה מאלכסנדריא של מצרים שאין חותכין האם שלה\u0004 קודם שתצא משם, \u0003בשביל שלא תלד\u0004 במקום אחר. שהיו להם גזעים מובחרים של בהמות, שמחירם גבוה, ולא רצו שיתרבו במקומות אחרים. והואיל והפרות הללו חיות זמן רב לאחר מכן, הרי זה מוכיח שאינן נעשות טריפה על ידי כריתת הרחם.","\u0003אמר ר' טרפון\u0004 על עצמו: \u0003הלכה חמורך טרפון,\u0004 כלומר, הפסדת את חמורך, שתצטרך למוכרו כדי לשלם עבור הפרה שהטרפת! \u0003אמר לו ר' עקיבא: ר' טרפון, אתה מומחה לבית דין, וכל המומחה לבית דין פטור מלשלם.\u0004","ושואלים על דברי ר' עקיבא: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 שר' טרפון פטור, משום ש\u0003טעה בדבר משנה,\u0004 שהרי שנינו במשנה שבהמה שניטלה האם שלה אינה טריפה, \u0003ו\u0004חכם ש\u0003טעה בדבר משנה\u0004 — הרי הוא \u0003חוזר\u0004 בו, כלומר, אין תוקף למה שהורה. ומי שהאכילה לכלבים — מתוקף הוראה בטילה עשה!","ומשיבים: \u0003חדא ועוד קאמר\u0004 \u0005[\u0006טענה \u0005אחת ועוד\u0006 אחת \u0005הוא אומר]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — ש\u0003טעה בדבר משנה\u0004 \u0003חוזר. ועוד, אי נמי\u0004 \u0005[אם גם כן]\u0006 \u0003בשיקול הדעת טעיתה,\u0004 ולא בדבר משנה, ובמקרה זה אין הדין חוזר — בכל זאת \u0003מומחה לבית דין אתה, וכל המומחה לבית דין פטור מלשלם.\u0004","\u0003הנוטל שכר להיות רואה את הבכורות,\u0004 אם יש בהם מום, ולהתירם — \u0003אין שוחטין על פיו\u0004 את הבכור, \u0003אלא אם כן היה מומחה\u0004"],["\u0003כאילא\u0004 שהיה \u0003ביבנה, שהתירו לו ביבנה חכמים להיות נוטל ארבע איסרות ל\u0004בדיקת \u0003בהמה דקה, וששה\u0004 איסרות \u0003ל\u0004בדיקת \u0003גסה,\u0004 על תנאי שיטלם \u0003בין\u0004 אם נמצא הבכור \u0003תם ובין\u0004 שהוא \u0003בעל מום.\u0004","שנינו שאילא היה נוטל ארבע איסרות על בדיקת בהמה דקה, וששה איסרות על הגסה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהוא מחלק במחיר בין דקה לגסה? ומשיבים: \u0003האי נפיש טירחיה\u0004 \u0005[זה,\u0006 בכור בהמה גסה, \u0005טרחתו מרובה]\u0006 לבודקו, שצריך להשליכו לארץ ולכופתו, \u0003והאי לא נפיש טירחיה\u0004 \u0005[וזה,\u0006 בכור בהמה דקה, \u0005אין טרחתו מרובה].\u0006","שנינו שהיה אילא נוטל שכרו, \u0003בין\u0004 אם נמצא הבכור \u0003תם, ובין\u0004 אם נמצא שהוא \u0003בעל מום.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בעל מום\u0004 מובן מדוע נוטל שכר — \u0003משום דקא שרי ליה\u0004 \u0005[שהוא מתיר לו]\u0006 את הבכור בשחיטה, \u0003אלא\u0004 אם נמצא הבכור \u0003תם אמאי\u0004 \u0005[מדוע]\u0006 היה נוטל שכר? ומשיבים: ש\u0003אם כן,\u0004 שרק על בעלי מום היה נוטל שכר, \u0003אתי למיחשדיה\u0004 \u0005[יבואו לחשוד אותו],\u0006 \u0003ואמרי\u0004 \u0005[ויאמרו]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 הבכור שאמר שהוא \u0003בעל מום,\u0004 באמת \u0003תם הוא, והאי דקא שרי ליה\u0004 \u0005[וזה שהוא מתיר אותו]\u0006 — \u0003משום אגרא\u0004 \u0005[השכר]\u0006 התירו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שחוששים לחשדם של אנשים, הרי אם יאמר עליו שהוא \u0003תם נמי אמרי\u0004 \u0005[גם כן יאמרו]:\u0006 \u0003בעל מום הוא, והאי דלא קשרי ליה\u0004 \u0005[וזה שאינו מתיר אותו]\u0006 הרי זה משום שהוא \u0003סבר\u0004 \u0005[סבור]\u0006 כי מוטב לו שלא להתירו עכשיו, \u0003כי היכי דלשקול אגריה זימנא אחריתי\u0004 \u0005[כדי שיטול שכרו פעם אחרת,\u0006 נוספת\u0005]\u0006 כשיביאו אותו שוב לראות אם יש בו מום! ומשיבים: \u0003חד זימנא תקינו ליה רבנן\u0004 \u0005[פעם אחת תיקנו לו חכמים]\u0006 ליטול שכר על כל בכור, \u0003תרי זימני לא תקינו ליה רבנן\u0004 \u0005[שתי פעמים לא תיקנו לו חכמים]\u0006 שיטול שכר, ולכן אין מקום לחשד כזה.","דיין \u0003הנוטל שכרו לדון\u0004 — \u0003דיניו בטילים,\u0004 וכן הנוטל שכר \u0003להעיד\u0004 — \u0003עדותיו בטילין.\u0004 הנוטל שכר \u0003להזות\u0004 ממי פרה אדומה על טמא מת, או על מנת \u0003לקדש\u0004 מתחילה את המים הללו באפר הפרה — \u0003מימיו\u0004 שהיזה על הטמא, נחשבים ל\u0003מי מערה,\u0004 כלומר, סתם מים, ו\u0003אפרו\u0004 שקידש בו את המים, נחשב כ\u0003אפר מקלה,\u0004 סתם אפר של שריפה, שלא הועיל כלום.","ומוסיפים: אף שאסור לדיין וכו' ליטול שכר, מכל מקום \u0003אם היה כהן,\u0004 ומי שהוצרך לו היה \u0003מטמאהו מתרומתו,\u0004 שהוצרך הכהן ליטמא לשם כך, ולכן אינו יכול לאכול ולהשתמש בתרומה — זה שהוצרך לו \u0003מאכילו ומשקו וסכו,\u0004 נותן לו מאכל ומשקה ושמן לסוך את גופו מן החולין, עד שיטהר. \u0003ו\u0004כן \u0003אם היה\u0004 הדיין, או העד, \u0003זקן\u0004 — זה הנצרך לו \u0003מרכיבו על החמור. ו\u0004כן, למרות שאינו רשאי ליטול שכר, מכל מקום הנצרך לו \u0003נותן לו שכרו כפועל,\u0004 שהרי הוצרך ליבטל ממלאכתו לשם כך.","שנינו כי הנוטל שכרו לדון — דיניו בטלים. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאסור לדיין לדון ולהורות בשכר? \u0003אמר רב יהודה אמר רב, דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בדברי משה לעם: \u0003\"ראה למדתי אתכם\u0004 חקים ומשפטים כאשר צוני ה' אלהי, לעשות כן\" וכו' (דברים ד, ה), \u0003מה אני\u0004 למדתי \u0003בחנם\u0004 מפי הקדוש ברוך הוא — אף אתם למדתם ממני \u0003בחנם,\u0004 וכן תעשו לדורות. ומעירים, \u0003תניא\u0004","\u0003נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 על פסוק זה עצמו: \u0003\"כאשר צוני ה' אלהי\", מה אני\u0004 למדתי מפי ה' \u0003בחנם\u0004 — \u0003אף אתם\u0004 למדתם ממני \u0003בחנם. ומנין שאם לא מצא\u0004 רב ללמוד ממנו \u0003בחנם, שילמד\u0004 אפילו \u0003בשכר? תלמוד לומר: \"אמת קנה\"\u0004 (משלי כג, כג). \u0003ומנין שלא יאמר: כשם שלמדתיה בשכר כך אלמדנה\u0004 לאחרים \u0003בשכר? תלמוד לומר: \"אמת קנה ואל תמכר\"\u0004 (משלי כג, כג).","שנינו במשנה כי הנוטל שכר כדי \u0003להזות ולקדש\u0004 — \u0003מימיו מי מערה, אפרו אפר מקלה,\u0004 הרי שאינו רשאי ליהנות מהם. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 על כך ממה ששנינו במשנה: \u0003המקדש\u0004 אשה \u0003במי חטאת\u0004 או \u0003באפר חטאת\u0004 — \u0003הרי זו מקודשת, אף על פי שהוא\u0004 המקדש \u0003ישראל.\u0004 הרי שרשאי ליהנות בהם!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003כאן\u0004 כשהוא נוטל שכר — \u0003בשכר הבאה\u0004 של המים, \u0003ומלוי\u0004 המים בכלי, שזוהי טירחה סתם, ועליה יכול לקבל שכר. \u0003כאן\u0004 שאינו רשאי ליטול שכר — \u0003בשכר הזאה\u0004 על הטמא, \u0003וקידוש\u0004 המים על ידי האפר.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 הדבר \u0005גם כן],\u0006 \u0003דקתני הכא\u0004 \u0005[שהוא שונה כאן]\u0006 במשנתנו: הנוטל שכרו \u0003להזות ולקדש, והתם קתני\u0004 \u0005[ו\u0006אילו \u0005שם הוא שונה]\u0006 בלשון כללית: \u0003המקדש במי חטאת ובאפר חטאת,\u0004 ואינו מזכיר הזאה וקידוש. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003אם היה\u0004 הדיין או העד וכו' \u0003כהן,\u0004 וזה המוליכו כדי לדון היה \u0003מטמאהו מתרומתו כו'.\u0004 ושואלים: \u0003איהו גופיה היכי אזיל\u0004 \u0005[הוא עצמו,\u0006 הכהן, \u0005כיצד הוא הולך לשם,\u0006 למקום הטומאה\u0005]?\u0006 והרי נאסר על הכהן להיטמא!","ומשיבים: מדובר שהוא הולך \u0003לבית הפרס,\u0004 שדה שנחרש בה קבר, שטומאתו היא רק \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולא נאסר על הכהן ללכת שם. וכפי ש\u0003אמר רב יהודה אמר רב\u0004 בענין ההולך לעשות פסחו, שצריך לעשותו בטהרה: \u0003מנפח אדם בית הפרס,\u0004 כלומר, נופח בפיו כדי לפזר את העפר, כדי שיראה שאין שום עצם שייטמא בה מן התורה, \u0003והולך\u0004 במקום שבדק. ומכל מקום, נטמא הכהן ואסור לאכול תרומה."],["\u0003ורב יהודה בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה אמר:\u0004 \u0003בית הפרס שנידש,\u0004 שהלכו בו אנשים ודשוהו ברגליהם — \u0003טהור\u0004 למי שצריך לעשות את הפסח, שאין חוששים שנותרה שם עצם בשיעור שעורה, שמטמאת. אבל אין הכהן שעבר שם רשאי לאכול תרומה.","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 מדובר במשנתנו כשהכהן הוצרך להיטמא \u0003בשאר טומאות\u0004 ולא בטומאת מת, כגון טומאת שרץ ונבילה, \u0003דלא מזהר עלייהו\u0004 \u0005[שאינו מוזהר עליהם],\u0006 שהרי אין הכהנים מוזהרים שלא ליטמא אלא בטומאת מת. ומכל מקום, גם אם נטמא בטומאה אחרת — הרי אינו יכול לאכול בתרומה.","שנינו במשנה: \u0003אם היה\u0004 הדיין או העד \u0003זקן,\u0004 הרי מי שנצרך לו \u0003מרכיבו על החמור,\u0004 ונותן לו שכרו כפועל. בפירוש דבר זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כפועל בטל,\u0004 כלומר, כפי השכר שמוכן פועל ליטול כדי שיתבטל ממלאכתו. \u0003אמר אביי:\u0004 כוונת הדברים היא — \u0003כפועל בטל של אותה מלאכה\u0004 שממנה הוא בטל. שצריך להביא בחשבון את גודל הטירחה ואת גובה השכר שיש לו במלאכתו הרגילה.","\u0003החשוד על הבכורות,\u0004 לשוחטם באיסור ולמכור את בשרם — \u0003אין לוקחין\u0004 (קונים) \u0003ממנו\u0004 בשר, שמא בשר בכור הוא. ואפילו הוא טוען שהוא \u0003בשר צבאים.\u0004 \u0003ולא\u0004 קונים ממנו \u0003עורות שאינן עבודים\u0004 (מעובדים). \u0003ר' אליעזר אומר: לוקחין ממנו עורות של נקבה,\u0004 שבודאי אין זה עור של בכור, שאין בכור אלא זכר. \u0003ואין לוקחין ממנו צמר מלובן\u0004 (מכובס) \u0003וצואי\u0004 (מלוכלך), \u0003אבל לוקחין ממנו טוי\u0004 (חוטים טוויים) \u0003ו\u0004כל שכן \u0003בגדים.\u0004","שנינו במשנה שאין קונים מן החשוד על הבכורות \u0003בשר צבאים.\u0004 ומסבירים: דווקא בשר צבאים, משום \u0003דמיחלף\u0004 \u0005[שמתחלף]\u0006 \u0003ב\u0004בשר של \u0003עגלה\u0004 \u0005[עגל],\u0006 שבשרם דומה.","ועוד שנינו: \u0003ולא\u0004 לוקחים ממנו \u0003עורות שאינן עבודים.\u0004 ויש לדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 עורות \u0003עבודים זבנינן\u0004 \u0005[קונים אנו]\u0006 מן החשוד. והטעם הוא: שכן \u0003אם איתא\u0004 \u0005[אמנם]\u0006 עור של \u0003בכור הוה\u0004 \u0005[היה\u0006 זה\u0005]\u0006 — \u0003לא הוה טרח ביה\u0004 \u0005[היה טורח בו\u0006 לעבד אותו\u0005],\u0006 \u0003סבר\u0004 \u0005[\u0006שהיה \u0005סבור]:\u0006 \u0003אי שמעו ביה רבנן מפסדו לי מינאי\u0004 \u0005[אם ישמעו בו חכמים\u0006 שבכור הוא \u0005יפסידו לי אותו ממני].\u0006","ועוד שנינו: \u0003ר' אליעזר אומר לוקחין ממנו,\u0004 מן החשוד על הבכורות, \u0003עורות של נקבה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מידע ידיע\u0004 \u0005[\u0006הדבר \u0005ידוע]\u0006 שהוא עור של נקבה, שחסר בו העור של אבר הזכרות, ואם כן אין מה לחשוש.","ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 שאינו מחלק בין עור לעור, מה הוא סבור? ומשיבים: \u0003אם כן,\u0004 שקונים ממנו עורות של נקבה — עורות של \u0003זכר נמי\u0004 \u0005[גם כן]\u0006 יכול למכור, כשהוא \u0003חייק לזכרותיה\u0004 \u0005[חותך את עור הזכרות שלו],\u0006 \u0003ואמר\u0004 \u0005[אומר]\u0006 שחלק זה \u0003עכברים אכלוה\u0004 \u0005[אכלו אותו]!\u0006 ואומרים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אליעזר\u0005],\u0006 מה הוא משיב לכך? \u0003בי עכברים מידע ידיע\u0004 \u0005[מקום ש\u0006אכלוהו \u0005עכברים ידוע\u0006 וניכר\u0005],\u0006 ואינו יכול לרמות.","ועוד שנינו במשנה: \u0003ואין לוקחין ממנו,\u0004 מן החשוד על הבכורות, \u0003צמר מלובן\u0004 (מכובס) \u0003וצואי\u0004 (מלוכלך). ותמהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אמרת ש\u0003צמר מלובן לא זבנינן\u0004 \u0005[אין אנו קונים]\u0006 ממנו, למרות שיש בו טורח, ויש להניח שאם היה של בכור לא היה טורח בו — \u0003צואי מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין קונים ממנו? \u0003אלא,\u0004 יש להבין כי \u0003חדא קתני\u0004 \u0005[\u0006דבר \u0005אחד שונה],\u0006 והכוונה היא ל\u0003צמר מלובן מצואתו,\u0004 שאפילו צמר מלובן אין קונים ממנו.","ועוד שנינו: \u0003אבל לוקחין ממנו טוי\u0004 (חוטים טוויים) \u0003ובגדים.\u0004 וגם כאן שואלים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003טוי זבנינן\u0004 \u0005[אנו קונים]\u0006 ממנו, משום שאם צמר של בכור הוא לא היה משקיע בטווייתו — \u0003בגדים,\u0004 שיש בעשייתם טורח מרובה יותר, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שקונים? ומשיבים: \u0003מאי\u0004 \u0005[מהם]\u0006 \u0003בגדים\u0004 שהוזכרו כאן? \u0003נמטי\u0004 \u0005[לבדים],\u0006 שאינם טוויים, לומר שלמרות שיש בהם פחות טורח — קונים ממנו.","\u0003החשוד על השביעית\u0004 לזרוע או לסחור בפירות שמיטה — \u0003אין לוקחין ממנו פשתן, ואפילו סרק\u0004 (פשתן סרוק) שהושקעה בו מלאכה וטורח. \u0003אבל לוקחין מהם,\u0004 מהחשודים על השביעית, \u0003טוי\u0004 (חוטי פשתן טוויים) \u0003ואריג\u0004 העשוי מפשתן, שיש בעשייתם השקעה יתירה, שאין אדם טורח בדבר אסור שמא יפסידוהו.","על מה ששנינו שאין לוקחים מהם טוי ואריג שואלים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אמרת ש\u0003טוי זבנינן\u0004 \u0005[קונים אנו]\u0006 ממנו, ואין אנו חוששים שהוא טורח בדבר איסור, מפני שהוא חושש שהוא עלול להפסידו, \u0003אריג\u0004 שיש בו טירחה מרובה יותר, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמותר לקנות ממנו? ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אריג?\u0004 לא אריג ממש, אלא \u0003תיכי\u0004 \u0005[גדילים]\u0006 שקולעים מפשתן שאינו טווי.","\u0003החשוד להיות מוכר תרומה לשום חולין\u0004 — \u0003אין לוקחין\u0004 \u0003ממנו אפילו מים ומלח,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר: כל\u0004 דבר \u0003שיש בו זיקת\u0004 שייכות ל\u0003תרומה ומעשרות\u0004 \u0003אין לוקחין ממנו,\u0004 אבל דבר שאין בו שום שייכות לתרומה ומעשרות — אפשר לקנות.","ושואלים: מה שאמר ר' שמעון \"כל שיש בו זיקת תרומה ומעשרות\", \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005את מה]?\u0006 איזה דבר הוא בא להוסיף? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0005קרבי דגים, שהם בעצמם ודאי אינם חייבים בתרומה, אלא\u0006 \u0003דמערבי בהו\u0004 \u0005[שמערבים בהם]\u0006 \u0003שמן זית.\u0004","מסופר, \u0003ההוא טבחא דהוה חשוד לזבוני\u0004 \u0005[טבח,\u0006 קצב \u0005אחד שהיה חשוד למכור]\u0006"],["\u0003תרבא דאטמא\u0004 \u0005[חלב של ירך],\u0006 שהוא אסור באכילה, \u0003במר דכנתא\u0004 \u0005[במקום\u0006 שומן \u0005של מעיים],\u0006 שמותר באכילה, \u0003קנסיה\u0004 \u0005[קנס אותו]\u0006 \u0003רבא לזבוני\u0004 \u0005[\u0006שלא \u0005למכור]\u0006 \u0003אפילו אמגוזי\u0004 \u0005[אגוזים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר? \u0003כ\u0004דעת \u0003ר' יהודה\u0004 במשנתנו, שהרי ר' שמעון אוסר לקנות ממנו רק מה שיש בו שייכות לדבר שהוא חשוד עליו. אבל \u0003אי\u0004 \u0005[אם]\u0006 אתה הולך \u0003כ\u0004דעת \u0003ר' יהודה\u0004 — \u0003אפילו מים ומלח נמי\u0004 \u0005[גם כן]\u0006 לא ימכור!","השיב לו רבא: \u0003לעולם\u0004 פוסק אני כ\u0003ר' שמעון,\u0004 וגם כאן \u0003באיסורא דגופיה קנסינן ליה\u0004 \u0005[באיסור עצמו,\u0006 שהוא חשוד עליו, \u0005קונסים אנו אותו],\u0006 שכן \u0003סתם דרדקי גרו באמגוזי\u0004 \u0005[סתם ילדים להוטים אחרי אגוזים],\u0006 \u0003ו\u0004אותו אדם \u0003אזיל ומשבש לבני טבחי\u0004 \u0005[הולך ומטעה את בני הקצבים],\u0006 \u0003וגרי להו באמגוזי\u0004 \u0005[ומפתה אותם באגוזים],\u0006 \u0003ומייתו ליה תרבא דאטמא\u0004 \u0005[ומביאים לו\u0006 מאבותיהם \u0005חלב של ירך],\u0006 \u0003ומזבין ליה במר דכנתא\u0004 \u0005[ומוכר אותו במקום\u0006 חלב \u0005של מעיים].\u0006","\u0003החשוד על השביעית\u0004 — \u0003אינו חשוד על המעשרות,\u0004 ומצד שני, \u0003החשוד על המעשרות\u0004 — \u0003אינו חשוד על השביעית.\u0004 אבל \u0003החשוד על זה ועל זה,\u0004 כלומר, או על שביעית או על המעשרות — \u0003חשוד\u0004 גם \u0003על הטהרות,\u0004 למכור אוכלים טמאים כאילו היו טהורים. \u0003ויש שהוא חשוד על הטהרות ואינו חשוד לא על זה ולא על זה,\u0004 לא על השביעית ולא על המעשרות. ועוד מוסיפים: \u0003זה הכלל\u0004 בעניינים אלו: כל אדם \u0003החשוד על דבר\u0004 מסויים לעבור בו עבירה — \u0003לא דנו,\u0004 הריהו פסול לדון בענין זה, \u0003ולא מעידו,\u0004 אינו מעיד עליו.","שנינו במשנה שהחשוד על השביעית אינו חשוד על המעשרות. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן \u0003שביעית לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003חומה,\u0004 אין צריכים לאכול אותה לפנים מחומת ירושלים. אבל \u0003מעשר\u0004 שני, \u0003כיון דבעי\u0004 \u0005[שצריך]\u0006 \u0003חומה\u0004 — יש לומר כי \u0003חמיר ליה\u0004 \u0005[חמור לו\u0006 יותר\u0005],\u0006 שיש בו קדושה יתירה, ואינו חשוד על כך.","ועוד שנינו: \u0003החשוד על המעשר\u0004 אינו חשוד על השביעית. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מעשר\u0004 שני \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003פדיון,\u0004 ניתן לפדותו, ואז הוא מותר לגמרי במכירה. ואילו \u0003שביעית, כיון דקא מיתסרא ליה\u0004 \u0005[שהיא נאסרת לו]\u0006 בסחורה לעולם, \u0003ולית ליה\u0004 \u0005[ואין לה]\u0006 \u0003פדיון\u0004 — \u0003חמירא ליה\u0004 \u0005[חמורה לו\u0006 יותר\u0005].\u0006","ועוד שנינו: \u0003החשוד\u0004 או \u0003על זה\u0004 או \u0003על זה,\u0004 על השביעית או על המעשר — חשוד על הטהרות. ומסבירים: \u0003כיון דחשיד אדאורייתא\u0004 \u0005[ש\u0006הוא \u0005חשוד\u0006 לעבור \u0005על דברי תורה],\u0006 ששביעית ומעשר שני הריהם מן התורה — \u0003כל שכן שהוא\u0004 חשוד לעבור \u0003אדרבנן\u0004 \u0005[על דברי סופרים],\u0006 והרי אכילת חולין בטהרה אינה מצוה מן התורה, אלא תקנת חכמים.","ועוד שנינו: \u0003ויש חשוד על הטהרות\u0004 ואינו חשוד לא על השביעית ולא על המעשר. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003נהי אדרבנן חשיד\u0004 \u0005[אם אמנם על דברי חכמים הוא חשוד]\u0006 — \u0003אדאורייתא לא חשיד\u0004 \u0005[על דברי תורה אינו חשוד].\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים, מראים סתירה]\u0006 ממה ששנינו בברייתא: מי ש\u0003נאמן על הטהרות\u0004 — \u0003נאמן על שביעית.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003חשיד\u0004 \u0005[\u0006מי ש\u0005חשוד]\u0006 על הטהרות — \u0003חשיד\u0004 \u0005[חשוד]\u0006 גם על השביעית!","\u0003אמר ר' אילעי: מתניתין\u0004 \u0005[משנתנו]\u0006 האומרת שאינו חשוד — \u0003כשראינוהו שנוהג\u0004 ומחמיר בענין שביעית \u0003בצינעא בתוך ביתו,\u0004 ומשום כך אין מקום לחשד.","\u0003ר' ינאי בר' ישמעאל אמר:\u0004 בברייתא מדובר \u0003כגון דהוה חשיד לתרוייהו\u0004 \u0005[שהיה חשוד\u0006 קודם לכן \u0005על שניהם],\u0006 על טהרות ועל שביעית, \u0003ואתא קמי רבנן וקביל אתרוייהו\u0004 \u0005[ובא לפני חכמים וקיבל\u0006 על עצמו לשמור \u0005על שניהם],\u0006 \u0003והדר איחשד אחד מינייהו\u0004 \u0005[וחזר ונחשד על אחד מהם],\u0006 \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003מיגו דחשיד אהא\u0004 — \u0003חשיד נמי אאידך\u0004 \u0005[מתוך שהוא חשוד על זה\u0006 — \u0005חשוד גם כן על האחר],\u0006 אפילו היה זה איסור חמור יותר, שהרי רואים שאינו עומד בדיבורו.","ושבים לתחילת משנתנו, ששנינו: החשוד על השביעית — אינו חשוד על המעשר. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: זו,\u0004 משנתנו, היא דברי ר' עקיבא סתימתאה (שדבריו נאמרים פעמים רבות במשנה בסתם, בלא להזכיר את שמו), \u0003אבל חכמים אומרים:\u0004 מי ש\u0003חשוד על השביעית\u0004 — \u0003חשוד\u0004 גם \u0003על המעשר.\u0004","ומעירים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? \u0003ר' יהודה, דבאתריה\u0004 \u0005[שבמקומו]\u0006 של \u0003ר' יהודה שביעית חמירא להו\u0004 \u0005[\u0006היתה \u0005חמורה להם\u0006 במיוחד\u0005],\u0006 \u0003דההוא דהוה קרי ליה לחבריה\u0004 \u0005[שאחד קרא לו לחבירו]\u0006 בכינוי גנאי: \u0003\"דיירא בר דיירתא\"\u0004 \u0005[גר בן גיורת],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלה: \u0003תיתי לי\u0004 \u0005[יפה לי],\u0006 \u0003דלא אכלי\u0004 \u0005[שאיני אוכל]\u0006 \u0003פירות שביעית כוותך\u0004 \u0005[כמותך].\u0006 משמע שבאותו מקום היה זה עלבון חמור, ומי שאינו מקפיד שם על השביעית ודאי שאינו מקפיד על המעשר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את השמועה בלשון אחרת, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: זו,\u0004 משנתנו, דברי ר' עקיבא סתימתאה. \u0003אבל חכמים אומרים:\u0004 מי ש\u0003חשוד על המעשר\u0004 — \u0003חשוד על השביעית. ומאן\u0004 \u0005[ומי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? \u0003ר' מאיר היא,\u0004 ש\u0003אמר:\u0004 ה\u0003חשוד ל\u0004עבור על \u0003דבר אחד הוי\u0004 \u0005[הריהו]\u0006 \u0003חשוד ל\u0004עבור על \u0003כל התורה כולה,\u0004 וגם על דבר חמור יותר.","ומעירים: \u0003ר' יונה ור' ירמיה תלמידי ר' זעירא, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003ר' יונה ור' זעירא, תלמידי ר' יוחנן,\u0004 נחלקו באותו ענין, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אבל חכמים אומרים חשוד על השביעית\u0004 —"],["\u0003חשוד\u0004 גם \u0003על המעשר, ומאן\u0004 \u0005[ומי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? \u0003ר' יהודה,\u0004 ששביעית במקומו חמורה יותר, והחשוד על החמור — חשוד על הקל. \u0003וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר: החשוד על המעשר\u0004 — \u0003חשוד על השביעית, ומאן\u0004 \u0005[ומי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלו? \u0003ר' מאיר,\u0004 הסבור שחשוד לדבר אחד — חשוד לכל התורה כולה. והיכן נאמרו דברי ר' מאיר?","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עם הארץ שקיבל עליו דברי חבירות,\u0004 כלומר, קיבל על עצמו לנהוג בזהירות בכל הדברים שהחברים, המקפידים בענייני טומאה וטהרה, ובהפרשת תרומות ומעשרות, נזהרים בהם, וקיבלוהו חכמים להיות נאמן על כך, \u0003ו\u0004אולם לאחר מכן \u0003נחשד לדבר אחד,\u0004 שראו שהוא עובר עליו — \u0003נחשד\u0004 מאז \u0003לכל התורה כולה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: אינו נחשד אלא לאותו דבר בלבד,\u0004 ולא על דברים אחרים.","ועוד שנינו בברייתא: \u0003הגר שקיבל עליו דברי תורה\u0004 בזמן שנתגייר, \u0003אפילו נחשד\u0004 לאחר מכן \u0003לדבר אחד\u0004 מדברי תורה — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003חשוד לכל התורה כולה, והרי הוא כישראל משומד\u0004 (שהמיר דתו, שעובר באופן קבוע על דברי תורה). ומסבירים: מה שאמרנו שהריהו כישראל משומד, הרי \u0003נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 להלכה, \u0003דאי קדיש\u0004 \u0005[שאם\u0006 אותו גר \u0005מקדש אשה]\u0006 מישראל — \u0003קידושיו קידושין,\u0004 כלומר, קידושיו תופסים, ואשת איש היא. ואין אנו אומרים כי מכיון שהוא חשוד לכל התורה כולה — כאילו לא נתגייר, ואין הקידושין חלים.","ועוד בעניינים אלו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבא\u0004 לפני חכמים \u0003לקבל\u0004 על עצמו \u0003דברי חבירות,\u0004 \u0003חוץ מדבר אחד\u0004 שאינו רוצה לקבל על עצמו — \u0003אין מקבלין אותו,\u0004 ואין סומכים עליו גם על שאר דברים. וכן \u0003גוי שבא\u0004 להתגייר על מנת \u0003לקבל\u0004 עליו כל \u0003דברי תורה, חוץ מדבר אחד\u0004 — \u0003אין מקבלין אותו. ר' יוסי בר' יהודה אומר: אפילו\u0004 לא רצה לקבל עליו \u0003דקדוק אחד מדברי סופרים,\u0004 גם אז אין מקבלים אותו.","\u0003וכן בן לוי שבא\u0004 ומוכן \u0003לקבל דברי לויה,\u0004 כלומר, לעבוד את עבודת הלויים שבמקדש חוץ מדבר אחד, \u0003וכהן שבא\u0004 ומוכן \u0003לקבל דברי כהונה, חוץ מדבר אחד,\u0004 שלא רצה לקבל על עצמו — \u0003אין מקבלין אותו\u0004 כלל. ואף אין אותו כהן נוטל חלקו במתנות הכהונה, \u0003שנאמר: \"המקריב את דם השלמים\u0004 ואת החלב מבני אהרן, לו תהיה שוק הימין למנה\" (ויקרא ז, לג). כלומר, \u0003העבודה המסורה לבני אהרן,\u0004 להקריב את הדם ואת החלב וכו', \u0003כל כהן שאינו מודה בה\u0004 ומקבל אותה על עצמו — \u0003אין לו חלק בכהונה.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 עם הארץ \u0003הבא לקבל דברי חבירות,\u0004 ולהיחשב כחבר, \u0003אם ראינוהו\u0004 קודם לכן \u0003שנוהג\u0004 זהירות בטהרה ובהפרשת תרומות ומעשרות, \u0003בצינעה בתוך ביתו,\u0004 ולא רק למראית עין — \u0003מקבלין אותו\u0004 כחבר, \u0003ואחר כך מלמדין אותו\u0004 כיצד לנהוג בדיוק. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שלא ראינוהו נוהג כן מתחילה — קודם \u0003מלמדין אותו\u0004 מה יעשה, \u0003ואחר כך מקבלין אותו. ר' שמעון בן יוחי אומר: בין כך ובין כך,\u0004 גם אם לא ראינוהו נוהג כן מתחילה — \u0003מקבלין אותו, והוא למד כדרכו והולך,\u0004 כלומר, בתוך שהוא עושה את הדברים, הוא לומד מאחרים כיצד לנהוג.","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מקבלין\u0004 עם הארץ תחילה כנאמן \u0003לכנפים,\u0004 כלומר, לטהרת הידיים, לסמוך על כך שהוא נוטל ידיו, ואם נגע בטהרות — אין חוששים שנפסלו, \u0003ואחר כך מקבלין\u0004 אותו כנאמן \u0003ל\u0004ענייני \u0003טהרות\u0004 בכלל. \u0003ואם אמר: איני מקבל אלא לכנפים\u0004 — \u0003מקבלין אותו\u0004 לענין זה בלבד. אבל אם \u0003קיבל\u0004 על עצמו \u0003ל\u0004הקפיד ב\u0003טהרות ולא קיבל לכנפים,\u0004 שלא קיבל על עצמו ליטול ידיו, שדבר קל הוא — \u0003אף לטהרות לא קיבל,\u0004 ואין סומכים עליו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עד כמה מקבלין אותו?\u0004 כמה זמן יעבור עד שיתקבל כחבר גמור, ונסמוך עליו בענייני טהרה? \u0003בית שמאי אומרים: ל\u0004ענין טהרת \u0003משקין\u0004 — שלשים יום, לטהרת \u0003כסות\u0004 (הבגד), שהיו החברים מקפידים על טהרת כסותם — \u0003שנים עשר חודש. ובית הלל אומרים: אחד זה ואחד זה\u0004 — \u0003לשנים עשר חודש.\u0004","על נוסח הברייתא שואלים: \u0003אם כן, הוה ליה\u0004 \u0005[הרי זה]\u0006 אחד מהדברים שהם \u0003מקולי בית שמאי ומחומרי בית הלל,\u0004 שבית שמאי מקילים בהם ובית הלל מחמירים, והרי לא שנינו כן ברשימה שבמסכת עדיות! \u0003אלא,\u0004 כך צריך לשנות: \u0003בית הלל אומרים: אחד זה ואחד זה לשלשים\u0004 יום.","\u0003(סימן\u0004 להלכות הבאות: חבר, תלמיד, תכלת, מכס, חצר, גבאי, \u0003בעצמו).\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הבא לקבל\u0004 על עצמו \u0003דברי חבירות צריך לקבל\u0004 אותם \u0003בפני שלשה חבירים. ובניו ובני ביתו אינן צריכין לקבל\u0004 על עצמם חבירות בנפרד \u0003בפני שלשה חבירים,\u0004 אלא די במה שהוא עצמו קיבל בפניהם, ובני ביתו נגררים אחריו. \u0003רבן שמעון בן גמליאל אומר: אף בניו ובני ביתו צריכין לקבל בפני שלשה חבירים, לפי שאינו דומה חבר שקיבל\u0004 על עצמו במפורש ומרצונו, \u0003לבן חבר שקיבל\u0004 מחמת אביו, ואין לסמוך על כך.","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 עוד: \u0003הבא לקבל דברי חבירות\u0004 — \u0003צריך לקבל\u0004 אותם \u0003בפני שלשה חבירים, ואפילו תלמיד חכם\u0004 הבא לקבל דברי חבירות — \u0003צריך לקבל בפני שלשה חבירים. זקן,\u0004 שנסמך כחכם, \u0003ויושב בישיבה\u0004 ודן עם החכמים — \u0003אינו צריך לקבל בפני שלשה חבירים, ש\u0004אנו אומרים: \u0003כבר קיבל עליו\u0004 דברי חבירות \u0003משעה שישב\u0004 בישיבה. \u0003אבא שאול אומר: אף תלמיד חכם אינו צריך לקבל בפני שלשה חבירים. ולא עוד אלא שאחרים מקבלין\u0004 דברי חבירות \u0003לפניו,\u0004 אף על פי שהוא לא קיבלם על עצמו בפני שלושה.","\u0003אמר ר' יוחנן: בימי בנו של ר' חנינא בן אנטיגנוס נשנית משנה זו,\u0004 שתלמיד חכם צריך לקבל בפני שלושה חברים, כדי שיסמכו עליו כחבר. שכן מסופר, \u0003ר' יהודה ור' יוסי איסתפק להו מילתא\u0004 \u0005[נסתפק להם דבר]\u0006 \u0003ב\u0004הלכות \u0003טהרות, שדרו רבנן לגבי\u0004 \u0005[שלחו חכמים,\u0006 מתלמידיהם, \u0005אצל]\u0006 \u0003בנו של ר' חנינא בן אנטיגנוס,\u0004 וכך אמרו להם: \u0003אזילו אמרו ליה\u0004 \u0005[לכו ואמרו לו]:\u0006 \u0003לעיין\u0004 \u0005[שיעיין]\u0006 \u0003בה\u0004 אדוני, בבעיה זו. \u0003אשכחוה דקא טעין\u0004 \u0005[מצאו אותו,\u0006 אותם חכמים, \u0005שהוא טוען,\u0006 נושא\u0005]\u0006 \u0003טהרות.\u0004 ומתוך שחשש שיטמאום \u0003אותיב רבנן מדידיה לגבייהו\u0004 \u0005[הושיב חכמים משלו,\u0006 מתלמידיו, \u0005לידם]\u0006 ליד התלמידים שבאו לשאול, כדי להשגיח עליהם שלא יגעו בטהרות, \u0003וקאי איהו לעיוני בה\u0004 \u0005[ועמד הוא לעיין בה]\u0006 בבעיה זו.","\u0003אתו אמרי ליה\u0004 \u0005[באו\u0006 התלמידים \u0005ואמרו לו]\u0006 \u0003לר' יהודה ור' יוסי\u0004 שכך נהג בהם, כבעמי הארץ. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יהודה: אביו של זה\u0004 כלומר, ר' חנינא בן אנטיגנוס עצמו, \u0003ביזה תלמידי חכמים,\u0004 שכך היה נוהג שלא לסמוך עליהם בעניינים אלה, \u0003אף הוא מבזה תלמידי חכמים!\u0004","\u0003אמר לו ר' יוסי: כבוד זקן יהא מונח במקומו,\u0004 חכם הוא וראוי לכבוד. ואין זה משום שהוא מבזה תלמידי חכמים, \u0003אלא מיום שחרב בית המקדש נהגו כהנים סילסול\u0004 (מעלה) \u0003בעצמן, שאין מוסרין את הטהרות לכל אדם,\u0004 ולכן יפה עשה, שהוא כהן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חבר שמת\u0004 — \u0003אשתו ובניו ובני ביתו הרי הן בחזקתן,\u0004 והם נאמנים בדברי חבירות, \u0003עד שיחשדו,\u0004 שיתברר שאינם נאמנים. \u0003וכן חצר שמוכרין בה תכלת\u0004 לציצית — \u0003הרי היא בחזקתה,\u0004 שמוכרים בה תכלת ולא תחליף תכלת, שהוא זול יותר, \u0003עד שתיפסל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אשת עם הארץ שנשאת לחבר, וכן בתו של עם הארץ שנשאת לחבר, וכן עבדו של עם הארץ שנמכר לחבר\u0004 — \u0003כולן צריכין לקבל דברי חבירות בתחלה,\u0004 קודם שיהיו נאמנים, ואין סומכים על מה שנכנסו לרשותו. \u0003אבל אשת חבר שנשאת לעם הארץ, וכן בתו של חבר שנשאת לעם הארץ, וכן עבדו של חבר שנמכר לעם הארץ,\u0004 הואיל והיו מורגלים בדברי חבירות — \u0003אין\u0004 הם \u0003צריכין לקבל דברי חבירות בתחלה,\u0004 שבחזקת נאמנים הם.","\u0003ר' מאיר אומר:\u0004 לא כן, אלא \u0003אף הן צריכין לקבל עליהן דברי חבירות לכתחלה,\u0004 משום שמשבאו לרשות עם הארץ פעמים שהם משנים את מנהגם. וכן \u0003ר' שמעון בן אלעזר אומר משום\u0004 (משמו של) \u0003ר' מאיר: מעשה באשה אחת שנשאת לחבר והיתה קומעת\u0004 (קושרת) \u0003לו תפילין על ידו,\u0004 לאחר זמן \u0003נשאת לעם הארץ והיתה קושרת לו קשרי מוכס על ידו,\u0004 כלומר, היתה מסייעת לו בעניני המכס, שיש בהם ענייני גזלנות. משמע שאישה לפעמים הולכת אחר בעלה, ואין לסמוך על מה שנהגה מתחילה."],["ובענין עמי הארץ שקיבלו על עצמם דברי חבירות, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003וכולן שחזרו בהן\u0004 ממה שקיבלו על עצמם — \u0003אין מקבלין אותן\u0004 עוד \u0003עולמית,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם \u0003חזרו\u0004 בהם \u0003במטמוניות\u0004 (בסתר), אבל בפרהסיא המשיכו לנהוג כחברים — \u0003אין מקבלין אותן,\u0004 שהם חשודים בגניבת דעת. אבל אם חזרו בהם מחבירותם \u0003בפרהסיא\u0004 — \u0003מקבלין אותן,\u0004 שאין לחשוד שהם מרמים.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אם\u0004 כשקיבלו עליהם מתחילה דברי חבירות, \u0003עשו דבריהן\u0004 (דברי חבירות) גם \u0003במטמוניות,\u0004 הרי למרות שחזרו בהם וקלקלו — \u0003מקבלין אותן\u0004 עכשיו, אבל אם מתחילה עשו דברי חבירות רק \u0003בפרהסיא,\u0004 הרי אם חזרו וקלקלו — \u0003אין\u0004 חוזרים ו\u0003מקבלין אותן.\u0004 \u0003ר' שמעון ור' יהושע בן קרחה אומרים: בין כך ובין כך מקבלין אותן, משום שנאמר: \"שובו בנים שובבים\"\u0004 (ירמיהו ג, יד), שאפילו כאשר הם שובבים (חוטאים) יכולים הם לשוב. \u0003אמר ר' יצחק איש כפר עכו אמר ר' יוחנן: הלכה כאותו הזוג,\u0004 שלעולם מקבלים אותם.","","","","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו אומרים,\u0004 מי שהיה \u0003חבר ונעשה גבאי\u0004 (גובה מסים) של מלך, שהוא חשוד על הגזל — \u0003דוחין אותו מחבירתו,\u0004 וגם אם \u0003פירש\u0004 מהגבאות — \u0003אין מקבלין אותו\u0004 שוב. \u0003חזרו לומר\u0004 לאחר מכן: אם \u0003פירש\u0004 — \u0003הרי הוא ככל אדם,\u0004 ומקבלים אותו. ובענין זה מסופר, \u0003רב הונא בר חייא איצטריכא ליה שעתא\u0004 \u0005[הוצרכה לו השעה],\u0006 שהיו חכמים צריכים אותו, \u0003הוה עייל גביה\u0004 \u0005[היו נכנסים אצלו]\u0006 \u0003רבה ורב יוסף וארבע מאה זוגא דרבנן\u0004 \u0005[וארבע מאות זוגות של חכמים,\u0006 תלמידים, איתם\u0005].\u0006 \u0003שמע דאתו\u0004 \u0005[\u0006כאשר היה \u0005שומע שהם באים]\u0006 היה עושה להם כבוד גדול, \u0003קטיר להו ארבע מאה תכתקי\u0004 \u0005[\u0006היה \u0005קושר,\u0006 מתקין, \u0005להם ארבע מאות כסאות]\u0006 לכבודם. \u0003לסוף שמעו\u0004 חכמים ש\u0003נעשה גבאי\u0004 של המלכות. \u0003שלחו ליה\u0004 \u0005[לו]\u0006 החכמים: \u0003זיל לחשיבותיה זיל לקדמותיה\u0004 \u0005[לך לחשיבותך,\u0006 שבחרת להתמנות לגבאי, וגם \u0005לך לקדמותך],\u0006 למה שהיית בתחילה, ששוב איננו נצרכים לך. \u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003הדרי בי\u0004 \u0005[חוזר אני בי]\u0006 מן הגבאות. \u0003רב יוסף לא אזל\u0004 \u0005[הלך\u0006 אליו\u0005],\u0006 \u0003רבה אזל\u0004 \u0005[הלך]. וכך הסבירו את נימוקיהם,\u0006 \u0003רב יוסף אמר:\u0004 הרי \u0003תנינא\u0004 \u0005[שנינו],\u0006 חבר ונעשה גבאי, גם אם \u0003פירש\u0004 מגבאותו — \u0003אין מקבלין אותו; רבה אמר:\u0004 הרי \u0003תנינא\u0004 \u0005[שנינו],\u0006 \u0003חזרו לומר: פירש\u0004 — \u0003הרי הוא ככל אדם,\u0004 ומקבלים אותו. ועוד בענין נאמנות, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל הבכורות אדם רואה\u0004 אם יש בהם מום ומתירם לשחיטה, \u0003חוץ מ\u0004בכורות \u0003של עצמו,\u0004 מפני שהוא נוגע בדבר. \u0003ו\u0004אולם \u0003רואה\u0004 אדם \u0003את קדשיו,\u0004 שאם הקדיש בהמות — יכול הוא בעצמו לראות אם נפל בהן מום, ולפדותם. \u0003ו\u0004כן רואה אדם \u0003את מעשרותיו\u0004 (מעשר בהמה שלו), ויכול להחליט שהם פסולים, ואינו צריך לעלות ולהקריבם במקדש. \u0003ו\u0004כן \u0003נשאל\u0004 אדם \u0003על טהרותיו\u0004 של עצמו, שאם היתה בהם שאלה של טומאה, יכול הוא לפסוק שטהורים הם, ואינו חשוד לומר על טמא שהוא טהור. ודנים בפרטי ברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל הבכורות אדם רואה חוץ משל עצמו.\u0004 ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 באיזה מקרה מדובר? \u0003אילימא בחד\u0004 \u0005[אם תאמר ב\u0006אדם \u0005אחד]\u0006 שרואה את המום — וכי יחיד \u0003מי מהימן\u0004 \u0005[האם\u0006 הוא \u0005נאמן]\u0006 להתיר בכורות? והלוא שנינו (להלן לו,ב) שאין מתירים בכור אלא על פי שלושה אנשים! \u0003אלא\u0004 ודאי מדובר פה \u0003בתלתא\u0004 \u0005[בשלושה]\u0006 שרואים את הבכור, ואחד מן השלושה הוא בעליו. ואולם על כך יש לתמוה: שלושה שדנו יחד \u0003מי חשידי\u0004 \u0005[האם\u0006 הם \u0005חשודים]\u0006 כשאחד מהם נוגע בדבר? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 חכם שאשה \u0003מיאנה\u0004 בבעלה בפניו, \u0003או שחלצה\u0004 ליבם \u0003בפניו\u0004 — \u0003ישאנה,\u0004 ואין חוששים שהתיר לה למאן או לחלוץ מפני שהוא נוגע בדבר, ורוצה לשאת אותה לאשה. \u0003מפני שהוא\u0004 חבר \u0003בית דין,\u0004 שהרי יש שם עוד שני דיינים!","ומשיבים: \u0003לעולם\u0004 מדובר כאן \u0003בחד\u0004 \u0005[ב\u0006דיין \u0005אחד],\u0006 \u0003וכדאמר\u0004 \u0005[וכמו שאמר]\u0006 \u0003רב חסדא\u0004 שכך \u0003אמר ר' יוחנן\u0004 בענין אחר, שמדובר \u0003ביחיד מומחה\u0004 שרשאי לדון לבדו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ביחיד מומחה,\u0004 שהוא רשאי להתיר בכור לבדו. ומכל מקום אינו נאמן לראות בכורות שלו, משום שהוא נוגע בדבר. וממשיכים לברר את פרטי הדינים בברייתא זו.","נאמר לגבי חכם: \u0003ורואה את קדשיו,\u0004 ומחליט שיש בהם מום. ומסבירים: מדוע אין חושדים בו? משום \u0003דאי בעי\u0004 \u0005[שאם\u0006 היה \u0005רוצה]\u0006 להוציאם לחולין — יכול היה לעשות זאת בהיתר, שהיה \u0003מיתשיל עלייהו\u0004 \u0005[נשאל עליהם],\u0006 הולך לחכם ומבקש שיתיר את נדרו, שנדר בהמות אלו להקדש. \u0003ו\u0004מה שאמרו שאדם רואה את \u0003מעשרותיו,\u0004 מעשר בהמה שלו, אם יש בהם מום, ואין חושדים בו, הרי זה משום \u0003דאי בעי\u0004 \u0005[שאם\u0006 היה \u0005רוצה]\u0006 להיפטר מלהקריבם, יכול היה לעשות זאת בהיתר, \u0003שדי ביה מומא בכוליה עדריה\u0004 \u0005[\u0006שהיה \u0005מטיל מום בכל עדרו],\u0006 מתחילה, כשיש בכולו רק בהמות חולין, ואחר כך מעשרו. \u0003ו\u0004מה שאמרו בברייתא ש\u0003נשאל\u0004 אדם \u0003על טהרותיו,\u0004 ואינו חשוד לומר על טמא שהוא טהור, טעמו — מפני שאינו מפסיד אם נטמאו, \u0003דהא חזא ליה\u0004 \u0005[שהרי\u0006 הדבר הטמא \u0005ראוי לו]\u0006 לאכילה \u0003בימי טומאתו.\u0004","","","","\u0003כל פסולי המוקדשין,\u0004 קדשים שנפל בהם מום ונפסלו מהקרבה, והם נפדים — \u0003הנאתן,\u0004 הרווח ממכירתם, הריהו \u0003להקדש.\u0004 ומשום כך, כדי שההקדש לא יפסיד, הריהם \u0003נמכרין באיטליז\u0004 במקום השוק, שם מרובים הקונים, ומחירם גבוה. ואין אומרים שיש בזה זלזול בקדשים. \u0003ו\u0004כן \u0003נשחטין,\u0004 פסולי המוקדשים שנפדו, \u0003באיטליז,\u0004 בבית המטבחיים שבשוק, \u0003ו\u0004כן כשמוכרים את בשרם הריהם \u0003נשקלין בליטרא,\u0004 במשקל, כדרך ששוקלים בשר רגיל.","\u0003חוץ מן הבכור והמעשר\u0004 (מעשר בהמה), שכשנפל בהם מום והותרו לשחיטה, אינם נמכרים ואינם נשחטים אלא בתוך ביתו, ואינם נשקלים בליטרא אלא באומד, כיון \u0003שהנייתן\u0004 אינה אלא \u0003לבעלים\u0004 (הבכור — לכהן, והמעשר — לבעליו), ולא להקדש, שהרי אין להם פדייה. והואיל ואין להקדש רווח בכך — אין נוהגים בקדשים מנהג חולין. אבל \u0003פסולי המוקדשין\u0004 — \u0003הנייתן להקדש.\u0004 ומוסיפים: למרות שבשר בכור אינו נשקל בליטרא, מכל מקום \u0003שוקלין מנה כנגד מנה בבכור,\u0004 שאם יש לו בשר חולין במשקל ידוע — מותר לשקול כנגדו חתיכה מן הבכור ולמוכרה כך, לפי שאין זו דרך שקילה של בשר חולין.",""],["שנינו במשנה: \u0003כל פסולי המוקדשין הנאתן,\u0004 הרווח ממכירתם, \u0003להקדש,\u0004 ולכן הם נמכרים באיטליז ונשחטים באיטליז ונשקלים בליטרא. ושואלים: \u0003אימת\u0004 \u0005[מתי]\u0006 מדובר שמוכרים ושוחטים אותם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לאחר פדיונו,\u0004 אחרי שפדו אותם הבעלים מיד ההקדש — האם אז \u0003הנאתן להקדש?\u0004 הלא לאחר שנפדו רכוש הבעלים הם, ולפיכך \u0003הנאתן\u0004 של ה\u0003בעלים הוא!\u0004","\u0003אלא\u0004 תאמר שמדובר כאן \u0003לפני פדיונו,\u0004 ודמי מכירתם (פדיונם) ניתנים להקדש. ואולם בשלב זה האם הם \u0003נשחטין? הא בעי\u0004 \u0005[הרי צריכים\u0006 הם\u0005]\u0006 \u0003העמדה\u0004 לפני הכהן \u0003והערכה\u0004 של מחירם כדי לפדותם, ובהמה שחוטה אינה יכולה לעמוד לפני הכהן!","ומוסיפים: \u0003הניחא למאן דאמר\u0004 \u0005[זה,\u0006 אמנם, \u0005נוח ל\u0006דעת \u0005האומר]\u0006 ש\u0003קדשי מזבח\u0004 שנפל בהם מום \u0003לא היו בכלל\u0004 דין \u0003העמדה והערכה,\u0004 אלא דווקא קדשי בדק הבית, וניתן איפוא לשוחטם קודם פדיון. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאף הם \u0003היו בכלל העמדה והערכה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא לעולם\u0004 יש לומר שמדובר שנמכרים ונשחטים באטליז \u0003לאחר פדיון, ומאי\u0004 \u0005[ומה]\u0006 שנאמר \u0003הנאתן להקדש\u0004 — לא על ההנאה מדמי המכירה מדובר, אלא \u0003אדמעיקרא\u0004 \u0005[על\u0006 פדיונם \u0005מתחילה].\u0006","\u0003דכיון דשרי להו מר\u0004 \u0005[שכיון שמתיר אותם החכם\u0006 במשנתנו\u0005]\u0006 שיהיו \u0003נמכרין באיטליז ונשחטין באיטליז ונשקלין בליטרא\u0004 לאחר הפדיון — \u0003טפי ופריק מעיקרא\u0004 \u0005[מוסיף ופודה\u0006 אותם \u0005מתחילה]\u0006 מיד ההקדש במחיר גבוה יותר, שהרי יכול למוכרו לאחר הפדיון ביוקר.","שנינו במשנה: \u0003חוץ מן הבכור ומן המעשר שהנייתן לבעלים,\u0004 ולכן גם כאשר נפל בהם מום, ומותר לשוחטם — אינם נמכרים באיטליז. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בכור\u0004 — \u0003באיטליז הוא דלא מיזדבן\u0004 \u0005[שלא נמכר],\u0006 \u0003הא בביתיה מיזדבן\u0004 \u0005[אבל בביתו,\u0006 שלא בפרהסיא, \u0005נמכר].\u0006 \u0003אלא מעשר,\u0004 אפילו \u0003בביתיה\u0004 \u0005[בביתו]\u0006 \u0003מי מיזדבן\u0004 \u0005[האם נמכר]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בבכור נאמר\u0004 רק: \u0003\"לא תפדה\"\u0004 (במדבר יח, יז), שלא ניתן לפדותו ולהוציאו לחולין, \u0003ו\u0004אולם משעה שהגיע ליד הכהן, שהוא נחשב בעליו של הבכור — הריהו \u0003נמכר\u0004 כשהוא \u0003חי.\u0004 ואילו \u0003במעשר\u0004 בהמה \u0003נאמר: \"לא יגאל\"\u0004 (ויקרא כז, לג), \u0003ו\u0004לכן, לא רק שאין פודים אותו, אלא גם \u0003אינו נמכר לא חי ולא שחוט, לא תם ולא בעל מום!\u0004","ומספרים: \u0003הא מילתא איקשיא ליה\u0004 \u0005[דבר זה\u0006 היה \u0005קשה לו]\u0006 \u0003לרב ששת באורתא\u0004 \u0005[בלילה],\u0006 \u0003ושנייה בקדמותא\u0004 \u0005[ותירץ אותה בבוקר]\u0006 \u0003מברייתא,\u0004 ש\u0003במעשר בהמה של יתומים\u0004 קטנים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שנפל בו מום ונשחט, שהתירו חכמים למוכרו. \u0003ומשום השבת אבידה נגעו בה,\u0004 שאין היתומים יכולים לאכול את כל בשרו, וכדי שלא יפסידו התירו חכמים למכור אותו לאחרים.","מסופר, \u0003ר' אידי סרסיה\u0004 \u0005[שמשו]\u0006 של \u0003רב ששת הוה שמעה מיניה\u0004 \u0005[היה שומע אותה,\u0006 שמועה זו, \u0005ממנו]\u0006 מפי רב ששת, \u0003אזל אמרה בי מדרשא ולא אמרה משמיה\u0004 \u0005[הלך ואמר אותה בבית המדרש ולא אמרה משמו]\u0006 של רב ששת, \u0003שמע רב ששת איקפד\u0004 \u0005[הקפיד\u0006 עליו\u0005]\u0006 על שלא אמרה משמו, \u0003אמר: מאן דעקיץ\u0004 — \u0003ליעקציה עקרבא\u0004 \u0005[מי שעוקץ\u0006 אותי, פוגע בי — \u0005שיעקוץ אותו עקרב]!\u0006 ושואלים: \u0003ורב ששת מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 אם אומרים בשמו או אין אומרים בשמו, שהקפיד כל כך? ומשיבים: כפי ש\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 שביקש דוד \u0003\"אגורה באהלך עולמים\"\u0004 (תהלים סא, ה)? \u0003וכי איפשר לאדם לגור\u0004 באותה שעה \u0003בשני עולמים,\u0004 בעולם הזה ובעולם הבא?","\u0003אלא\u0004 כך \u0003אמר דוד: רבונו של עולם,\u0004 עשה ש\u0003יאמרו דבר שמועה מפי בעולם הזה,\u0004 גם לאחר שאמות, ובכך אזכה לחיות באותה שעה גם בעולם הזה. שכך \u0003אמר ר' יוחנן משום\u0004 (משמו) של \u0003ר' שמעון בן יוחי: כל תלמיד חכם שאומרים דבר שמועה מפיו בעולם הזה\u0004 — \u0003שפתותיו דובבות\u0004 (רוחשות ולוחשות) באותה שעה \u0003בקבר.\u0004","\u0003ואמר ר' יצחק בר זעירי:\u0004 \u0003מאי קראה\u0004 \u0005[מהו הפסוק\u0006 המלמד על כך\u0005]\u0006 — \u0003\"וחכך כיין הטוב הולך לדודי למישרים דובב שפתי ישנים\"\u0004 (שיר השירים ז, י), שדברי התורה (שבחיכה של כנסת ישראל) הרי הם \u0003ככומר\u0004 (ערימה) \u0003של ענבים,\u0004 שמניחים אותם יחד כדי שיתחממו ויתססו, מה כומר של ענבים כיון ש\u0003אדם נוגע בו\u0004 — \u0003דובב,\u0004 נע, ומשמיע קול לחישה — \u0003אף תלמידי חכמים, כיון שאדם אומר דבר שמועה מפיו\u0004 של תלמיד חכם — דובבות שפתיו בקבר.","ושבים לגופו של הענין, \u0003מאי\u0004 \u0005[מהי]\u0006 אותה \u0003ברייתא\u0004 שעליה סמך רב ששת? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשר בהמה של יתומים\u0004 — \u0003מוכרין אותו. ומעשר בהמה ששחטו,\u0004 ואסור למכור את בשרו — \u0003מבליעו,\u0004 את מחיר הבשר, \u0003ב\u0004מחיר \u0003עורו, בחלבו ובגידו ובקרניו\u0004 של המעשר, שהם מותרים במכירה. שמוכרם ביוקר, ונותן לו את הבשר במתנה.","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]\u0006 התנא? שהרי מתחילה משמע שמעשר בהמה של יתומים נמכר כדרכו, ואחר כך נאמר שאין מוכרים בשר מעשר אלא בהבלעה! \u0003אמר אביי,\u0004 אין בברייתא אלא דין אחד, והתנא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מעשר בהמה של יתומים מוכרין אותו,\u0004 וכיצד מוכרים אותו — \u0003בהבלעה.\u0004","ואומרים: \u0003מכלל\u0004 הדברים אתה למד שמעשר של \u0003גדול,\u0004 שאינו יתום, אפילו \u0003בהבלעה לא\u0004 ימכרנו. ושואלים: \u0003מאי שנא מהא דתניא\u0004 \u0005[מה שונה\u0006 דין זה \u0005מזו ששנויה]:\u0006 \u0003הלוקח\u0004 (הקונה) \u0003לולב מחבירו בשביעית\u0004 (בשנת השמיטה) — \u0003נותן לו\u0004 המוכר גם \u0003אתרוג במתנה, לפי שאינו רשאי ללוקחו\u0004 (לקנותו) את האתרוג \u0003בשביעית,\u0004 שאסור לסחור בפירות שביעית.","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים בכך]:\u0006 אם \u0003לא רצה\u0004 המוכר \u0003ליתן לו במתנה מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 \u0003ואמר רב הונא: מבליע לו\u0004 את \u0003דמי\u0004 ה\u0003אתרוג בלולב,\u0004 שמוסיף במחירו של הלולב עד שנכללים בו גם דמי האתרוג!","ומשיבים: \u0003התם לא מוכחא מילתא\u0004 \u0005[שם לא מוכח הדבר],\u0006 שאין מחיר האתרוג יקר כל כך, ואין התוספת במחיר הלולב ניכרת כל כך. אבל \u0003הכא מוכחא מילתא\u0004 \u0005[כאן מוכח הדבר],\u0006 שמשלם לו עבור הבשר, שכן מחירו גבוה בהרבה ממחיר העור והגידים.","\u0003אמר רבא\u0004 לאביי: \u0003אם כן\u0004 אתה מפרש, שכל הברייתא אינה עוסקת אלא בדין אחד, במעשר של יתומים, מה שנאמר בברייתא \u0003\"מעשר בהמה\" תרי זמני\u0004 \u0005[שתי פעמים]\u0006 \u0003למה לי? אלא אמר רבא:\u0004 שתי הלכות יש בברייתא, והתנא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מעשר בהמה של יתומים\u0004 ששחטוהו — \u0003מוכרין אותו כדרכו. ומעשר בהמה\u0004 של \u0003גדול ששחטו\u0004 — \u0003מבליעו\u0004 את בשרו \u0003ב\u0004מכירת \u0003עורו בחלבו בגידו ובקרניו.\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את ההלכה הזו, שניתן למכור בשר מעשר בהבלעה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי מעשר: \u0003\"והיה הוא ותמורתו יהיה קדש לא יגאל\"\u0004 (ויקרא כז, לג), שאם אמר על בהמת חולין שתהא תמורת המעשר — שניהם קדושים, ואינם נמכרים.","ויש ללמוד מדין התמורה על איסור המכירה (\"לא יגאל\"): \u0003אימתי\u0004 מעשר \u0003עושה תמורה\u0004 — \u0003מחיים,\u0004 שהרי בהמת קדשים שחוטה אינה עושה תמורה. ואם כן יש לומר גם כי מעשר, \u0003אימתי אינו נגאל\u0004 (נמכר) — \u0003מחיים, הא\u0004 \u0005[אבל]\u0006 \u0003לאחר שחיטה\u0004 — \u0003נגאל.\u0004 ומדין תורה מותר, איפוא, למכור את המעשר לאחר שחיטה, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003ההוא\u0004 ש\u0003גזרו\u0004 ואסרו למכור את בשרו \u0003לאחר שחיטה, אטו\u0004 \u0005[משום]\u0006 חשש שיבואו למוכרו \u0003לפני שחיטה.\u0004","ואולם דוקא לגבי \u0003דבר הנישום מחיים,\u0004 בשר הבהמה, שלפי משקלו אומדים את ערכה של הבהמה כשמוכרים אותה בחייה — \u0003גזור רבנן\u0004 \u0005[גזרו חכמים]\u0006 שלא למכור \u0003לאחר שחיטה, אטו\u0004 \u0005[משום]\u0006 חשש שיבואו למוכרו \u0003לפני שחיטה,\u0004"],["\u0003דבר שאינו נישום מחיים,\u0004 כגון העור והגידים, שאין מוכרים בהמה בחייה בשביל גידיה ועצמותיה — \u0003לא גזור רבנן\u0004 \u0005[לא גזרו חכמים]\u0006 שלא למוכרם לאחר שחיטה, ולכן כשרוצה למכור בשר יכול להבליעו בעור וגידים, כפי ששנינו בסוף הברייתא. \u0003וביתמי אוקמוה רבנן אדאורייתא\u0004 \u0005[וביתומים העמידו אותה חכמים על דין תורה],\u0006 שלאחר שחיטה מותר למכור את בשר המעשר, גם בלא הבלעה.","ומעירים: \u0003ואף רב שמואל בר רב יצחק סבר לה להא\u0004 \u0005[סבור כ\u0006שמועה \u0005זו]\u0006 שאמר \u0003רבא,\u0004 שמן התורה מותר למכור מעשר בעל מום שנשחט, ולכן התירו חכמים לעשות כן במעשר של יתומים בלא הבלעה. ש\u0003אמר רב שמואל בר רב יצחק: מנין למעשר בהמה של יתומים\u0004 שנפל בו מום ונשחט, \u0003שמוכרים אותו כדרכו?\u0004","\u0003שנאמר\u0004 לגבי בהמות קדשים שנפל בהן מום: \u0003\"רק בכל אות נפשך תזבח ואכלת בשר\u0004 כברכת ה' אלהיך אשר נתן לך\" (דברים יב, טו), \u0003איזהו דבר שאין בו ברכה מחיים,\u0004 שאסור ליהנות ממנו כלל בעודו חי, \u0003אלא לאחר שחיטה\u0004 (\"תזבח... כברכת ה' \")? \u0003הוי אומר זה מעשר בהמה\u0004, שנאמר בו \"לא יגאל\", ואסור למוכרו בחייו, אלא רק לאחר שחיטה. שנינו בברייתא לעיל כי חכמים התירו להבליע מחיר בשר מעשר במכירת העור והחלב, הגידים והקרנים שלו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003מהו להבליעו\u0004 את מחיר בשר המעשר \u0003ב\u0004תוך מחיר ה\u0003עצמות\u0004 של המעשר? \u0003ר' חייא ור' שמעון ברבי\u0004 נחלקו בכך, חד \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מבליעו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין מבליעו.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שאין מבליעים — \u0003ב\u0004בהמה \u0003דקה,\u0004 שאין העצמות ראויות לעשות בהן דבר, ואין מוכרים אותן, וממילא לא ניתן להבליע בשר בדמיהן. \u0003הא\u0004 \u0005[זו]\u0006 \u0003בגסה\u0004 שמעצמותיה אפשר לעשות כלים שונים, והן עומדות למכירה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדברים \u0003בגסה, ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 \u0003מר כי אתריה, ומר כי אתריה\u0004 \u0005[חכם זה כמקומו, וחכם זה כמקומו],\u0006 שיש מקומות שעושים כלים מעצמות ומוכרים אותן, ויש מקומות שאין עושים כלים מעצמות, ואין מוכרים אותן.","\u0003גופא\u0004 \u0005[\u0006ושבים לדון ב\u0005גופה]\u0006 של הברייתא ששנינו לעיל: \u0003בבכור הוא אומר: \"לא יפדה\"\u0004 (\"אך בכור שור... לא תפדה\" במדבר יח, יז), \u0003ו\u0004אין רשאים לפדותו ולהוציאו לחולין, אבל הוא \u0003נמכר,\u0004 שרשאי הכהן שקיבלו למוכרו. ואילו \u0003במעשר נאמר \"לא יגאל\"\u0004 (ויקרא כז, לג), \u0003ו\u0004לפיכך, לא רק שאינו נפדה, אלא גם \u0003אינו נמכר, לא חי ולא שחוט, ולא תם ולא בעל מום.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שמה שנאמר במעשר \"לא יגאל\" מלמד על איסור מכירה?","\u0003אמר רב חיננא אמר רב, וכן אמר רב דימי אמר ר' יוחנן: נאמר \"לא יגאל\" במעשר\u0004 (ויקרא כז,לג), \u0003ונאמר \"ולא יגאל\" בחרמים,\u0004 כלומר, בנכסים שאדם מקדיש בלשון חרם, והם עוברים לרשות הכהנים. שכך נאמר בהם: \"אך כל חרם... לא ימכר ולא יגאל\" (ויקרא כז, כח), ולמדים איפוא בגזירה שווה: \u0003מה להלן,\u0004 בחרמים, איסור \u0003מכירה עמו\u0004 (עם איסור הגאולה), \u0003אף כאן,\u0004 במעשר בהמה — איסור \u0003מכירה עמו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 חייבים לומר שהכתוב \"לא יגאל\" \u0003מפני\u0004 \u0005[מופנה]\u0006 לגזירה שווה זו, ואינו נצרך כדי ללמוד ממנו דבר אחר (ובאופן זה לא ניתן להקשות על לימוד זה מן הסברה, משום שכאילו נאמר הדבר בתורה במפורש). \u0003דאי לא מפני\u0004 \u0005[שאם אינו מופנה],\u0006 \u0003איכא למפרך\u0004 \u0005[יש לפרוך]\u0006 השוואה זו, ולומר: \u0003מה לחרמים\u0004 שיש בהם חומרה מיוחדת, \u0003שכן חלים על הכל,\u0004 על כל דבר שאדם מחרים מנכסיו. מה שאין כן במעשר בהמה, שאינו שייך אלא בבהמות כשרות.","ומעירים: \u0003לאיי אפנויי מפני\u0004 \u0005[ובאמת מופנה\u0006 הוא הכתוב\u0005],\u0006 שכן אפשר היה ש\u0003לא יאמר \"ולא יגאל\" בחרמים, ויגמר\u0004 \u0005[וילמד]\u0006 הלכה זו \u0003ממעשר: מה מעשר קדוש ואינו נגאל,\u0004 שאינו נפדה — \u0003אף חרמים קדושים ואינם נגאלין.\u0004 אם כן, \u0003\"ולא יגאל\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 הרי זה \u0003לאפנויי\u0004 \u0005[להפנות אותו\u0006 לדרשה\u0005]\u0006 זו.","ודוחים: עדיין יש לומר כי \"לא יגאל\" שנאמר בחרמים הוצרך לגופו ואינו מופנה, שכן \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 את ההשוואה למעשר, ולומר: \u0003מה למעשר,\u0004 שהוא חמור יותר, \u0003שכן קדוש לפניו ולאחריו,\u0004 שאם טעה במנין הבהמות, וקרא בטעות \"עשירי\" לתשיעי, וגם לאחד עשר, הרי אלו מוקדשים. מה שאין כן בחרמים, שהקדש בטעות אינו חל כלל. ולכך הוצרך להיאמר גם בו \"לא יגאל\" ללמד שאינו נפדה!","\u0003אלא\u0004 כך צריך לומר: \u0003לא יאמר \"לא יגאל\" בחרמים, ויגמר\u0004 \u0005[וילמד]\u0006 \u0003מבכור: מה בכור קדוש ואינו נגאל,\u0004 שהרי נאמר בו \"לא תפדה\" — \u0003אף חרמים קדושין ואינן נגאלין.\u0004 אם כן, \u0003\"לא יגאל\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 בחרמים \u0003למה לי? לאפנויי\u0004 \u0005[להפנות]\u0006 אותו, כדי ללמד על מעשר בגזירה שווה שאינו נמכר.","ודוחים: אף כאן \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 את ההשוואה של חרמים לבכור, ולומר: \u0003מה לבכור שכן קדושתו מרחם,\u0004 מה שאין כן חרמים, שצריכים להקדישם, ולכך הוצרך לומר בהם \"לא יגאל\"!","אלא כך יש לומר: \u0003לא יאמר \"לא יגאל\" במעשר, ויגמר\u0004 \u0005[וילמד]\u0006 בגזירה שווה \u0003העברה העברה מבכור,\u0004 שבמעשר נאמר: \"אשר יעבור תחת השבט\" (ויקרא כז, לב), ובבכור נאמר: \"והעברת כל פטר רחם לה' \" (שמות יג, יב), \u0003מה בכור קדוש ואינו נגאל, אף מעשר קדוש ואינו נגאל.\u0004 אם כן, \u0003\"לא יגאל\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003במעשר למה לי? לאפנויי\u0004 \u0005[להפנות אותו],\u0006 כדי ללמוד בגזירה שווה מחרמים, שגם במעשר יש איסור מכירה.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין],\u0006 מה שנאמר \"לא יגאל\" \u0003במעשר נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מפני\u0004 \u0005[אינו מופנה],\u0006 והוא נצרך ללמד שמעשר עצמו אינו נפדה. \u0003דאיכא למיפרך כדפרכינן\u0004 \u0005[ש\u0006הרי \u0005יש\u0006 מקום \u0005לפרוך\u0006 את ההשוואה של מעשר לבכור, \u0005כמו ש\u0006כבר \u0005פרכנו]\u0006 את ההשוואה של חרמים לבכור, מכך שבכור קדוש מרחם!","ומשיבים: \u0003\"והעברת\"\u0004 האמור בבכור \u0003קרא יתירא\u0004 \u0005[כתוב מיותר]\u0006 \u0003הוא,\u0004 ומופנה לדרשה זו, כאילו היא מפורשת בכתוב, ולא ניתן לפורכה.","ושואלים: \u0003בכור נמי\u0004 \u0005[גם כן],\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה \u0003גאולה גאולה מחרמים,\u0004 שאסור למוכרו, כפי שלמדנו מחרמים למעשר! ומשיבים: גאולה הכתובה ב\u0003מעשר\u0004 — \u0003מפני\u0004 \u0005[מופנה],\u0006 ללמוד דין זה בגזירה שווה מחרמים. אבל מה שנאמר ב\u0003בכור\u0004 — \u0003לא מפני\u0004 \u0005[אינו מופנה],\u0006 אלא לגופו, שאין פודים את הבכור.","ושואלים: \u0003ומאי חזית\u0004 \u0005[ומה ראית לומר]\u0006 ש\u0003\"לא תפדה\"\u0004 שכתוב ב\u0003בכור\u0004 — \u0003לגופיה\u0004 \u0005[לגופו]\u0006 הוא שנאמר, \u0003ו\u0004זה שנאמר ב\u0003מעשר\u0004 — \u0003לאפנויי\u0004 \u0005[להפנותו]\u0006 לדרשה? \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 של \u0003מעשר\u0004 — \u0003לגופיה\u0004 \u0005[לגופו]\u0006 הוא נצרך, ללמד שאינו נפדה, ואילו של \u0003בכור\u0004 — \u0003לאפנויי\u0004 \u0005[להפנות אותו]\u0006 לדרשה, ללמוד מחרמים בגזירה שווה שאינו נמכר!","ומשיבים: \u0003דנין\u0004 לשון \u0003גאולה\u0004 שבמעשר \u0003מ\u0004לשון \u0003גאולה\u0004 שבחרמים, \u0003ואין דנין\u0004 לשון \u0003פדייה\u0004 שבבכור \u0003מ\u0004לשון \u0003גאולה\u0004 שבחרמים.","ודוחים: \u0003מאי נפקא מינה?\u0004 \u0003הא תנא דבי\u0004 \u0005[הרי\u0006 בכגון זה \u0005שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"ושב הכהן\"\u0004 (ויקרא יד, לט), ונאמר \u0003\"ובא הכהן\"\u0004 (ויקרא א, מד), ואומרים אנו: \u0003זו היא שיבה זו היא ביאה,\u0004 כלומר, בשני המקרים המשמעות היא שבא הכהן אל הבית, ולפיכך למדים בגזירה שווה זה מזה, למרות שהמילים אינן זהות, אלא רק תוכנן!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאפשר ללמוד גזירה שווה ממילים שאינן זהות, אמורים \u0003היכא דליכא דדמי ליה\u0004 \u0005[במקום שאין\u0006 כתוב אחר \u0005שדומה לו]\u0006 בדיוק, שיכול להילמד בגזירה שווה, \u0003אבל איכא דדמי ליה\u0004 \u0005[\u0006במקום ש\u0005יש דומה לו]\u0006 — \u0003מדדמי ליה ילפינן\u0004 \u0005[מן הדומה לו אנו למדים].\u0006","ומקשים עוד: \u0003ולילף\u0004 \u0005[ושילמד]\u0006 \u0003בכור\u0004 בגזירה שווה \u0003העברה העברה ממעשר,\u0004 שאסור למוכרו, \u0003דהא\u0004 \u0005[שהרי]\u0006 לגבי \u0003מעשר נמי\u0004 \u0005[גם כן]\u0006 כבר \u0003גמר\u0004 \u0005[למד]\u0006 דין זה בגזירה שווה \u0003גאולה גאולה מחרמים!\u0004","ומשיבים: \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 בכור מאיסור זה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חרמים,\u0004 שאמרה \u0003\"הוא\"\u0004 (\"קדש קדשים הוא לה' \". ויקרא כז, כח) — להדגיש: \u0003הוא ולא בכור.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \u0003\"הוא\"\u0004 בא להדגיש: \u0003ולא מעשר!\u0004 ומשיבים: \u0003מעשר\u0004 דומה לחרמים, שיש בו לשון \u0003גאולה כמותו.\u0004","\u0003רבא אמר,\u0004 איסור מכירה של מעשר נלמד באופן זה: \"לא יגאל\" של \u0003חרמים\u0004 המלמד שאין פודים אותו, \u0003לא צריך\u0004 כלל לאומרו, \u0003דאיתנהו היכא\u0004 \u0005[ש\u0006הרי \u0005היכן נמצאים\u0006 החרמים הללו\u0005]\u0006 המיועדים לכהנים? \u0003אי בי\u0004 \u0005[אם בבית]\u0006 ה\u0003בעלים\u0004 — \u0003הקדש נינהו\u0004 \u0005[הם]\u0006 ואין בכוחו לפדותם, \u0003אי בי\u0004 \u0005[אם בבית]\u0006 ה\u0003כהן\u0004 הם נמצאים כבר — \u0003חולין נינהו\u0004 \u0005[הם],\u0006 והכהן יכול למוכרו לכל מי שירצה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חרמים, כל זמן שהן בבית בעלים\u0004 — \u0003הרי הן כהקדש לכל דבריהם, שנאמר: \"כל חרם קדש קדשים הוא לה' \"\u0004(ויקרא כז, כח), ואם \u0003נתנן לכהן\u0004 — משעה שהגיעו לידו \u0003הרי הן כחולין לכל דבריהם, שנאמר: \"כל חרם בישראל לך יהיה\"\u0004 (במדבר יח, יד). ואם כן, \u0003\"לא\u0004"],["\u0003יגאל\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 ולכן צריך לומר: \u0003אם אינו ענין לחרמים תנהו ענין למעשר,\u0004 שאסור למוכרו, בנוסף למה שנאמר בו \"לא יגאל\", שאסור לפדותו. ומקשים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003תנהו ענין לבכור\u0004 שאסור למוכרו! ומשיבים: \u0003מעשר\u0004 — נאמרה בו לשון \u0003גאולה כמותו\u0004 (כמו בחרם).","\u0003רב אשי אמר:\u0004 אין צורך ללמוד איסור מכירה של מעשר ממה שנאמר בחרמים, אלא \u0003\"לא יגאל\"\u0004 האמור ב\u0003מעשר\u0004 — \u0003לא ימכר הוא. אמר רב אשי: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי מעשר: \u0003\"והיה הוא ותמורתו יהיה קדש לא יגאל\"\u0004 (ויקרא כז, לג), ויש ללמוד מדין התמורה על דין הגאולה:","\u0003אימתי\u0004 מעשר \u0003עושה תמורה\u0004 — \u0003מחיים,\u0004 שאם המיר בהמת קדשים מתה בבהמת חולין — אינה מתקדשת בכך. ולפיכך צריך לומר גם כן: \u0003אימתי אינו נגאל,\u0004 אין בעליו רשאי לפדותו — \u0003מחיים,\u0004 ומכאן יש לדייק: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003לאחר שחיטה\u0004 — \u0003נגאל.\u0004 ואולם, כיצד אפשר לפדות מעשר לאחר שנשחט? \u0003הא בעי\u0004 \u0005[הרי צריך]\u0006 \u0003העמדה והערכה\u0004 לפני הכהן, כדי שיוכל לפדותו, כדין שאר קדשי מזבח, ומשנשחט שוב אי אפשר להעמידו!","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמה שנאמר \u0003\"לא יגאל\"\u0004 — \u0003לא ימכר הוא,\u0004 וקודם שנשחט המעשר אינו יכול למוכרו לאדם אחר, אבל לאחר שנשחט — מותר הדבר.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קדשי מזבח\u0004 אף הם \u0003היו בכלל העמדה והערכה. אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003קדשי מזבח לא היו בכלל העמדה והערכה,\u0004 אלא רק קדשי בדק הבית, ואם כן ניתן לפדות מעשר לאחר שחיטה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע לא נפרש כפשוטו, ש\"לא יגאל\" משמעו — לא ייפדה?","ומשיבים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו, כך אנו אומרים]:\u0006 הואיל ו\"לא יגאל\" האמור אינו אלא מחיים, כדין תמורה, אבל לאחר שחיטה מותר הדבר — לא ניתן לפרש זאת כאיסור פדייה, שכן \u0003מי איכא\u0004 \u0005[האם יש,\u0006 ייתכן, דבר\u0005]\u0006 ש\u0003מחיים לא מיפריק\u0004 \u0005[אינו נפדה],\u0006 \u0003ולאחר שחיטה מיפריק\u0004 \u0005[נפדה]?\u0006 אלא מכאן שאין מדובר באיסור פדייה, אלא באיסור מכירה. ודוחים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 נאמר שניתן לפדותו רק לאחר שחיטה? והרי יש טעם לחלוקה כזו: \u0003מחיים דאלימא קדושתיה\u0004 \u0005[שתקיפה,\u0006 חזקה, \u0005קדושתו]\u0006 — \u0003לא מיפריק\u0004 \u0005[אינו נפדה],\u0006 ודווקא \u0003לאחר שחיטה דאקיל ליה קדושתיה\u0004 \u0005[שהוקלה לו קדושתו]\u0006 — \u0003מיפריק\u0004 \u0005[נפדה]!\u0006","ודוחים: \u0003ולא כל\u0004 ש\u0003כן הוא,\u0004 שנאמר היפך דבר זה: \u0003ומה מחיים, דאלים למיתפס\u0004 \u0005[ש\u0006המעשר \u0005תקיף,\u0006 חזק, כדי \u0005לתפוס]\u0006 את \u0003פדיונו\u0004 בקדושתו, שהרי הוא עושה תמורה — \u0003לא מיפריק\u0004 \u0005[אינו נפדה],\u0006 \u0003לאחר שחיטה, דלא אלים למיתפס\u0004 \u0005[שאינו חזק לתפוס]\u0006 \u0003פדיונו,\u0004 שהרי השחוטה אינה עושה תמורה — האם \u0003מיפריק\u0004 \u0005[נפדה]?\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003\"לא יגאל\"\u0004 — \u0003לא ימכר הוא.\u0004","ואומרים: אם כן, \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 במפורש \u0003\"לא ימכר\"!\u0004 ומשיבים: \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 \u0003\"לא ימכר\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003איזדבוני הוא דלא מזדבן\u0004 \u0005[להימכר הוא שאינו נמכר],\u0006 מפני \u0003דקא עביד עובדין דחול\u0004 \u0005[שהוא עושה\u0006 בו \u0005מעשים של חול],\u0006 שהוא נוהג בו כבהמת חולין רגילה, ודמיו נעשים חולין, \u0003אבל איפרוקי\u0004 — \u0003מיפריק\u0004 \u0005[להיפדות\u0006 — \u0005הוא נפדה],\u0006 \u0003דהא עיילי\u0004 \u0005[שהרי נכנסים]\u0006 \u0003דמיו להקדש, להכי כתב רחמנא\u0004 \u0005[לכך כתבה התורה]:\u0006 \u0003\"לא יגאל\",\u0004 שאסור לפדותו, ומכאן אתה למד \u0003דלא איזדבוני מיזדבן\u0004 \u0005[שאינו נמכר] ולא איפרוקי מיפריק [ואינו נפדה].\u0006 \u0003בית\u0004","\u0003שמאי אומרים: לא ימנה ישראל עם הכהן ל\u0004אכילת \u0003בכור\u0004 בעל מום. \u0003ובית הלל מתירין\u0004 שישראל יאכל מן הבכור הזה, \u0003ואפילו\u0004 מתירים ל\u0003גוי\u0004 לאכול ממנו.","שנינו במשנתנו, כי לדעת בית הלל מותר אפילו לגוי לאכול מן הבכור. ואומרים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבי עקיבא היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003בכור\u0004 בעל מום, \u0003אין נמנין עליו אלא חבורה שכולה כהנים,\u0004 אלו \u0003דברי בית שמאי. ובית הלל אומרים: אפילו זרים. ר' עקיבא מתיר\u0004 להאכילו \u0003אפילו\u0004 ל\u0003גוי.\u0004 ומה שמתירים בית הלל במשנתנו להאכיל לגוי, הריהו איפוא כפי שפוסק ר' עקיבא לפי שיטתם.","ומסבירים את הנימוקים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי? דכתיב\u0004 \u0005[שנאמר]\u0006 לאהרן ובניו לגבי הבכורות: \"אך בכור שה או בכור כשב... \u0003ובשרם יהיה לך\u0004 כחזה התנופה וכשוק הימין\" (במדבר יח, יח), כלומר, דינם כדין חזה ושוק שמקבלים הכהנים מכל זבח שלמים: \u0003מה התם\u0004 \u0005[שם],\u0006 בחזה ושוק, \u0003כהנים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אוכלים בו, \u0003ישראל\u0004 — \u0003לא,\u0004 שהרי נאמר לגביהם: \"תאכלו במקום טהור אתה ובניך ובנותיך אתך\" (ויקרא י, יד), \u0003אף הכא\u0004 \u0005[כאן],\u0006 באכילת בכור, \u0003כהנים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אוכלים ממנו, \u0003ישראל\u0004 — \u0003לא.\u0004"],["\u0003ובית הלל\u0004 טוענים כנגד זה: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא בבכור \u0003תם,\u0004 שקרב במקדש, \u0003אבל\u0004 בבכור \u0003בעל מום\u0004 — הרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \"בשעריך תאכלנו \u0003הטמא והטהור יחדיו יאכלנו\"\u0004 (דברים טו, כב). \u0003ו\u0004קל וחומר הוא: \u0003מה\u0004 אם כהן \u0003טמא שאינו אוכל ב\u0004בשר \u0003קדשים קלים\u0004 — \u0003אוכל ב\u0004בשר \u0003בכור\u0004 בעל מום, \u0003זר שאוכל בקדשים קלים,\u0004 כגון שלמים, הנאכלים לכל אדם — \u0003אינו דין שיאכל בבכור?\u0004","ומקשים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לשבור]\u0006 את הקל וחומר, ולומר: \u0003מה ל\u0004כהן \u0003טמא\u0004 שהותר לאכול בכור בעל מום — \u0003שכן\u0004 איסור הטמא בקדשים \u0003הותר מכללו בעבודת צבור,\u0004 שהרי אם אין כהנים טהורים — מקריבים את קרבנות הציבור בכהנים טמאים. אבל זר — אסור לעולם להקריב!","\u0003ובית הלל\u0004 משיבים על כך: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בעבודה\u0004 של הקרבנות \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 קל וחומר? \u0003באכילה קאמרינן\u0004 \u0005[אנו אומרים],\u0006 ולענין אכילת קדשים, \u0003אכילת זר עדיף\u0004 על אכילה של טמא, שטמא אינו אוכל קדשים קלים ואילו זר אוכל, ולכן לענין אכילת בכור בעל מום נלמד הזר בקל וחומר מן הטמא.","ועוד שנינו בברייתא: \u0003ור' עקיבא מתיר\u0004 לכל להימנות על בשר בכור בעל מום, \u0003ואפילו גוי.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא?\u0004 נאמר \u0003\"כצבי וכאיל\"\u0004 (דברים טו, כב), \u0003מה צבי ואיל מותר\u0004 באכילה \u0003לגוי, אף פסולין,\u0004 בכור שנפל בו מום ונפסל, \u0003מותר לגוי.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר]\u0006 בשם בית הלל, שאינו מתיר להאכיל לגוי מן הבכור, מדוע אינו למד כן? ומשיבים: \u0003תלתא\u0004 \u0005[שלוש]\u0006 פעמים \u0003\"צבי ואיל\" כתיבי\u0004 \u0005[נאמרו]\u0006 בפסולי המוקדשים, זה שבבכור (דברים טו, כב), ועוד שנים (דברים יב, טו. דברים טו, כב), \u0003חד\u0004 \u0005[אחד]\u0006 נצרך \u0003לכ\u0004 מו שאמר \u0003ר' יצחק, וחד\u0004 \u0005[ואחד]\u0006 \u0003לכ\u0004 מו שאמר \u0003ר' אושעיא, וחד\u0004 \u0005[ואחד]\u0006 בא ללמד \u0003לכ\u0004 מו שאמר \u0003ר' אלעזר הקפר.\u0004","\u0003ואידך\u0004 \u0005[והכתוב האחר]\u0006 ללמד: \u0003מה צבי ואיל פטורים מן הבכורה, אף פסולי המוקדשין,\u0004 למרות שאינם קרבים על המזבח, מכל מקום \u0003פטורין מן הבכורה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בכור\u0004 בעל מום, \u0003אין מאכילין אותו לנדות,\u0004 אלו \u0003דברי בית שמאי. ובית הלל אומרים: מאכילין אותו לנדות.\u0004 ואומרים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי? דכתיב\u0004 \u0005[שנאמר]\u0006 בבכור: \u0003\"ובשרם יהיה לך\u0004 כחזה התנופה וכשוק התרומה\" (במדבר יח, יח), הניתנים לכהן מכל זבח שלמים, \u0003מה התם\u0004 \u0005[שם]\u0006 \u0003נדות לא\u0004 אוכלות מן הבשר, שהרי קדשים הם ואסור לטמא לאוכלם — \u0003אף הכא\u0004 \u0005[כאן],\u0006 בבכור בעל מום, \u0003נדות לא.\u0004","\u0003ובית הלל\u0004 אומרים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 בבשר בכור \u0003תם,\u0004 שהוקש לחזה ושוק \u0003אבל\u0004 בכור \u0003בעל מום\u0004 — הלא נאמר בו במפורש ש\u0003הטמא והטהור אכלה\u0004 (דברים טו, כב).","\u0003ובית שמאי\u0004 טוענים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהטמא יכול לאכול אותו, אמורים \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אין טומאה יוצאה עליו מגופו,\u0004 כגון שנטמא במת או בשרץ. \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003טומאה יוצאה עליו מגופו,\u0004 כגון זב או נידה — \u0003לא.\u0004 ומניין לחלק בין זה לזה?","\u0003דאשכחן דפליג רחמנא\u0004 \u0005[ש\u0006הרי \u0005אנו מוצאים שחילקה התורה]\u0006 לענין אכילת קדשים \u0003בין טומאה יוצאה עליו מגופו, לבין שאין טומאה יוצאה עליו מגופו. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 קרבן \u0003הפסח שבא בטומאה,\u0004 שהיה רוב הציבור טמא בטומאת מת, ובמקרה זה הריהו נאכל על ידי הטמאים, בכל זאת \u0003לא יאכלו ממנו זבים ומצורעין וזבות ונדות ויולדות,\u0004 שטומאה יוצאת עליהם מגופם.","\u0003ובית הלל\u0004 משיבים: \u0003התם הוא דגלי רחמנא\u0004 \u0005[שם,\u0006 בפסח, \u0005הוא שגילתה התורה]\u0006 ואמרה: \u0003\"טמא\u0004 ל\u0003נפש\"\u0004 (במדבר ט, י), כלומר, טמא מת, ולא טמא בטומאה אחרת. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 כשהתירה התורה לאכול בכור בעל מום — \u0003\"טמא\" סתמא כתיב\u0004 \u0005[סתם כתוב],\u0006 \"הטמא והטהור יחדיו יאכלוהו\" (במדבר יח, יח), \u0003לא שנא\u0004 \u0005[אין הבדל]\u0006 אם הוא טמא לנפש או טמא אחר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אף ששוחטים בהמה ביום טוב ומפשיטים את עורה — \u0003אין מרגילין ביום טוב,\u0004 כלומר, אין מפשיטים את עור הבהמה דרך הרגליים, כדי שיישאר שלם, על מנת להשתמש בו כחמת. \u0003כיוצא בו אין מרגילין\u0004 כלל (גם ביום חול) \u0003בבכור,\u0004 אפילו בעל מום, \u0003ולא בפסולי המוקדשין\u0004 שנפדו ונשחטו, מפני שיש בכך בזיון לבהמת קדשים.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ב\u0003יום טוב\u0004 אין מרגילין, משום \u0003דקא טרח טירחא דלא חזי ליה\u0004 \u0005[שהוא טורח טירחה שאינה ראויה לו],\u0006 שאינה לצורך יום טוב. \u0003אלא בכור,\u0004 שאין מרגילים בו, \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 הסבור כן? \u0003אמר רב חסדא:\u0004 שיטת \u0003בית שמאי היא,\u0004 ש\u0003אמר: אין מאכילין אותו,\u0004 את הבכור בעל המום, \u0003לנדות.\u0004 שלדעתם דין בכור בעל מום כדין בכור תם, שקרב על המזבח, ואסור לטמאים. ולכן גם אין מרגילים בו, כדין בכור תם, שאין נוהגים כן בקדשים.","ועל מה ששנינו עוד: \u0003ולא\u0004 מרגילים \u0003בפסולי המוקדשין,\u0004 שואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 הסבור כן? \u0003אמר רב חסדא: ר' אלעזר בר' שמעון היא, דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003היו לפניו שתי חטאות\u0004 שהקדיש לשם כפרת חטאו, שאם תמות או תאבד אחת יתכפר בשניה, \u0003אחת\u0004 מהן \u0003תמימה, ואחת בעלת מום\u0004 (שלאחר שהקדישה נפל בה מום), הרי \u0003תמימה\u0004 — \u0003תקרב,\u0004 ואילו \u0003בעלת מום\u0004 — \u0003תיפדה.\u0004","\u0003נשחטה בעלת מום\u0004 לאחר פדיונה, \u0003אם\u0004 נשחטה \u0003עד שלא נזרק דמה של\u0004 ה\u0003תמימה\u0004 על המזבח לכפרה — הרי היא \u0003מותרת.\u0004 אבל \u0003אם\u0004 נשחטה רק \u0003משנזרק דמה של תמימה\u0004 על המזבח, ונמצא שהיתה בחיים כשנתכפרו הבעלים — הריהי \u0003אסורה\u0004 בהנאה, כדין חטאת שנתכפרו בעליה באחרת, שדינה למיתה.","\u0003ר' אלעזר בר' שמעון אומר: אפילו\u0004 נשחטה בעלת המום, וה\u0003בשר\u0004 מונח כבר \u0003בקדירה, ונזרק דמה של תמימה\u0004 — \u0003אסורה\u0004 בעלת המום, מפני שעדיין שם חטאת עליה. הרי שהוא סבור שפסולי המוקדשים, נשארה בהם קדושה ראשונה, אפילו לאחר שחיטה, ומשום כך הוא אוסר גם להרגיל בהם.","ושואלים: \u0003ורב חסדא, לוקמה\u0004 \u0005[שיעמיד]\u0006 ברייתא זו \u0003כולה כבית שמאי,\u0004 וכדין בכור בעל מום שנשחט — כך דין שאר פסולי המוקדשים! ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לחלק ולומר כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אומרים]\u0006 \u0003בית שמאי\u0004 כך \u0003אלא בבכור,\u0004 משום ש\u0003קדושתו מרחם,\u0004 משעה שנולד, ולכן אין הקדושה פוקעת ממנו, ואסור לנהוג בו כבחולין, \u0003אבל פסולי המוקדשין\u0004 האחרים, ש\u0003אין קדושתו מרחם\u0004 — \u0003לא,\u0004 אלא משעה שהותרו בשחיטה — שוב אין בהם קדושה, ויעשה בהם כרצונו."],["ושואלים: \u0003ולוקמה\u0004 \u0005[ויעמיד]\u0006 רב חסדא את הברייתא \u0003כולה כ\u0004דעת \u0003ר' אלעזר בר' שמעון,\u0004 שאין מרגילים בפסולי המוקדשים, ואף בכור בעל מום בכלל זה! ומשיבים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' אלעזר בר' שמעון התם\u0004 \u0005[שם]\u0006 שבעל מום עומד בקדושתו, ואסור להרגיל בו, \u0003אלא\u0004 בשאר \u0003פסולי המוקדשין, דאלימי למיתפס פדיונו\u0004 \u0005[שהם תקיפים\u0006 בקדושתם עד כדי \u0005לתפוס\u0006 את \u0005פדיונם]\u0006 בקדושה. \u0003אבל בכור\u0004 בעל מום, שלא ניתן לפדותו, \u0003דלא אלים למיתפס\u0004 \u0005[שאינו תקיף\u0006 עד כדי \u0005לתפוס]\u0006 את \u0003פדיונו\u0004 בקדושה — שמא \u0003לא\u0004 \u0005[אינו]\u0006 עומד בקדושתו, ומותר להרגיל בו.","ושואלים: \u0003ו\u0004כי \u0003ר' אלעזר בר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את ההלכה ששנינו במשנה בלא חולק, ש\u0003כל פסולי המוקדשין נמכרין באיטליז ונשקלין בליטרא? אלמא\u0004 \u0005[הרי]\u0006 ש\u0003כיון דאיכא רווחא\u0004 \u0005[שיש רווח]\u0006 \u0003להקדש\u0004 — \u0003שרי לה\u0004 \u0005[מותר לו]\u0006 לנהוג מנהג חולין בפסולי המוקדשים. ומדוע לא יתיר להרגיל בהם לאחר פדיונם? והרי על ידי כך ירויח ההקדש, שיפדו אנשים את הפסולים במחיר גבוה יותר!","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: מה שמשביח בעור\u0004 על ידי שמפשיט אותו בשלימות — \u0003פגם בבשר,\u0004 שמקצת הבשר הולך לאיבוד בדרך הפשטה זו. וההיתר להרגיל אינו מעלה את ערך הבהמה. \u0003במערבא\u0004 \u0005[במערב,\u0006 בארץ ישראל\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבינא אמרי\u0004 \u0005[אומרים]\u0006 טעם אחר לאיסור להרגיל בפסולי המוקדשים — \u0003מפני שנראה כעובד עבודה בקדשים,\u0004 והרי אסור לעבוד בפסולי המוקדשים.","\u0003ר' יוסי בר אבין אומר: גזירה שמא\u0004 ימתין לשוחטם עד שימצא מי שיצטרך לעור כזה, ובתוך כך \u0003יגדל מהן עדרים עדרים,\u0004 וייכשל באיסור גיזה ועבודה.","\u0003בכור שאחזו דם,\u0004 שחלה מחמת ריבוי דם, וצריכים להקיז את דמו לרפואה, \u0003אפילו מת\u0004 הבכור אם לא יקיזו את דמו — \u0003אין מקיזין לו דם,\u0004 שמא מתוך כך יטיל בו מום, ואסור להטיל מום בקדשים, אלו \u0003דברי ר' יהודה. וחכמים אומרים: יקיז\u0004 לו דם, \u0003ובלבד שלא יעשה בו\u0004 תוך כדי כך \u0003מום.\u0004 \u0003ואם עשה בו מום\u0004 בתוך ההקזה — \u0003הרי זה לא ישחט עליו,\u0004 בגלל מום זה, אלא ימתין לו עד שיפול בו מום אחר. \u0003ר' שמעון אומר: יקיז\u0004 בכל מקרה, \u0003אף על פי שהוא עושה בו מום,\u0004 מפני שאינו מתכוון להטיל בו מום אלא לרפאותו.","בענין ששנינו במשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003בכור שאחזו דם, מקיזין לו את הדם במקום שאין עושים בו מום, ואין מקיזין לו את הדם במקום שעושין בו מום,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים:\u0004 מקיזים \u0003אף במקום שעושה בו מום, ובלבד שלא ישחט\u0004 הבכור \u0003על אותו המום. ר' שמעון אומר: אף נשחט על אותו המום. ר' יהודה אומר: אפילו מת\u0004 מהמחלה — \u0003אין מקיזין לו את הדם.\u0004","מסופר, \u0003מתני ליה\u0004 \u0005[\u0006היה \u0005משנה לו,\u0006 מלמד אותו\u0005]\u0006 \u0003ר' אלעזר לבריה\u0004 \u0005[לבנו],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה מלמד זאת \u0003ר' חייא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003כמחלוקת כאן\u0004 בברייתא זו — \u0003כך מחלוקת בחבית של תרומה. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003חבית של\u0004 שמן של \u0003תרומה שנולד בה ספק טומאה,\u0004 ואסור לאוכלה — שמא טמאה היא, ודינה בשריפה, ומצד אחר אסור להשתמש בה לצרכים אחרים, כגון להדליק בה את הנר — שמא טהורה היא, ואינה מותרת אלא באכילה. מה ייעשה בה? ר' אליעזר אומר: אם היתה החבית מונחת \u0003במקום התורפה\u0004 (במקום גלוי) שאינה נשמרת בו, ועלולה להיטמא — \u0003יניחנה במקום המוצנע,\u0004 וכן \u0003אם היתה\u0004 חבית זו \u0003מגולה\u0004 — \u0003יכסנה.\u0004","\u0003ר' יהושע אומר\u0004 להיפך: \u0003אם היתה מונחת במקום המוצנע\u0004 — \u0003יניחנה במקום התורפה, אם היתה מכוסה\u0004 — \u0003יגלנה,\u0004 כדי שתיטמא, ויוכל להשתמש בה. \u0003רבן גמליאל אומר: לא יחדש בה דבר,\u0004 כלומר, יניחנה כמות שהיא.","ויש לומר כי \u0003ר' מאיר,\u0004 האומר שאין מקיזים דם לבכור במקום שההקזה עושה בו מום, סבור \u0003כר' אליעזר,\u0004 האוסר להניח את התרומה במקום שהיא עלולה ליטמא בו. \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 האומרים שמקיזים דם לבכור אף במקום שעושה בו מום, כדי שלא ימות וניתן יהיה ליהנות ממנו (לכשיפול בו מום אחר), סבורים \u0003כ\u0004דעת \u0003ר' יהושע,\u0004 האומר שגורמים טומאה לתרומה, כדי שניתן יהיה להשתמש בה. \u0003ור' יהודה,\u0004 האומר שאין מקיזים כלל דם לבכור, סבור \u0003כ\u0004דעת \u0003רבן גמליאל,\u0004 האומר שאין נוגעים כלל בחבית התרומה כשנפל בה ספק.","את ההשוואה הזו דוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? הרי יש מקום לחלק בין המקרים. \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם,\u0006 בבכור\u0005]\u0006 שאין מקיזים במקום שעושה בו מום, אלא משום \u0003דקא עביד\u0004 \u0005[שהוא עושה\u0006 מום\u0005]\u0006 \u0003בידים, אבל הכא דגרמא\u0004 \u0005[כאן,\u0006 בחבית, \u0005שהוא רק גורם]\u0006 טומאה לחבית, ואינו עושה מעשה בגופה — \u0003כר' יהושע סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שיניחנה במקום התורפה!","\u0003ו\u0004כן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם,\u0006 בחבית\u0005]\u0006 שנפל בה ספק, שצריך לשומרה שלא תבוא לידי טומאה, \u0003אלא\u0004 משום \u0003שמא יבא אליהו\u0004 הנביא \u0003ויטהרנה,\u0004 שיאמר שלא נטמאה. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 בבכור\u0005],\u0006 \u0003דאי שביק ליה מיית\u0004 \u0005[שאם יניח אותו\u0006 כמו שהוא \u0005ימות]\u0006 — \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים הוא סבור],\u0006 שיקיז במקום שאינו עושה מום, גם אם יש חשש בדבר!","ועוד אפשר לחלק בין הדברים: \u0003ועד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן הכא\u0004 \u0005[אומרים חכמים כאן,\u0006 בבכור\u0005]\u0006 שמותר להקיז דמו, למרות שהוא עושה בו מום, אלא משום \u0003דאי שביק ליה מיית\u0004 \u0005[שאם יניח אותו\u0006 בוודאי \u0005ימות],\u0006 \u0003אבל התם\u0004 \u0005[שם,\u0006 בחבית\u0005],\u0006 שיש מקום לומר \u0003שמא יבא אליהו ויטהרנה\u0004 — \u0003כר' אליעזר סבירא להו\u0004 \u0005[סבורים הם],\u0006 שיש להצניעה, שלא תבוא לידי טומאה! ועוד אפשר לומר, \u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהודה הכא\u0004 \u0005[כאן,\u0006 בבכור\u0005],\u0006 שאין מקיזים לו דם, אלא משום \u0003דקא עביד\u0004 \u0005[שהוא עושה\u0006 מום\u0005]\u0006 \u0003בידים, אבל התם דגרמא\u0004 \u0005[שם,\u0006 בחבית, \u0005שהוא רק גורם\u0006 לדבר\u0005],\u0006 שמא \u0003כר' יהושע סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שמניח אותה על מנת שתיטמא מאליה!","\u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003רבן גמליאל התם\u0004 \u0005[שם,\u0006 בחבית\u0005]\u0006 שלא יחדש בה דבר, אלא משום \u0003שמא יבא אליהו ויטהרנה, אבל הכא\u0004 \u0005[כאן,\u0006 בבכור\u0005],\u0006 \u0003דאי שביק ליה מיית\u0004 \u0005[שאם יניח אותו\u0006 בוודאי \u0005ימות],\u0006 \u0003כרבנן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005חכמים הוא סבור],\u0006 שמקיזים אף במקום שעושים מום!","\u0003ועוד:\u0004 אין מקום להשוות את המחלוקות שבשני הדינים, בהטלת מום שבבכור ובטומאת התרומה, שכן \u0003הכא בקראי פליגי\u0004 \u0005[כאן ב\u0006דרשת \u0005המקראות\u0006 הם \u0005חלוקים],\u0006 \u0003והכא בקראי פליגי\u0004 \u0005[וכאן ב\u0006דרשת \u0005המקראות\u0006 הם \u0005חלוקים].\u0006 ומה היא המחלוקת בדרשת המקראות לגבי הטלת מום בבכור? ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הכל,\u0004 כל התנאים שנחלקו בברייתא האם מותר להקיז דם לבכור שאחזו דם, \u0003מודים במחמץ\u0004 מנחה שבמקדש \u0003אחר מחמץ\u0004 (אחר שכבר חימצו אותה) — \u0003שהוא חייב, דכתיב\u0004 \u0005[שנאמר]\u0006 במנחה: \u0003\"לא תאפה חמץ\"\u0004 (ויקרא ו, י) למרות שכבר נאמר \u0003\"לא תעשה\u0004 חמץ\" (שם ב, יא).","וכן הכל מודים \u0003במסרס אחר מסרס,\u0004 במי שעושה מעשה של סירוס בבעל חיים שכבר סירסוהו — \u0003שהוא חייב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומעוך וכתות ונתוק וכרות\u0004 לא תקריבו לה' ובארצכם לא תעשו\" (ויקרא כב, כד). ויש לשאול: מדוע הוצרך הכתוב להזכיר נתוק? \u0003אם על כורת,\u0004 שחותך את האשכים מחיבורם, \u0003חייב, על נותק,\u0004 שעוקר לגמרי את האשכים ממקומם, \u0003לא כל שכן? אלא להביא נותק אחר כורת ש\u0004גם \u0003הוא חייב.\u0004","ו\u0003לא נחלקו\u0004 החכמים בברייתא \u0003אלא במטיל מום בבעל מום,\u0004 שבכור שאחזו דם, והוא עומד למות מכך — אין לך מום גדול מזה, ש\u0003ר' מאיר\u0004 האוסר להקיז לו דם במקום שעושה בו מום, \u0003סבר\u0004 \u0005[סבור]:\u0006 נאמר לגבי קרבנות \u0003\"כל מום לא יהיה בו\"\u0004 (ויקרא כב, כא), והוא מפרשו שלא יעשה (כאילו היה מנוקד: יהיה) בו כל מום, גם אם היה בו כבר מום קודם לכן. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המתירים להקיז לו דם אף במקום שעושה בו מום, \u0003סברי\u0004 \u0005[סבורים]:\u0006 הואיל ונאמר תחילה \u0003\"תמים יהיה לרצון\"\u0004 (ויקרא כב, כא), הרי זה מלמד שדווקא בתמים יש איסור להטיל מום, ולא בבעל מום.","ושואלים: \u0003ור' מאיר, האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"תמים יהיה לרצון\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה למעוטי\u0004 \u0005[צריך אותו\u0006 כדי \u0005למעט]\u0006 מי שהיה \u0003בעל מום מעיקרו\u0004 \u0005[מתחילתו],\u0006 לפני הקדשתו, שאינו בכלל איסור זה.","ומקשים: \u0003בעל מום מעיקרו פשיטא\u0004 \u0005[פשוט]\u0006 שמותר לעשות בו מום אף אחר שהקדישוהו, הלוא \u0003דיקלא בעלמא\u0004 \u0005[דקל,\u0006 עץ, \u0005בלבד]\u0006 \u0003הוא,\u0004 כלומר, לא נתפסה בו קדושת קרבן כלל!","\u0003אלא למעוטי\u0004 \u0005[למעט]\u0006 \u0003פסולי המוקדשין,\u0004 קדשים שנפל בהם מום לאחר שהוקדשו, ונפסלו, לומר שאין איסור להטיל בהם מום \u0003לאחר פדיונן.\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואסירי\u0004 \u0005[ו\u0006הם \u0005אסורים]\u0006 \u0003בגיזה ועבודה\u0004 כמו לפני פדיונם — \u0003ב\u0004עשיית \u0003מומין נמי ליתסרו\u0004 \u0005[גם כן ייאסרו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין איסור על הטלת מום בהם.","ומצד שני שואלים: \u0003ורבנן נמי\u0004 \u0005[וחכמים גם כן],\u0006 מדוע הם סבורים שאין איסור להטיל מום בקרבן שכבר נפל בו מום? \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"כל מום לא יהיה בו\"!\u0004 ומשיבים: כתוב זה \u0003לגרמא הוא דאתי\u0004 \u0005[לגרימת\u0006 מום בבהמה תמימה \u0005הוא בא],\u0006 שלא זו בלבד שאסור להטיל מום בבהמת קדשים, אלא גם אסור לגרום שיפול בה מום. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 ממה שנאמר \u0003\"מום לא יהיה בו\"\u0004 — \u0003אין לי\u0004"],["\u0003אלא שלא יתן בו מום\u0004 בידיים. ו\u0003מנין שלא יביא דבילה\u0004 או \u0003בצק ויניחנה על\u0004 גבי \u0003האוזן\u0004 של הבכור, \u0003כדי שיבא כלב ויאכלנה,\u0004 ובתוך כך יפגום את האוזן? \u0003תלמוד לומר: \"כל מום\u0004 לא יהיה בו\" (ויקרא כב, כא) — \u0003אחד מום\u0004 שעושה בידים, \u0003ואחד כל מום,\u0004 לרבות גרמא. הרי שלענין הקזת דם הבכור יש לפרש שנחלקו בדרשת הכתובים.","וכן \u0003הכא\u0004 \u0005[כאן],\u0006 לענין תרומה שנולד בה ספק טומאה, יש לומר כי \u0003בקראי פליגי\u0004 \u0005[במקראות הם חלוקים],\u0006 ש\u0003אמר רב יהודה אמר שמואל, וכן אמר ריש לקיש, וכן אמר רב נחמן אמר רבה בר אבוה:\u0004 נאמר לאהרן ולבניו \u0003\"ואני הנה נתתי לך את משמרת תרומתי\"\u0004 (במדבר יז, ח), שצריך אתה לשמור על טהרתן,","\u0003ר' אליעזר,\u0004 האומר שצריך להצניע את חבית התרומה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003בשתי תרומות הכתוב מדבר, אחת תרומה טהורה ואחת תרומה תלויה\u0004 (ספק טמאה), \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 \u0003לה שימור,\u0004 שגם התלויה צריכה שמירה שלא תיטמא. \u0003ור' יהושע,\u0004 האומר שמותר לגרום לה ליטמא, סבור — \u0003\"תרומתי\" כתיב\u0004 \u0005[כתוב],\u0006 בלשון יחיד, ורק בתרומה טהורה מדובר.","ומקשים על הסבר זה: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 כי \u0003יש אם למקרא,\u0004 שסומכים על דרך הקריאה של המלים בתורה, ולא על דרך הכתיבה? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: נאמר באמה העבריה שחזרה לבית אביה: \"לעם נכרי לא ימשול למוכרה \u0003בבגדו בה\"\u0004 (שמות כא, ח), לומר: \u0003כיון שפירש\u0004 האדון \u0003טליתו\u0004 (\"בגדו\") \u0003עליה\u0004 ויעדה כאשה לעצמו, אם נתגרשה או נתאלמנה, \u0003שוב\u0004 האב \u0003אינו רשאי למוכרה,\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003ר' אליעזר אומר: כיון שבגד בה\u0004 האב, במה שמכרה לאמה, אם השתחררה מן האדון, \u0003שוב\u0004 האב \u0003אינו רשאי למוכרה.\u0004 משמע שאינו למד מן הקרי, ש\"בגדו\" עניינו לשון בגד, אלא מן הכתיב, שמשמעו לשון בגידה!","\u0003אלא,\u0004 יש לדחות הסבר זה ולומר: \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן,\u0006 לעניין תרומה תלויה, \u0005בזה הם חלוקים],\u0006 במה שנאמר באותו כתוב \"לך\" (\"ואני נתתי לך את משמרת תרומתי\"); \u0003ר' יהושע סבר\u0004 \u0005[סבור]:\u0006 את התרומה \u0003הראויה לך\u0004 לאכילה — \u0003שמור, ושאינה ראויה לך\u0004 (משום שיש בה ספק טומאה) — \u0003לא תשמור. ור' אליעזר\u0004 אומר: \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003ראויה היא,\u0004 ומדוע? \u0003שמא יבוא אליהו ויטהרנה,\u0004 שיאמר שלא נטמאה.","ושבים לעיקר ההלכה, בענין הקזת דם לבכור שאחזו דם. \u0003אמר רב יהודה אמר שמואל: הלכה כר' שמעון. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: הי\u0004 \u0005[לאיזה]\u0006 מדברי \u0003ר' שמעון\u0004 מתכוונים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' שמעון דמתניתין\u0004 \u0005[של משנתנו],\u0006 שמתיר להקיז את דמו אף על פי שהוא עושה בו מום, משום שאינו מתכוון לכך אלא לרפאותו — על כך יש לתמוה: וכי \u0003עד השתא לא אשמעינן\u0004 \u0005[עד עכשיו לא השמיע לנו]\u0006 \u0003שמואל\u0004 הלכה זו, ש\u0003דבר,\u0004 מעשה אסור, \u0003שאין מתכוין\u0004 לעשותו, \u0003מותר?\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' חייא בר אשי אמר\u0004 בשם \u0003רב: הלכה כר' יהודה,\u0004 הסבור שדבר שאין מתכוון אסור, \u0003ורב חנין בר אשי אמר\u0004 בשם \u0003שמואל: הלכה כר' שמעון,\u0004 הסבור שדבר שאין מתכוין מותר. \u0003ו\u0004כן \u0003רב חייא בר אבין מתני\u0004 \u0005[\u0006היה \u0005משנה]\u0006 לתלמידיו את ההלכה הזו שאמרנו \u0003בלא גברי\u0004 \u0005[אנשים]\u0006 שמסרו אותה, אלא במישרין — \u0003רב אמר: הלכה כר' יהודה, ושמואל אמר: הלכה כר' שמעון! אלא\u0004 הכוונה היא לדברי","\u0003ר' שמעון\u0004 שנאמרו ב\u0003ברייתא,\u0004 שלא זו בלבד שאין איסור בעצם המעשה, אלא שמותר לשחוט את הבכור בגלל המום שגרמה ההקזה. ומעירים: \u0003ורב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי מתני לה בהדיא\u0004 \u0005[היה שונה אותה במפורש\u0006 כך\u0005],\u0006 \u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004דברי \u0003ר' שמעון\u0004 שב\u0003ברייתא.\u0004","\u0003הצורם\u0004 (עושה פגם) ב\u0003אוזן בבכור\u0004 — \u0003הרי זה לא ישחוט\u0004 את הבכור הזה \u0003עולמית,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אומרים:\u0004 אם \u0003נולד בו מום אחר\u0004 לאחר מכן — \u0003ישחוט עליו.\u0004","ושואלים: \u0003ומי קניס\u0004 \u0005[והאם קונס]\u0006 \u0003ר' אליעזר\u0004 על מי שעבר עבירה, שיהיה אסור \u0003לעולם? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו במשנה: \u0003מי שהיתה לו בהרת,\u0004 נגע צרעת,"],["\u0003ונקצצה\u0004 הבהרת בלא מתכוון — הריהו \u0003טהור\u0004 מטומאת צרעת, שהרי אין בו עוד בהרת. אם \u0003קצצה\u0004 ב\u0003מתכוין\u0004 לטהר עצמו על ידי כך, גזרו חכמים שיהא טמא, כאילו לא נקצצה. ונחלקו חכמים במשנה מתי יטהר. \u0003ר' אליעזר אומר: לכשיולד לו נגע אחר,\u0004 ושוב אינו נהנה ממה שעשה — \u0003יטהר הימנו,\u0004 מן הנגע שקצץ, ודנים בו לפי נגעו החדש.","\u0003וחכמים אומרים:\u0004 אין לו תקנה כשייוולד לו נגע אחר, \u0003עד שתפרח\u0004 הצרעת \u0003בכולו,\u0004 שהוא סימן טהרה למצורע (ויקרא יג, יב), \u0003או עד שתמעט בהרתו מ\u0004גודל \u0003כגריס,\u0004 שאז אינה עוד סימן טומאה. משמע איפוא, שר' אליעזר אינו קונס אותו לעולם, אלא רק שלא ייהנה ממה שעשה. ואף במשנתנו, מדוע קונס ר' אליעזר את הצורם אוזן הבכור, שלא ישחט את הבכור גם כשיפול בו מום אחר?","\u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 תירוץ לסתירה זו: \u0003כי קניס\u0004 \u0005[כאשר קונס]\u0006 \u0003ר' אליעזר\u0004 במשנתנו — הרי זה \u0003בממונו,\u0004 אבל \u0003בגופו\u0004 — \u0003לא קניס\u0004 \u0005[אינו קונס].\u0006","וטעם ההבדל: \u0003ממונו\u0004 — אם לא ייאסר עליו הבכור לעולם, \u0003איכא למימר דאתי למיעבד\u0004 \u0005[יש\u0006 מקום \u0005לומר שיבוא לעשות]\u0006 בו מום, כיון שאינו מפסיד בכך, שהרי ממילא הוא אסור בבכור עד שיפול בו מום. אבל \u0003גופו,\u0004 גם אם אינו טמא אלא עד שיוולד לו נגע אחר — \u0003מי איכא למימר דאתי למיעבד\u0004 \u0005[האם יש לומר שיבוא לעשות]\u0006 איסור זה? הרי לא הרויח דבר, ולעולם יחשוש שמא לא יפול בו נגע אחר.","ולעיקר קושיית הגמרא \u0003אמר רבא:\u0004 וכי מדברי \u0003ר' אליעזר\u0004 על דברי \u0003ר' אליעזר קשיא\u0004 \u0005[קשה],\u0006 \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[ו\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים אינו קשה]?\u0006 הרי גם בדבריהם יש סתירה, שאת המטיל מום בבכור אינם קונסים עולמית, ואת הקוצץ בהרת הם קונסים לעולם!","\u0003אלא\u0004 צריך לומר כך: מדברי \u0003ר' אליעזר\u0004 על דברי \u0003ר' אליעזר לא קשיא\u0004 \u0005[אינו קשה]\u0006 — \u0003כדשנינן\u0004 \u0005[כמו שתירצנו].\u0006 \u0003רבנן אדרבנן נמי לא קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה],\u0006 והם הולכים בשיטה אחת כאן וכאן: \u0003הכא במאי דעבד קנסוה\u0004 \u0005[כאן במה שעשה קנסו אותו],\u0006 \u0003הכא במאי דעבד קנסוה\u0004 \u0005[כאן במה שעשה קנסו אותו].\u0006","ומפרטים: לענין מטיל מום בבכור, \u0003במאי איכוין\u0004 \u0005[במה\u0006 שהוא \u0005התכוון\u0006 לעשות\u0005],\u0006 \u0003למישרייה בהאי מומא\u0004 \u0005[להתירו\u0006 את הבכור \u0005במום הזה]\u0006 — \u0003בהאי מומא קנסוה רבנן\u0004 \u0005[במום זה קנסוהו חכמים],\u0006 \u0003דבהאי מומא לא לישתרי ליה\u0004 \u0005[שבמום זה לא יותר לו]\u0006 הבכור לעולם, ודינו כבכור תם, שהוא אסור עד שיפול בו מום אחר. \u0003ו\u0004כן \u0003הכא\u0004 \u0005[כאן,\u0006 בקציצת הבהרת\u0005],\u0006 גם כן, \u0003במאי דעבד קנסוה\u0004 \u0005[במה שעשה קנסו אותו],\u0006 הוא \u0003איכוין לטהורי נפשיה בהאי קציצה\u0004 \u0005[\u0006הוא \u0005התכוון לטהר\u0006 את \u0005עצמו בקציצה זו]\u0006 — \u0003בהאי קציצה קנסוה רבנן\u0004 \u0005[בקציצה זו קנסוהו חכמים],\u0006 שלא יוכל ליטהר על ידה מנגעו. ודנים בדברי ר' אליעזר שאמר: לכשיולד לו נגע אחר יטהר הימנו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 האם \u0003\"יטהר\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 שמיד כשייוולד בו נגע אחר הריהו נטהר מטומאת הנגע הראשון שקצצו, \u0003או \"ויטהר\" תנן\u0004 \u0005[שנינו],\u0006 שאינו טהור אף מן הראשון עד שיטהר מן הנגע החדש?","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם נפרש כך או כך? \u0003ל\u0004ענין \u0003חתן שנראה בו נגע\u0004 חדש, בתוך שבעת ימי המשתה, לאחר שהיה בו נגע וקצצו,","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003חתן\u0004 בתוך ימי חופתו שנראה בו נגע צרעת — \u0003נותנין לו שבעה ימים,\u0004 ימי המשתה, קודם שיראהו הכהן ויטמאהו, בין \u0003לו\u0004 לנגע שבגופו, \u0003ו\u0004בין שהיה זה נגע צרעת \u0003לאצטליתו\u0004 (בגדו העליון) \u0003ול\u0004שאר \u0003כסותו. וכן\u0004 אם נראה לאדם סתם נגע \u0003ברגל\u0004 — \u0003נותנין לו כל ימי הרגל,\u0004 קודם שיראהו הכהן.","ומעתה, \u0003אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 \"לכשיוולד לו נגע אחר \u0003יטהר\" תנן\u0004 \u0005[שנינו]\u0006 — גם במקרה זה הוא טהור במשך שבעת ימי המשתה, שהרי \u0003מקמייתא טהר ליה\u0004 \u0005[מ\u0006הבהרת \u0005הראשונה,\u0006 שקצצה, \u0005נטהר לו],\u0006 \u0003לבתרייתא נטרין ליה\u0004 \u0005[לאחרונה,\u0006 שנולדה עכשיו, \u0005ממתינים לו]\u0006 \u0003שבעה ימי משתה.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]:\u0006 \"לכשיוולד לו נגע אחר \u0003ויטהר\u0004 הימנו\" \u0003תנן\u0004 \u0005[שנינו]\u0006 — אין טעם בדבר, שהרי \u0003סוף סוף כי לא מטמיא לבתרייתא\u0004 \u0005[\u0006גם \u0005כאשר אינו מיטמא ל\u0006בהרת ה\u0005אחרונה],\u0006 מכל מקום \u0003הא מיטמא וקאי מקמייתא\u0004 \u0005[הרי\u0006 הוא \u0005מיטמא ועומד מהראשונה].\u0006 ושואלים: אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הפתרון? לשאלה זו לא נמצא פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה כי הצורם אוזן בבכור — קנסוהו שלא ישחט את הבכור בגלל המום שהטיל בו. \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: צורם אוזן בבכור, ומת\u0004 האיש שעשה עבירה זו, \u0003מהו לקנוס בנו אחריו,\u0004 שגם הוא לא ישחט את הבכור בגלל מום זה? ומשווים ספק זה לשני מקרים אחרים שיש בהם ספק דומה.","\u0003אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 לגבי \u0003מוכר עבדו\u0004 הכנעני \u0003לגוים, ומת\u0004 המוכר, ש\u0003קנסו בנו אחריו,\u0004 לפדותו מיד הגוי, כפי שהוא היה צריך לעשות, אפשר לומר כי שם יש טעם מיוחד לדבר — משום \u0003דכל יומא ויומא מפקע ליה\u0004 \u0005[שבכל יום ויום מפקיע אותו\u0006 אדוניו הגוי\u0005]\u0006 \u0003ממצו‍ת,\u0004 שהרי העבד הכנעני מחויב במקצת מצוות, וכאשר הוא אצל הגויים אינו יכול לקיימן, וצריך איפוא לפדותו. אבל טעם זה אינו שייך בענין המטיל מום בבכור.","ומצד אחר, \u0003אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 לגבי מי ש\u0003כוון מלאכתו\u0004 לעשות אותה \u0003במועד\u0004 (בחול המועד), שהביא עצמו למצב בו יפסיד אם לא יעשה אותה, וכך יתאפשר לו הדבר. ואסרו עליו חכמים לעשות מלאכה זאת במועד, ומה שעשה מאבדים ממנו, ומכל מקום אם \u0003מת\u0004 קודם המועד \u0003לא קנסו בנו אחריו,\u0004 והוא מותר לעשות עבודה זו בחול המועד — יש לומר כי דוקא שם יש לומר כן, \u0003משום\u0004 שהאב עדיין \u0003לא עבדא לאיסורא\u0004 \u0005[לא עשה את האיסור],\u0006 שלא עשה מלאכה במועד.","אבל \u0003הכא מאי\u0004 \u0005[כאן,\u0006 בצורם אוזן בבכור, \u0005מה\u0006 הדין\u0005]?\u0006 האם נאמר כי \u0003לדידיה קנסו רבנן\u0004 \u0005[לו\u0006 עצמו, שעשה איסור, \u0005קנסו חכמים],\u0006 \u0003והא ליתיה\u0004 \u0005[והרי אינו\u0006 קיים עוד\u0005].\u0006 \u0003או דלמא לממוניה קנסו רבנן\u0004 \u0005[או שמא את ממונו קנסו חכמים],\u0006 \u0003והא איתיה\u0004 \u0005[והרי\u0006 הממון \u0005ישנו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא, \u0003תניתוה\u0004 \u0005[שניתם אותה],\u0006 כלומר, יש פתרון לדבר ממה ששנינו: \u0003שדה שנתקווצה\u0004 (שהוציאו ממנה את הקוצים) \u0003ב\u0004שנת ה\u0003שביעית,\u0004 שאסורה בה כל עבודת אדמה — \u0003תזרע למוצאי שביעית,\u0004 שאין זו עבודת אדמה ממש. אבל אם \u0003ניטייבה\u0004 (זיבלו אותה), או \u0003נידיירה\u0004 עשו אותה דיר לצאן, כדי שתתמלא בזבל הצאן, שעבודה חשובה היא, שמשביח את הקרקע — \u0003לא תזרע למוצאי שביעית,\u0004 שקנסו חכמים שלא ייהנה ממה שעשה באיסור. \u0003ו\u0004על כך \u0003אמר רב אסי בר חנינא: נקטינן\u0004 \u0005[מוחזקים אנו],\u0006 שאם \u0003הטיבה ומת\u0004 — \u0003בנו זורעה\u0004 במוצאי שביעית. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לדידיה קנסו רבנן\u0004 \u0005[לו\u0006 עצמו \u0005קנסו חכמים],\u0006 \u0003לבריה לא קנסו רבנן\u0004 \u0005[לבנו לא קנסו חכמים].\u0006","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו],\u0006"],["\u0003טימא טהרות\u0004 של חבירו \u0003ומת,\u0004 שקנסוהו חכמים לשלם על הנזק שגרם לו, אם מת — \u0003לא קנסו בנו אחריו\u0004 שישלם. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003היזק שאינו ניכר\u0004 לעין \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק\u0004 מן התורה, שצריך לשלם עבורו, אלא \u0003קנסא דרבנן\u0004 \u0005[קנס\u0006 מדברי \u0005חכמים]\u0006 הוא, ומאחר שכן \u0003לדידיה\u0004 \u0005[לו עצמו]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים],\u0006 \u0003לבריה\u0004 \u0005[לבנו]\u0006 \u0003לא קנסו רבנן\u0004 \u0005[חכמים].\u0006","\u0003מעשה בזכר של רחלים\u0004 (איל) \u0003זקן, ושערו מדולדל,\u0004 משום שהיה בכור ואסור בגיזה, \u0003וראהו קסטור\u0004 (ממונה, פקיד רומאי) \u0003אחד, ואמר: מה טיבו של זה,\u0004 שהניחוהו להזקין ולא שחטוהו \u0003אמרו לו: בכור הוא, ואינו נשחט אלא אם כן היה בו מום. נטל\u0004 הקסטור \u0003פיגום\u0004 (פגיון, סכין) \u0003וצרם\u0004 (עשה חתך) ב\u0003אזנו, ובא מעשה לפני חכמים והתירו\u0004 את הבכור הזה בשחיטה. \u0003ואחר שהתירו, הלך\u0004 אותו קסטור \u0003וצירם באזני בכורות אחרים\u0004 כדי להתירם, ואסרו חכמים את הבכורות בשחיטה, למרות שהיה בהם מום.","כיוצא זו, \u0003פעם אחת היו תינוקות\u0004 (ילדים) \u0003משחקין בשדה, וקשרו זנבי טלאים זה בזה, ו\u0004כשרצו לכאן ולכאן \u0003נפסקה\u0004 (נתלש) \u0003זנבו של אחד מהם ו\u0004התברר כי \u0003הרי הוא בכור, ובא מעשה לפני חכמים והתירו\u0004 את הבכור במום זה. \u0003ראו שהתירו, הלכו וקשרו זנבות בכורות אחרים,\u0004 כדי שיפול בהם מום, \u0003ואסרו\u0004 חכמים לשוחטם. \u0003זה הכלל: כל\u0004 מום \u0003שהוא\u0004 נעשה \u0003לדעתו,\u0004 במכוון, כדי להתירו — \u0003אסור, שלא לדעתו\u0004 — \u0003מותר.\u0004","שנינו במשנה: מעשה בקסטור שהטיל מום בבכור, והתירו חכמים לשוחטו. ועוד \u0003פעם אחרת היה\u0004 מעשה בתינוקות, והתירו חכמים לשוחטו. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לספר שהתירו חכמים בתחילה בשני המקרים. \u0003דאי אשמעינן\u0004 \u0005[שאם\u0006 היה \u0005משמיע לנו]\u0006 רק את המעשה ב\u0003גוי,\u0004 היינו אומרים כי דווקא שם התירו את הבכור, משום \u0003דלא אתי למיסרך\u0004 \u0005[שאין\u0006 חשש \u0005שיבוא להתרגל]\u0006 לעשות את הדברים הללו בעתיד, שהרי אין זה מעניינו. \u0003אבל קטן דאתי למיסרך\u0004 \u0005[שיבוא להתרגל]\u0006 ולעשות כן גם בעתיד — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתירו מתחילה, גם כשעשה זאת שלא במתכוון.","\u0003ואי אשמועינן\u0004 \u0005[ואם\u0006 היה \u0005משמיע לנו]\u0006 רק לגבי \u0003קטן,\u0004 שאין אוסרים את הבכור כשעשה בו מום שלא במתכוון, היינו אומרים שהוא \u0003משום דלא אתי לאיחלופי\u0004 \u0005[שאין\u0006 חשש \u0005שיבוא\u0006 הדבר \u0005להתחלף]\u0006 \u0003בגדול,\u0004 שאין אנשים למדים ממה שנעשה בקטנים. \u0003אבל גוי,\u0004 שיש חשש \u0003דאתי לאיחלופי\u0004 \u0005[שיבוא להתחלף]\u0006 \u0003ב\u0004ישראל \u0003גדול,\u0004 שיתיר לעצמו לעשות כן — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתירו, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שיסופרו שני המעשים. ועוד בענין הקסטור שהטיל מום בבכור והתירוהו חכמים.","\u0003אמר רב חסדא אמר רב קטינא: לא שנו\u0004 שהבכור מותר, \u0003אלא\u0004 משום ש\u0003אמרו ליה\u0004 \u0005[לו]\u0006 לאותו גוי שאין הבכור נשחט \u0003\"אלא אם כן היה בו מום\",\u0004 ומשמעות הדבר היא, שאירע בו מום מאליו. \u0003אבל אם אמרו ליה\u0004 \u0005[לו]:\u0006 \"אינו נשחט אלא \u0003אם נעשה בו מום\"\u0004 — \u0003כמאן דאמרו ליה \"זיל עביד ביה מומא\" דמי\u0004 \u0005[כמי שאמרו לו: \"לך עשה בו מום\" נחשב],\u0006 וזה ודאי אסור.","\u0003אמר רבא: מכדי\u0004 \u0005[הואיל]\u0006 ובשני האופנים, משמעות הדבר שהמום \u0003ממילא\u0004 \u0005[מאליו]\u0006 \u0003הוא\u0004 נמצא בבכור, ולא כשאדם עושה אותו, אם כן \u0003מה לי\u0004 אם אמר \u0003\"היה\", מה לי\u0004 אם אמר \u0003\"נעשה\"? אלא \"נעשה\" נמי\u0004 \u0005[גם כן]\u0006 \u0003ממילא\u0004 (מאליו) \u0003הוא, ולא שנא\u0004 \u0005[ואין זה משנה]\u0006 אם כך או כך אמר, ובשניהם הבכור מותר.","שנינו במשנה, \u0003זה הכלל: כל שהוא לדעת אסור.\u0004 ומסבירים: \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 בא כלל זה? \u0003לאיתויי גרמא\u0004 \u0005[להביא גרם],\u0006 כשגורם שיפול בו מום, ולא רק אם עשה בו מום במישרין.","ומה ששנינו: \u0003שלא לדעת\u0004 מותר — \u0003לאיתויי\u0004 \u0005[להביא]\u0006 מקרה ש\u0003מסיח לפי תומו,\u0004 שסיפר לגוי בתום לב שהבכור אינו מותר אלא כשנופל בו מום, והטיל בו הגוי מום.","\u0003היה בכור\u0004 של בהמה \u0003רדפו\u0004 רודף אדם, ו\u0003בעטו\u0004 האיש כדי להתגונן, \u0003ו\u0004על ידי כך \u0003עשה בו מום\u0004 — \u0003הרי זה שוחטין\u0004 את הבכור \u0003עליו,\u0004 בגלל מום זה, מפני שלא נעשה מתוך כוונה.","שבכור זה מותר \u0003אלא שבעטו בשעת רדיפה, אבל\u0004 אם בעט בו \u0003לאחר רדיפה\u0004 — \u0003לא,\u0004 שהרי אז בוודאי כוונתו היתה לעשות בו מום. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 נתיר את הבכור, משום שלא נתכוון להטיל בו מום, אלא בעט בו משום ש\u0003צעריה הוא דמדכר\u0004 \u0005[צערו הוא שנזכר],\u0006 שהבכור רצה להזיק לו, ולכן בועט בו מתוך כעס, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שיש לחשוש שמתכוון לעשות בו מום.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך, \u0003אמר רב פפא: לא תימא\u0004 \u0005[תאמר]:\u0006 דווקא אם בעטו \u0003בשעת רדיפה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר לשוחטו על מום זה, \u0003אבל שלא בשעת רדיפה\u0004 — \u0003לא. אלא אפילו\u0004 בעטו \u0003לאחר רדיפה נמי\u0004 \u0005[גם כן]\u0006 שוחטים אותו על מום זה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003צעריה דמדכר\u0004 \u0005[צערו\u0006 הוא \u0005שנזכר],\u0006 ואינו מתכוון לעשות בו מום.","ובענין הטלת מום בבכור, \u0003אמר רב יהודה: מותר להטיל מום בבכור קודם שיצא לאויר העולם,\u0004 משום שאינו קדוש בבכורה עד שייוולד, ואין זה בכלל איסור הטלת מום בקדשים. \u0003אמר רבא:\u0004 הואיל ובכור אינו קדוש עד שיצא ראשו, \u0003גדיא\u0004 \u0005[גדי\u0006 עזים\u0005]\u0006 יכול לעשות בו מום \u0003באודניה\u0004 \u0005[באוזנו],\u0006 מפני שיש לו אזניים ארוכות, והן יוצאות לחוץ קודם שיצא כל ראשו. ואילו \u0003אימרא\u0004 \u0005[טלה\u0006 של כבשים\u0005],\u0006 שאזניו קטנות ומצויות באחורי ראשו — מטיל מום \u0003בשפוותיה\u0004 \u0005[בשפתיו],\u0006 מפני שהן יוצאות תחילה. אבל לא באזנו, מפני שהיא יוצאת לאחר שכבר יצא רוב ראשו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בשם רבא: \u0003אימרא נמי באודניה\u0004 \u0005[טלה גם כן\u0006 מטיל מום \u0005באוזנו],\u0006 \u0003אימור\u0004 \u0005[אמור]:\u0006 ודאי \u0003דרך צדעיו נפק\u0004 \u0005[יצא],\u0006 שחלקו האחורי של ראשו, ובו אזניו, יצא תחילה.","\u0003אמר רבא\u0004 בעניינים אלו: מום שבפיו של בכור, \u0003אכל ולא מיחזי\u0004 \u0005[אם כשאוכל אינו נראה],\u0006 \u0003פעי ומיחזי\u0004 \u0005[\u0006וכשהוא \u0005פועה נראה]\u0006 לפי שפותח את פיו הרבה — \u0003הוי מומא\u0004 \u0005[הרי זה מום].\u0006 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בכך? הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 מעין הדברים הללו במשנה להלן: \u0003החוטין\u0004 (החניכיים) \u0003החיצונות\u0004 של הפה \u0003שנפגמו\u0004 ונחסרו מעט, \u0003ושנגממו\u0004 (נעשו בהן חתכים) — הרי זה מום. וכן החניכיים \u0003הפנימיות שנעקרו\u0004 לגמרי. ויש לשאול: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 כשנעקרו הפנימיות הרי זה מום? והרי אין זה מום גלוי, ששוחטים בגללו את הבכור! \u0003לאו משום דכי פעי מיחזי\u0004 \u0005[האם לא משום שכאשר הוא פועה\u0006 הרי זה \u0005נראה]?\u0006 ואם כן לא חידש רבא דבר!","\u0003אמר רב פפא: רבא נמי\u0004 \u0005[גם כן]\u0006 אינו מחדש דבר, אלא \u0003טעמא דמתניתין\u0004 \u0005[\u0006את \u0005טעמה של המשנה]\u0006 הוא \u0003מפרש: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003נעקרו\u0004 החניכיים \u0003הוי מומא\u0004 \u0005[הרי זה מום]\u0006 — \u0003משום דכי פעי מיחזי\u0004 \u0005[שכאשר הוא פועה\u0006 הרי זה \u0005נראה].\u0006","\u0003כל המומין הראויין\u0004 (היכולים) \u0003לבא בידי אדם,\u0004 אבל לא ידוע אם נעשו בידי אדם, ואז אסור לשחוט את הבכור עליהם, או אם נעשו מאליהם — \u0003רועי ישראל נאמנין\u0004 להעיד שמאליהם נעשו, \u0003רועים כהנים אינן נאמנין,\u0004 לפי שהכהנים הם הנהנים מכך שהבכור נעשה בעל מום, והם נוגעים איפוא בדבר. \u0003רבן שמעון בן גמליאל אומר: נאמן הוא\u0004 הכהן להעיד \u0003על\u0004 בכור \u0003של חבירו, ואין נאמן על של עצמו.\u0004 ואילו \u0003ר' מאיר אומר: ה\u0004כהן, הואיל והוא \u0003חשוד על הדבר,\u0004 להטיל מום בבכור — \u0003לא דנו\u0004 (דן בו) בעצמו, \u0003ולא מעידו,\u0004 לא מעיד עליו אפילו עבור אדם אחר.","\u0003ר' יוחנן ור' אלעזר\u0004 נחלקו בפירוש המשנה: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: \"רועי ישראל\"\u0004 הם רועים ישראלים \u0003בי\u0004 \u0005[בביתם]\u0006 של \u0003כהנים,\u0004 והם \u0003נאמנין\u0004 להעיד על מומי הבכור, ואין הם חשודים שמשקרים בעדותם. וטעם הדבר, שכן \u0003ללגימא,\u0004 שיתנו להם הכהנים לאכול עמם מבשר הבכור, \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","אבל \u0003\"רועי כהנים\",\u0004 הם רועים כהנים \u0003בי\u0004 \u0005[בבית]\u0006 \u0003ישראל\u0004 והם \u0003אין נאמנין,\u0004 שכן \u0003מימר אמר\u0004 \u0005[אומר הוא\u0006 הרועה הכהן לעצמו\u0005]:\u0006 \u0003כיון דקא טרחנא ביה לא שביק לדידי ויהיב לאחריני\u0004 \u0005[כיון שאני טורח בו,\u0006 בבכור זה, \u0005לא יניח אותי, ויתן\u0006 הבכור \u0005ל\u0006כהנים \u0005אחרים],\u0006 ולכן חושדים בו שמא הטיל בו מום לצורך עצמו, והוא משקר.","\u0003והוא הדין\u0004 ל\u0003כהן,\u0004 שאינו נאמן להעיד \u0003לכהן\u0004 אחר על בכורו, אף שהוא עצמו לא ייהנה מן הבכור, משום \u0003דחיישינן\u0004 \u0005[שחוששים אנו]\u0006 \u0003לגומלין,\u0004 שמא יגמלו לזה לזה, וישקרו זה עבור חבירו.","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]:\u0006 \u0003נאמן הוא\u0004 הכהן \u0003על\u0004 בכור \u0003של חבירו,\u0004 ואין חוששים לגומלין, \u0003ו\u0004אולם \u0003אינו נאמן על של עצמו. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' מאיר למימר\u0004 \u0005[לומר]:\u0006 \u0003החשוד על הדבר לא דנו ולא מעידו,\u0004 וכיון שהכהנים חשודים על הבכורות — אינם מעידים כלל, אפילו לא על של כהן אחר. זו היתה שיטת הפירוש למשנה של אחד מן האמוראים שהוזכרו לעיל.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ופירשה כך: \u0003\"רועי ישראל\"\u0004 הם רועים של ישראל, \u0003והן\u0004 הרועים \u0003כהנים\u0004 הם — \u0003נאמנין\u0004 להעיד על הבכור שבעדרו של הבעלים, שמום שבו נפל בו מאליו. ואינו חשוד להטיל בו מום, מתוך הנחה שיקבל אותו מן הבעלים."],["\u0003מימר אמר\u0004 \u0005[אומר\u0006 הוא לעצמו\u0005]:\u0006 \u0003לא שביק צורבא מרבנן ויהיב לדידי\u0004 \u0005[יניח\u0006 הבעלים כהן \u0005תלמיד חכם ויתן\u0006 דווקא \u0005לי]\u0006 את הבכור. אבל \u0003\"רועי כהנים\"\u0004 רועים של כהנים \u0003והן ישראל\u0004 — \u0003אינן נאמנין, דחיישינן\u0004 \u0005[\u0006מפני \u0005שחוששים אנו]\u0006 \u0003ללגימא,\u0004 שמא הוא משקר על מנת שיאכיל הכהן גם אותו מן הבכור.","\u0003וכל שכן\u0004 רועה \u0003כהן ל\u0004בעלים \u0003כהן\u0004 אינו מעיד לו על בכורו, \u0003דחיישינן\u0004 \u0005[\u0006מפני \u0005שחוששים אנו]\u0006 \u0003לגומלין,\u0004 שהכהנים חשודים לשקר בעדותם זה על בכורו של זה, \u0003וחיישינן\u0004 \u0005[וחוששים אנו]\u0006 גם \u0003ללגימא. ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון למימר\u0004 \u0005[לומר]:\u0006 \u0003נאמן\u0004 הכהן \u0003על\u0004 בכור \u0003של חבירו\u0004 הכהן, \u0003ואינו נאמן על של עצמו. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' מאיר למימר\u0004 \u0005[לומר]:\u0006 \u0003החשוד על הדבר,\u0004 כגון, הכהנים החשודים על הבכורות, \u0003לא דנו ולא מעידו\u0004 כלל. ונחלקו, איפוא, ר' יוחנן ור' אלעזר, האם לדעת התנא הראשון במשנתנו, כהנים רועי בהמות ישראל נאמנים על מומי הבכור.","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי לדעת התנא הראשון \u0003רועי\u0004 בהמות \u0003ישראל והן\u0004 הרועים \u0003כהנים נאמנין\u0004 — \u0003היינו דאתא\u0004 \u0005[זהו שבא]\u0006 \u0003ר' מאיר למימר\u0004 \u0005[לומר]:\u0006 \u0003החשוד על הדבר לא דנו ולא מעידו,\u0004 שהרועה הכהן פסול מלהעיד גם על של הבעלים הישראל.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהתנא הראשון סבור כי \u0003רועי כהנים בי\u0004 \u0005[בבית]\u0006 \u0003ישראל אין נאמנין, מאי אתא\u0004 \u0005[מה בא]\u0006 \u0003ר' מאיר לאשמועינן\u0004 \u0005[להשמיע לנו]?\u0006 הרי \u0003היינו תנא קמא\u0004 \u0005[זו היא\u0006 שיטת \u0005התנא הראשון]!\u0006","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מה שאמר \u0003ר' יהושע בן קפוסאי. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע בן קפוסאי אומר: בכור בי\u0004 \u0005[בבית]\u0006 \u0003כהן,\u0004 שנפל בו מום — \u0003צריך שנים מן השוק להעיד עליו,\u0004 שלא נעשה במתכוון בידי אדם. אבל בני ביתו, ואפילו הרועים, אינם נאמנים.","\u0003רבן שמעון בן גמליאל אומר: אפילו בנו\u0004 של הכהן מעיד עליו, \u0003אפילו בתו\u0004 מעידה עליו. \u0003ר' יוסי אומר: אפילו עשרה והן בני ביתו אין מעידין עליו.\u0004 וכך נחלקו במשנתנו: התנא הראשון סבור כר' יהושע בן קפוסאי, שרועים כהנים אינם נאמנים להעיד על בכור של הבעלים, אבל שני כהנים מן השוק נאמנים על כך. ולדעת ר' מאיר גם שני כהנים מן השוק אינם נאמנים, מפני שהכהנים חשודים על הדבר.","ומעירים, \u0003כמאן אזלא הא דאמר\u0004 \u0005[כ\u0006דעת \u0005מי הולכת זו שאמר]\u0006 \u0003רב חסדא אמר רב קטינא: ספק בכור שנולד בי\u0004 \u0005[בבית]\u0006 \u0003ישראל,\u0004 כגון שספק אם כבר ביכרה אמו, והוא נשאר ביד בעליו, וכשיפול בו מום רשאי לאוכלו — בני ביתו אינם נאמנים להעיד שמום שבו לא נעשה במתכוון, אלא \u0003צריך שנים מן השוק להעיד עליו,\u0004 ואז מותר לבעליו לאוכלו?","\u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 נאמרה — \u0003כ\u0004דעת \u0003ר' יהושע בן קפוסאי,\u0004 האומר שבני ביתו של כהן אינם נאמנים להעיד על הבכור שבביתו. וכדין הכהן בבכור, כן דין הבעלים בספק בכור.","רב נחמן אמר: בעלים עצמם \u0003מעידין עליו,\u0004 על ספק בכור. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 אלא כל אדם חשוד על מום של בכורו, אם כן, \u0003מעשר\u0004 בהמה, שאף הוא נאכל על ידי הבעלים לכשיפול בו מום, \u0003ל\u0004דעת \u0003ר' מאיר מי מעיד עליו?\u0004 והרי לדעתו, כל החשוד על של עצמו אינו נאמן על של אחרים, וכל אדם חשוד על מעשר שלו!","ודוחים את הראיה: לגבי \u0003מעשר, ודאי\u0004 כל אדם \u0003מהימן\u0004 \u0005[נאמן]\u0006 על של עצמו, ומדוע? \u0003דאי בעי שדי ביה מומא בכוליה עדריה\u0004 \u0005[שאם\u0006 היה \u0005רוצה\u0006 לעשות את המעשר בעל מום, היה \u0005מטיל מום בכל עדרו]\u0006 בהיתר, ואחר כך מעשר. \u0003אלא\u0004 כך טוען רב נחמן: אם \u0003ספק בכור\u0004 אין הבעלים נאמנים עליו, \u0003לר' מאיר מי מעיד עליו?\u0004 והרי כל אדם חשוד על ספק בכור שלו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]: הכי נמי דלית ליה תקנתא\u0006 \u0005[כך גם כן, ש\u0006לר' מאיר \u0005אין לו תקנה]\u0006 לספק בכור, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003שהיה ר' יוסי אומר: כל\u0004 ספק בכור \u0003שחליפיו ביד כהן,\u0004 כגון שנולדו לבהמתו המבכירה שני זכרים, ואינו יודע איזה מהם בכור, והכהן מקבל אחד מהם. האחר, שנשאר בידי הבעלים, לכשיפול בו מום ויישחט — \u0003פטור מן המתנות,\u0004 מלתת לכהן זרוע לחיים וקיבה שנותנים מכל בהמת חולין, \u0003ור' מאיר מחייב\u0004 במתנות. ומכאן שאף ר' מאיר סבור שאם נפל בו מום הריהו נשחט עליו!","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003בעלים מעידין עליו,\u0004 על ספק בכור שלו, למרות שכהנים אינם נאמנים על הבכור, ומדוע נאמן? כי \u0003כהנים הוא דחשידי אמומי\u0004 \u0005[ש\u0006הם \u0005חשודים על\u0006 הטלת \u0005מומים],\u0006 אבל \u0003ישראל לא חשידי אמומי\u0004 \u0005[אינם חשודים על\u0006 הטלת \u0005מומים].\u0006","ובפסיקת ההלכה בענין עדות על מומי הבכור, \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003רב נחמן אמר: הלכה כרבן שמעון בן גמליאל,\u0004 שכהן יכול להעיד על בכור של כהן אחר, שנפל בו מום מאליו, ואפילו הוא בן ביתו. \u0003רבא אמר: הלכה כר' יוסי,\u0004 שבני ביתו של אדם אינם נאמנים.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 אם \u0003בעלים\u0004 היו \u0003עומדים עמנו בחוץ,\u0004 ובכור זה \u0003נכנס שלם\u0004 לבית \u0003ויצא חבול\u0004 — \u0003מעידין עליו\u0004 בני הבית שהמום שבו נפל מאליו. משמע שאין חושדים בבני ביתו של הכהן! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שכך אמר רבא: אם \u0003כל בעלים,\u0004 כל בני הבית היו \u0003עומדים\u0004 בחוץ, ונכנס הבכור לבית ויצא חבול — יש להניח שנפל בו מום זה מאליו, \u0003ולא חיישינן\u0004 \u0005[ואין אנו חוששים].\u0006","ושואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך\u0006 אתה מפרש, \u0005מה\u0006 בא רבא \u0005לומר]?\u0006 הרי פשוט הדבר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש לחשדא\u0004 \u0005[נחשוש לחשד],\u0006 שמא מתחילה עשו דבר שיגרום לו מום זה, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין אנו חוששים. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרבן שמעון בן גמליאל,\u0004 שבנו וביתו של כהן מעידים על הבכור. \u0003ודוקא בנו ובתו\u0004 מעידים עליו, \u0003אבל אשתו לא\u0004 נאמנת, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אשתו כגופו דמי\u0004 \u0005[נחשבת].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ל\u0004דעת \u0003ר' מאיר, דאמר\u0004 \u0005[שאומר]\u0006 \u0003החשוד על הדבר לא דנו ולא מעידו,\u0004 ולכן כהנים אינם מעידים כלל על בכור, מפני שהם חשודים על כך. \u0003וקאמר\u0004 \u0005[ו\u0006מצד אחר \u0005אומר]\u0006 \u0003ר' מאיר\u0004 כי \u0003החשוד ל\u0004עבור על \u0003דבר אחד חשוד ל\u0004עבור על \u0003כל התורה כולה.\u0004 אם כן, \u0003כהנים, הכי נמי דלא דייני דינא\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינם דנים דין],\u0006 לשיטתו, שהרי הם חשודים לכל התורה כולה? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לגבי הכהנים: \u0003\"ועל פיהם יהיה כל ריב וכל נגע\"\u0004 (דברים כא, ה), ומשמע שהם דנים דין!"],["השיב לו אביי: \u0003אימר דאמר\u0004 \u0005[אמור שאומר]\u0006 \u0003ר' מאיר\u0004 שהכהנים חשודים על הטלת מום בבכור, \u0003ל\u0004ענין \u0003חששא\u0004 \u0005[חשש],\u0006 שלא לסמוך עליהם בענין זה. אבל \u0003לאחזוקינהו\u0004 \u0005[להחזיק אותם]\u0006 בוודאות כעוברי עבירה \u0003מי אמר\u0004 \u0005[האם\u0006 הוא \u0005אומר]?\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה ללומדים\u0005]:\u0006 \u0003עד מפי עד, מהו\u0004 להיות כשר \u0003לעדות בכור,\u0004 להעיד בשמו של אדם אחר שמום שבבכור זה לא הוטל בו בכוונה? \u0003רב אסי אסר, ורב אשי שרי\u0004 \u0005[התיר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לרב אשי, והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של החכם \u0003מנשה\u0004 בברייתא: \u0003אין עד מפי עד כשר אלא לעדות האשה,\u0004 להעיד שבעלה מת. אבל לא לכל עדות אחרת!","אמר לו: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: אין עד מפי עד כשר \u0003אלא לעדות שהאשה כשרה לה בלבד,\u0004 והרי אשה כשרה להעיד על מומי הבכור.","מסופר, \u0003רב יימר אכשר\u0004 \u0005[הכשיר]\u0006 \u0003עד מפי עד בבכור, קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003מרימר\u0004 בלשון גנאי: \u0003\"יימר שרי בוכרא\"\u0004 \u0005[מתיר בכורות].\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה],\u0006 \u0003עד מפי עד כשר לעדות בכור.\u0004","ועוד בענייני עדות בכור, \u0003אמר ר' אילעא: לא היו מוחזקין בו\u0004 בבעל חיים \u0003שהוא בכור, ובא\u0004 כהן \u0003אחד ואמר שהוא בכור ומומו עמו,\u0004 שלא הוטל בו בכוונה — \u0003נאמן,\u0004 ויכול החכם להתיר לשוחטו.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 ר' אילעא בכך\u0005],\u0006 \u0003ש\u0004אומרים אנו: \u0003הפה שאסר הוא הפה שהתיר,\u0004 וסומכים עליו? הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר דבר זה במשנה: \u0003האשה שאמרה \"אשת איש הייתי וגרושה אני\"\u0004 — \u0003נאמנת, שהפה שאסר,\u0004 שאמרה שהיא אשת איש — \u0003הוא הפה שהתיר,\u0004 שאמרה שאיננה נשואה כעת!","ודוחים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שסומכים על דבריה, משום \u0003דאי בעיא לא אמרה\u0004 \u0005[שאם\u0006 היתה \u0005רוצה\u0006 להינשא בחיי בעלה \u0005לא\u0006 היתה \u0005אומרת]\u0006 שהיא אשת איש, ויכולה היתה להינשא. \u0003אבל הכא\u0004 \u0005[כאן,\u0006 לענין בכור\u0005]\u0006 \u0003דלא סגיא דלא אמרה\u0004 \u0005[ש\u0006אם רצונו לשחוט את הבכור \u0005אינו יכול שלא לומר]\u0006 לחכם שבכור הוא, לפי ש\u0003קדשים בחוץ לא אכיל\u0004 \u0005[אין\u0006 אדם \u0005אוכל]\u0006 בלי שיאמר לו החכם שבעל מום הוא,","\u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא הפה שאסר הוא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אילעא, שאף במקרה זה הוא נאמן, ומדוע? \u0003דאי משום הכי\u0004 \u0005[שאם משום כך],\u0006 משום אכילת קדשים תמימים בחוץ אתה אומר שהוא בא לפני חכם — הרי יכול היה שלא להיזקק לחכם שיתיר לו, \u0003הוה שדי ביה מומא דניכר ואכיל ליה\u0004 \u0005[\u0006ש\u0005היה מטיל בו מום הניכר ואוכל אותו],\u0006 בלא להראותו כלל לחכם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: מאי שנא מההוא גברא דאוגר ליה חמרא לחבריה\u0004 \u0005[מה שונה הדבר מאדם אחד שהשכיר לו חמור לחבירו],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא תיזיל באורחא\u0004 \u0005[אל תלך בדרך]\u0006 של \u0003נהר פקוד, דאיכא מיא\u0004 \u0005[שיש שם מים]\u0006 והחמור עלול להחליק וליפול, \u0003זיל באורחא\u0004 \u0005[לך בדרך]\u0006 של \u0003נרש, דליכא מיא\u0004 \u0005[שאין שם מים].\u0006 והשוכר \u0003אזל באורחא\u0004 \u0005[הלך בדרך]\u0006 של \u0003נהר פקוד,\u0004 שלא כדעת המשכיר, \u0003ומית חמרא\u0004 \u0005[ומת החמור],\u0006 \u0003ואתא ואמר ליה\u0004 \u0005[ובא ואמר לו]\u0006 למשכיר: \u0003באורחא\u0004 \u0005[בדרך]\u0006 של \u0003נהר פקוד אזלי\u0004 \u0005[הלכתי],\u0006 \u0003ומיהו מיא לא הוו\u0004 \u0005[ומכל מקום מים לא היו],\u0006 ולא משום כך מת החמור.","\u0003ואמר רבא:\u0004 במקרה זה אפשר להאמין לו, שהרי \u0003מה לו לשקר,\u0004 כי \u0003אי בעי אמר\u0004 \u0005[אם\u0006 היה \u0005רוצה\u0006 לשקר היה יכול \u0005לומר]:\u0006 \u0003באורחא\u0004 \u0005[בדרך]\u0006 של \u0003נרש אזלי\u0004 \u0005[הלכתי].\u0006 \u0003ואמר אביי:\u0004 אין להאמינו על כך, מפני שאת הנימוק של \u0003\"מה לו לשקר\" במקום\u0004 שיש \u0003עדים\u0004 המכחישים את דבריו \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 והרי הכל יודעים שיש מים בנהר פקוד, וכאילו העידו עדים בפנינו על כך. ואף לענין הבכור, כאשר הכהן טוען שמום שבו נפל מאליו — אין לסמוך על ההנחה שאינו צריך לשקר, שהרי ידוע שהכהנים מטילים מומים בבכור!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם ודאי איכא מיא\u0004 \u0005[שם ודאי יש מים]\u0006 בדרך נהר פקוד, וכנגד זה לא תועיל הסברה של \"מה לו לשקר\". ואילו כאן, האפשרות \u0003דאישדי ביה מומא\u0004 \u0005[שהטיל בו מום]\u0006 — \u0003חששא\u0004 \u0005[חשש]\u0006 בלבד \u0003הוא, ובמקום חששא\u0004 \u0005[חשש]\u0006 בלבד \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"מה לו לשקר\".\u0004 מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבינא וקאמר להאי שמעתא בלא גברא\u0004 \u0005[ואומר את ההלכה הזו\u0006 שאמר ר' אילעא לגבי הבכור \u0005בלא\u0006 שם \u0005איש],\u0006 אלא בסתם, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא זוטי\u0004 \u0005[הקטן]\u0006 (להבדילו מרבא המפורסם) \u0003לרבינא: אנן משמיה\u0004 \u0005[אנו משמו]\u0006 של \u0003ר' אילעא מתנינן לה\u0004 \u0005[שונים אנו אותה].\u0006","ועוד בענין שנחשדו הכהנים על מומי הבכור, מסופר, \u0003ר' צדוק,\u0004 שהיה כהן, \u0003הוה ליה בוכרא\u0004 \u0005[היה לו בכור],\u0006 \u0003רמא ליה שערי בסלי\u0004 \u0005[הטיל לו שעורים בסלים]\u0006 קלועים מנצרים, \u0003בהדי דקאכיל\u0004 \u0005[בתוך שהיה אוכל]\u0006 הבכור מהסל \u0003איבזע שיפתיה\u0004 \u0005[נקרעה שפתו]\u0006 מן הנצרים, שהיו חדים, ונעשה בעל מום. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 ר' צדוק \u0005לפני]\u0006 \u0003ר' יהושע\u0004 לשאול האם מאמינים לו שמום זה נפל שלא במתכוון, וכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' יהושע: \u0003כלום חילקנו בין\u0004 כהן \u0003חבר\u0004 (תלמיד חכם) כמוני \u0003ל\u0004כהן \u0003עם הארץ\u0004 לגבי נאמנות על מומי הבכור? \u0003אמר לו ר' יהושע: הן\u0004 \u0005[כן],\u0006 וכיון שתלמיד חכם אתה — הרי אתה נאמן.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 ר' צדוק \u0005לפני]\u0006 \u0003רבן גמליאל\u0004 הנשיא, שהיה ראש הישיבה ביבנה באותה שעה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003חילקנו בין חבר לעם הארץ? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן גמליאל: לא. אמר ליה\u0004 \u0005[לו]\u0006 ר' צדוק: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע אמר לי הן! אמר לו: המתן עד שיעלו בעלי תריסין\u0004 (בעלי המגינים, הלוחמים), שהוא כינוי של כבוד לתלמידי החכמים החשובים, \u0003לבית המדרש.\u0004","\u0003כיון שנכנסו לבית המדרש, עמד השואל\u0004 ר' צדוק \u0003ושאל\u0004 בפומבי את ר' יהושע: \u0003כלום חילקנו בין חבר לעם הארץ? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: לאו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן גמליאל: והלא משמך אמרו לי הן!\u0004","\u0003יהושע, עמוד על רגליך, ויעידו בך,\u0004 יעיד ר' צדוק שכך אמרת! \u0003עמד ר' יהושע על רגליו ואמר: היאך\u0004 (איך, מה) \u0003אעשה\u0004 בענין זה? \u0003אילמלי\u0004 (אם) \u0003אני\u0004 הייתי \u0003חי והוא מת\u0004 — \u0003יכול החי להכחיש את המת,\u0004 והייתי יכול לומר שלא כך אמרתי, \u0003עכשיו שאני חי והוא חי, היאך חי יכול להכחיש את החי?\u0004 אכן כך אמרתי.","\u0003והיה רבן גמליאל עומד ודורש\u0004 בבית המדרש, \u0003ור' יהושע\u0004 עודו \u0003עומד על רגליו,\u0004 שהרי רבן גמליאל לא נתן לו רשות לשבת, \u0003עד שריננו\u0004 (התלחשו והתלוננו) \u0003כל העם ואמרו לחוצפית המתורגמן,\u0004 שהיה מתרגם את דברי רבן גמליאל לעם: עמוד, כלומר, הפסק את התרגום. \u0003ועמד,\u0004 הפסיק.","אף שאין הכהן נאמן להעיד על הבכור שמום שבו נפל מאליו, מכל מקום \u0003נאמן הכהן לומר: הראיתי בכור זה\u0004 לחכם, \u0003ו\u0004אמר לי ש\u0003בעל מום הוא,\u0004 והוא מותר בשחיטה.","\u0003אמר רב יהודה אמר רב: נאמן הכהן לומר \"בכור זה נתן לי ישראל במומו\",\u0004 כלומר, כשכבר היה בו מום. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כל מילתא דעבידא לאיגלויי\u0004 — \u0003לא משקרי בה אינשי\u0004 \u0005[כל דבר שעשוי להתגלות\u0006 — \u0005אין אנשים משקרים בו],\u0006 והרי ניתן לשאול את הישראל האם כך היה מעשה. \u0003אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 במשנתנו דין זה: \u0003נאמן הכהן לומר \"הראיתי בכור זה ובעל מום הוא\". מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שהוא נאמן? \u0003לאו משום דאמרינן\u0004 \u0005[האם לא משום שאנו אומרים]:\u0006 \u0003כל מילתא דעבידא לאיגלויי לא משקרי בה אינשי\u0004 \u0005[כל דבר שעשוי להתגלות אין אנשים משקרים בו]?\u0006","ודוחים: יש לומר כי דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שמאמינים לו שהראהו לחכם, אבל לא משום שהדבר עשוי להתגלות, אלא משום ש\u0003קדשים\u0004 תמימים \u0003בחוץ לא אכיל\u0004 \u0005[אינו אוכל]\u0006 הכהן, ואם לא היה החכם מתיר לו — לא היה אוכל. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 שהכהן אומר שניתן לו מתחילה בכור בעל מום, \u0003כיון דחשידי\u0004 \u0005[ש\u0006הכהנים \u0005חשודים]\u0006 להטיל מום בבכור — הריהם \u0003חשידי\u0004 \u0005[חשודים]\u0006 לשקר בענין זה.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב שיזבי\u0004 על דברי רב, ממה ששנינו: \u0003האומר למי שאין נאמן על המעשר \"קח לי\u0004 (קנה עבורי) תבואה \u0003ממי שהוא נאמן\",\u0004 שאינו קונה פירות מעמי הארץ, החשודים שאינם מעשרים, \u0003או:\u0004 \"קנה לי \u0003ממי שהוא מעשר\"\u0004 — שליח זה \u0003אינו נאמן.\u0004 ולדברי רב, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינו נאמן? \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003כל מילתא דעבידא לאיגלויי לא משקרי בה אינשי\u0004 \u0005[כל דבר שעשוי להתגלות אין אנשים משקרים בו]!\u0006","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006"],["שאינו חושש לשקר, מפני \u0003דאית ליה לאשתמוטי\u0004 \u0005[שיש לו\u0006 דרך \u0005להשתמט]\u0006 ולומר שקנה מאדם שלדעתו הוא נאמן.","ומעירים: \u0003סיפא\u0004 \u0005[הסוף\u0006 של אותה משנה\u0005]\u0006 על כל פנים \u0003ודאי מסייעא ליה\u0004 \u0005[מסייע לו]\u0006 לרב יהודה, שאמר שהכהן נאמן לומר שקיבל מישראל בכור במומו, משום שאין אדם משקר בדבר העשוי להתגלות. שכך שנינו: אם אמר לשליח שיקנה פירות דוקא \u0003מאיש פלוני,\u0004 שהוא מעשר — \u0003הרי זה\u0004 השליח \u0003נאמן\u0004 לומר שקנה ממנו.","ודוחים: משם אין ראיה, כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 לשליח \u0003תובע,\u0004 המשלח שאמר לו ללכת דווקא לאיש פלוני, והוא עשוי לבדוק את הדבר — \u0003מירתת\u0004 \u0005[מפחד\u0006 לשקר\u0005].\u0006 אבל הכהן שאמר שקיבל מישראל בכור במומו, אינו חושש שילך החכם ויברר דבר זה.","\u0003אמר ר' ירמיה בר אבא,\u0004 כששמע את דברי רב יהודה: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003ליהודה הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שהכהן נאמן לומר כן? הרי \u0003אנא\u0004 \u0005[אני]\u0006 \u0003בגידול קבעתיה\u0004 \u0005[קבעתי,\u0006 לימדתי \u0005אותה]\u0006 כלומר, שניתי לגידול הלכה זו בשם רב, \u0003וגידול קבע בדידיה\u0004 \u0005[בשלו],\u0006 שנה אותה לרב יהודה, אבל הוא שיבש את הדברים. \u0003והכי אמרי ליה\u0004 \u0005[וכך אמרתי לו]\u0006 לגידול: \u0003נאמן ישראל לומר \"בכור זה נתתי לכהן במומו\",\u0004 ומתירים לכהן לשחוט את הבכור על פיו.","ותוהים: \u0003ישראל\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא נאמן, שהרי אין לו ענין בדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003ב\u0004טלה שהיה \u0003קטן\u0004 בשעה שנתנו לכהן, \u0003והגדיל,\u0004 ואז העיד עליו. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לא קים ליה\u0004 \u0005[ברור לו\u0006 הדבר\u0005]\u0006 שזה הוא הטלה שנתן לו, ושמא הוא טלה אחר, שהטיל בו הכהן מום, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאפשר לסמוך עליו.","ומעירים: \u0003בסורא מתנו כלשנא בתרא\u0004 \u0005[\u0006היו \u0005שונים כלשון אחרונה],\u0006 כפי שאמר ר' ירמיה בר אבא, שישראל נאמן להעיד שנתן לכהן בכור במומו, ואילו \u0003בפומבדיתא\u0004 היו שונים \u0003כלשנא קמא\u0004 \u0005[כלשון הראשונה],\u0006 כפי שאמר רב יהודה בשם רב, שאפילו הכהן נאמן לומר שנתן לו ישראל בכור במומו, משום שהוא דבר העשוי להתגלות. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003אפילו כלשנא קמא\u0004 \u0005[כלשון ראשונה],\u0006 ואפשר לסמוך על הכהן.","בענין זה מסופר, \u0003רפרם\u0004 שהיה \u0003בפומבדיתא הוה ליה בוכרא ויהביה ליה לכהן בלא מומא\u0004 \u0005[היה לו בכור, ונתן אותו לכהן\u0006 כשהוא \u0005בלא מום],\u0006 \u0003אזל שדא ביה מומא\u0004 \u0005[הלך\u0006 הכהן \u0005הטיל בו מום].\u0006 \u0003יומא חד חלש בעיניה\u0004 \u0005[יום אחד חלה\u0006 רפרם \u0005בעיניו],\u0006 והיה מתקשה לפתוח את עיניו, \u0003אייתיה לקמיה\u0004 \u0005[\u0006ו\u0005הביא לו]\u0006 אותו כהן את הבכור כדי שיתיר אותו בשחיטה, וכך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בכור זה נתן לי ישראל במומו. ארפסיניה לעיניה, חזייה בשקריה\u0004 \u0005[פקח\u0006 רפרם \u0005את עיניו\u0006 בכח, \u0005ראה אותו והכירו]\u0006 שהוא הבכור שנתן לו בלא מום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאותו כהן: \u0003לאו אנא דיהיבתיה לך\u0004 \u0005[\u0006האם \u0005לא אני\u0006 הוא \u0005שנתתי אותו לך]?\u0006","ומעירים: \u0003ואפילו הכי לא חש לה למילתא\u0004 \u0005[ואפילו כך לא חשש לדבר]\u0006 לומר שלא יהיו כהנים נאמנים בענין זה, מפני שסבור היה: \u0003האי הוא דחציף\u0004 \u0005[\u0006כהן \u0005זה הוא שחצוף],\u0006 שהרי העיז פניו לשקר לאותו אדם שממנו קיבל את הבכור. אבל \u0003כולי עלמא לא חציפי\u0004 \u0005[הכל,\u0006 סתם כהנים \u0005אינם חצופים],\u0006 ואפשר לסמוך שלא ישקרו בכגון זה, כאשר עשוי הדבר להתגלות.","מסופר, \u0003ההוא שרוע דאתא לקמיה\u0004 \u0005[\u0006בכור שהיה \u0005שרוע,\u0006 שעינו אחת גדולה ואחת קטנה, \u0005שבא לפני]\u0006 \u0003רב אשי,\u0004 כדי שיתיר אותו בשחיטה, כדין בעל מום. \u0003אמר: למאי ניחוש ליה\u0004 \u0005[למה נחשוש לו]?\u0006 בין \u0003אי\u0004 \u0005[אם]\u0006 \u0003כהן הוא\u0004 המביא את הבכור, בין \u0003אי\u0004 \u0005[אם]\u0006 \u0003ישראל הוא\u0004 — אין לחשוש להטלת מום במכוון, ש\u0003הרי\u0004 זה \u0003בכור ומומו עמו,\u0004 שנולד כשהוא בעל מום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003ישראל הוא, ואמר רב יהודה: אין רואין בכור\u0004 של \u0003ישראל\u0004 לבודקו ולהתירו בשחיטה. \u0003אלא אם כן\u0004 יש \u0003כהן עמו,\u0004 שיקבל בכור זה. שמא ישחטנו הישראל לעצמו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 שאמרו שצריך שיהא כהן עמו, יש מקום לחשש, כי \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003קדשים\u0004 תמימים \u0003בחוץ לא אכיל\u0004 \u0005[אין\u0006 אדם \u0005אוכל],\u0006 ולכן הביאו לחכם כדי שיאמר שיש בו מום, מכל מקום \u0003אממוניה דכהן חשיד\u0004 \u0005[על\u0006 גזל \u0005ממונו של הכהן הוא חשוד],\u0006 ליטול את הבכור לעצמו.","ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 במקרה שלפנינו, \u0003מכדי ידע דהאי\u0004 \u0005[הואיל\u0006 וישראל זה \u0005יודע שזה]\u0006 השרוע \u0003מום מובהק הוא,\u0004 והוא עומד לשחיטה, \u0003מאי טעמא אתיוה קמיה רבנן\u0004 \u0005[מה טעם הביא אותו לפני חכמים]\u0006 כדי שיתירוהו — \u0003משום כבודו\u0004 של \u0003חכם;\u0004 וכי אדם זה אשר \u0003על\u0004 (בגלל) \u0003כבודו\u0004 של \u0003חכם לא עביד\u0004 \u0005[אינו עושה]\u0006 מעשה, \u0003איסורא עבד\u0004 \u0005[איסור עושה]\u0006 לגזול את הכהן? ולכן אין מקום לחשוד בו.","\u0003הכל נאמנין על מומי מעשר\u0004 בהמה, להעיד שנפל בו מום מאליו. ואפילו הבעלים, שמותרים על ידי כך לשוחטו.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שהבעלים נאמן על מומי מעשר בהמה? מפני \u0003דאי בעי שדי ביה מומא מעיקרא\u0004 \u0005[שאם היה רוצה\u0006 שיהיה בו מום \u0005היה מטיל בו מום מתחילה]\u0006 בהיתר, קודם שעישר את בהמותיו. ותמהים: כשהוא מוציא את בהמותיו דרך פתח הדיר כדי לעשרם, \u0003מי ידע הי נפיק\u0004 \u0005[האם\u0006 הוא \u0005יודע\u0006 מתחילה \u0005איזה מהם יצא]\u0006 עשירי כדי שיטיל בו מום?","\u0003וכי תימא מפיק ליה בריש עשרה\u0004 \u0005[ואם תאמר\u0006 ש\u0005מוציא אותו\u0006 בכוונה \u0005בראש עשרה],\u0006 כלומר, בעשירי — הלא \u0003\"לא יבקר בין טוב לרע\"\u0004 (ויקרא כז, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 לגבי מעשר, לומר שאסור לעשות כך! \u0003אלא\u0004 כך צריך לומר: \u0003דאי בעי שדי ביה מומא בכולי עדריה\u0004 \u0005[שאם היה רוצה\u0006 שיהיה בו מום \u0005היה מטיל מום בכל עדרו],\u0006 בהיתר, ואחר כך מעשרם.","\u0003בכור שנסמית\u0004 (נתעוורה) \u0003עינו\u0004 או \u0003שנקטעה ידו\u0004 או \u0003שנשברה רגלו,\u0004 ואין ספק שהוא בעל מום קבוע — \u0003הרי זה ישחט על פי שלשה בני הכנסת,\u0004 שלושה יהודים רגילים, הבאים לבית הכנסת, ואינו צריך התרת חכם. \u0003ר' יוסי אומר: אפילו יש שם עשרים ושלשה\u0004 (כמנין סנהדרין קטנה, סנהדרין ב,א) \u0003אינו נשחט אלא על פי מומחה\u0004 לראיית מומי הבכור.","מסופר, \u0003ר' שמלאי ור' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003תרוייהו משמיה\u0004 \u0005[שניהם משמו]\u0006 של \u0003ר' יהושע בן לוי אמרי\u0004 \u0005[אומרים],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' שמלאי ור' יהושע בן לוי תרוייהו משום\u0004 \u0005[שניהם משמו]\u0006 של \u0003ר' יהודה נשיאה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התרת בכור בחוצה לארץ\u0004 (ובכור בחוצה לארץ אינו עומד להקרבה אפילו בזמן המקדש) — \u0003על פי שלשה בני הכנסת. אמר רבא: ו\u0004דווקא \u0003במומין מובהקין,\u0004 ברורים, שאין בהם כל ספק.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו בזו]?\u0006 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במשנתנו: \u0003בכור שנסמית עינו\u0004 או \u0003שנקטעה ידו\u0004 או \u0003שנשתברה רגלו\u0004 — \u0003הרי זה ישחט על פי שלשה בני הכנסת,\u0004 משמע — דוקא במומים ברורים כאלה. ומשנתנו עוסקת בזמן הזה, כשהבכור אינו עומד להקרבה אף בארץ ישראל!","ומשיבים: \u0003אי ממתניתין הוה אמינא\u0004 \u0005[אם ממשנתנו הייתי אומר]:\u0006 מה שמתירים שלשה בני הכנסת בזמן הזה, וכיוצא בזה \u0003בחוצה לארץ\u0004 (אפילו בזמן המקדש), הרי זה \u0003אפילו\u0004 ב\u0003מומין שאין מובהקין, והאי דקתני\u0004 \u0005[וזה ש\u0006הוא \u0005שונה]\u0006 מומים \u0003מובהקין,\u0004 הרי זה כדי \u0003להודיעך כחו\u0004 של \u0003ר' יוסי,\u0004 עד כמה הוא מחמיר, שלדעתו אפילו במומים כאלו אין מתיר אלא מומחה. לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רבא שמדובר דווקא במומים מובהקים.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר ר' ירמיה בר אבא, ספק\u0004 אמר את הדבר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב, ספק משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל:\u0004 \u0003שלשה מתירין את הבכור במקום שאין מומחה.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 בכך\u0005]?\u0006 הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנתנו: בכור שנסמית עינו וכו' \u0003הרי זה ישחט על פי שלשה בני הכנסת!\u0004","ומשיבים: \u0003אי ממתניתין הוה אמינא\u0004 \u0005[אם ממשנתנו הייתי אומר]:\u0006 אפילו \u0003במקום\u0004 שיש \u0003מומחה\u0004 יכולים שלושה בני הכנסת להתיר, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003במקום שאין מומחה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מתירים שלשה בני הכנסת, אבל \u0003במקום שיש מומחה\u0004 — \u0003לא.\u0004","\u0003אמר רב חייא בר עמרם: שלשה מתירין את הבכור במקום שאין מומחה, שלשה מתירין את הנדר במקום שאין חכם.\u0004 ומבארים: מה שאמר \u0003שלשה מתירין את הבכור במקום שאין מומחה\u0004 —"],["בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוסי\u0004 במשנתנו, שאמר שאין מתירים כלל בהדיוטות. ומה שאמר ש\u0003שלשה מפירין את הנדר במקום שאין חכם\u0004 שיכול להתיר לבדו — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הפרת נדרים בשלשה, ר' יהודה אומר:\u0004 רק אם \u0003אחד מהם חכם.\u0004 אבל במקום שאין חכם — שלושה אינם מתירים את הנדר. ועל מה שנאמר ששלושה מתירים את הנדר \u0003במקום שאין חכם,\u0004 ומשמע שחכם מתירו לבדו, שואלים: \u0003כגון מאן\u0004 \u0005[מי]?\u0006 מיהו החכם שיכול להתיר נדר לבדו? \u0003אמר רב נחמן: כגון אנא\u0004 \u0005[אני].\u0006 וביחס למה ששנינו, \u0003ר' יהודה אומר: אחד מהן חכם,\u0004 שואלים: \u0003מכלל\u0004 זה יש להבין \u0003דהנך כל דהו\u0004 \u0005[שאלה,\u0006 האחרים, הם אנשים \u0005כל שהם]\u0006 ואפילו הדיוטות גמורים? \u0003אמר רבינא:\u0004 כל אחד מהם צריך להיות אדם \u0003דמסתברי ליה וסבר\u0004 \u0005[שמסבירים לו\u0006 את ההלכה \u0005והוא מבין].\u0006 שנינו במשנה, \u0003ר' יוסי אומר: אפילו יש שם עשרים ושלשה,\u0004 אין הבכור נשחט אלא על פי מומחה. \u0003אמר רב חננאל אמר רב: אין הלכה כר' יוסי.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! הלא כל מקום שנחלקו \u0003יחיד ורבים\u0004 — \u0003הלכה כרבים!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שר' יוסי יש לו מעמד מיוחד, משום ש\u0003נמוקו עמו,\u0004 ואולי הלכה כמותו במקרה זה גם נגד הרבים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","","","ואומרים: \u0003תפשוט מהא\u0004 \u0005[תפתור מ\u0006שמועה \u0005זו]\u0006 שנאמרה בשם רב, \u0003דהך קמייתא\u0004 \u0005[שאותה\u0006 שמועה \u0005ראשונה]\u0006 שנאמרה לעיל (לו,ב) ספק בשם רב ספק בשם שמואל, ששלושה מתירים את הבכור במקום שאין מומחה, ובניגוד לדעת ר' יוסי — \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל איתמר\u0004 \u0005[נאמרה],\u0006 \u0003דאי משמיה\u0004 \u0005[שאם משמו]\u0006 של \u0003רב\u0004 נאמרה, \u0003תרתי\u0004 \u0005[שתי\u0006 פעמים\u0005]\u0006 לפסוק הלכה \u0003למה לי?\u0004","משיבים: אין מכאן הוכחה, ואפשר לומר ששתיהן נאמרו בשמו של רב, אלא \u0003חדא מכלל דחבירתה איתמר\u0004 \u0005[אחת מכלל חבירתה נאמרה],\u0006 שמכלל ההלכה שפסק רב ששלושה מתירים במקום שאין מומחה, למדו שהוא פוסק שאין הלכה כר' יוסי, וכך אמרו כאן בשמו.","\u0003השוחט את הבכור,\u0004 ומכר את בשרו, \u0003ונודע שלא הראהו\u0004 מתחילה לחכם שיתירנו, ומכר להם איפוא דבר האסור בהנאה, שטעון קבורה (ראה לעיל כח,א), ומיקח טעות הוא — \u0003מה שאכלו\u0004 הקונים מבשרו — \u0003אכלו, ו\u0004קנסו את המוכר ש\u0003יחזיר להם\u0004 את כל \u0003הדמים\u0004 ששילמו. \u0003ומה שלא אכלו\u0004 — \u0003הבשר יקבר, ויחזיר את\u0004 כל \u0003הדמים\u0004 לקונים.","\u0003וכן השוחט את הפרה ומכרה, ונודע שהיא טרפה,\u0004 ואסורה באכילה — \u0003מה שאכלו אכלו,\u0004 והוא יחזיר להם את הדמים. \u0003ומה שלא אכלו\u0004 — \u0003הם יחזירו לו את הבשר,\u0004 ואם ירצה ימכרנו לגוי או יתננו לכלב, \u0003והוא יחזיר להם את הדמים. מכרוהו\u0004 הקונים את בשר הטריפה \u0003לגוים, או הטילוהו לכלבים\u0004 — \u0003ישלמו\u0004 לזה שמכר להם \u0003דמי טרפה,\u0004 שמחירה זול, והוא יחזיר להם את שאר הכסף שקיבל מהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר בשר לחבירו ונמצא\u0004 שהוא \u0003בשר בכור\u0004 שלא התיר חכם לשוחטו, או שמכר לו \u0003פירות ונמצא\u0004 שהיו \u0003טבלים,\u0004 פירות שאינם מעושרים, או שמכר לו \u0003יין ונמצא יין נסך\u0004 — \u0003מה שאכלו\u0004 הקונים \u0003אכלו, ויחזיר להם את\u0004 כל \u0003הדמים.\u0004","","\u0003ר' שמעון בן אלעזר אומר:\u0004 אם מכר להם \u0003דברים שהנפש קצה\u0004 (מואסת) \u0003בהן\u0004 — \u0003יחזיר להן את\u0004 כל \u0003הדמים,\u0004 שאין להם הנאה במה שאכלו. \u0003ו\u0004אם מכר להם דברים \u0003שאין הנפש קצה בהם\u0004 — לא יחזיר להם את כל הדמים ששילמו, אלא \u0003ינכה להם\u0004 \u0003את הדמים\u0004 של מה שאכלו, שהרי נהנו. \u0003ואלו הן דברים שהנפש קצה בהן: נבילות וטריפות שקצים ורמשים. ואלו הן דברים שאין הנפש קצה בהן: בכורות\u0004 שלא הותרו, \u0003טבלים ויין נסך.\u0004","ושואלים: לשיטת ר' שמעון בן אלעזר, \u0003בכור\u0004 מדוע מנכה לקונה את הדמים על מה שאכל? \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הקונה: \u0003מאי אפסדתך\u0004 \u0005[מה הפסדתי לך]?\u0006 הלא אף אתה לא היית רשאי ליהנות ממנו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו, אלא \u0003כגון דזבין ליה ממקום מומא\u0004 \u0005[שמכר לו\u0006 חתיכה \u0005ממקום\u0006 שהיה בו \u0005המום],\u0006 שהרי היה בבכור זה מום, אלא שלא הראהו לחכם. \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003אי לאו דאכלת הוה מחזינא ליה\u0004 \u0005[אם לא שאכלת\u0006 כבר את הבשר \u0005הייתי מראה אותו]\u0006 לחכם, והיה רואה שיש בו מום, \u0003ושרי ניהליה\u0004 \u0005[\u0006ו\u0005מתיר לי]\u0006 לאוכלו. ומעירים: והוא \u0003כ\u0004דעת \u0003ר' יהודה\u0004 (לעיל כח,א), שאפשר להתיר את בכור בעל מום גם לאחר שנשחט.","וכן לגבי \u0003טבלים,\u0004 יכול המוכר לטעון: אם לא היית אוכל אותם, \u0003הוה מתקיננא להו ואכלנא להו\u0004 \u0005[הייתי מתקן אותם,\u0006 מפריש מהם תרומות ומעשרות, \u0005ואוכל אותם].\u0006 וכיוצא בזה לגבי \u0003יין נסך\u0004 — אין מדובר שמכר לו יין נסך לבדו, אלא שמכר לו יין שנאסר \u0003על ידי תערובת\u0004 יין נסך. \u0003ו\u0004אם לא היה שותה אותו הקונה, היתה לו תקנה ליהנות ממנו, \u0003כ\u0004דברי \u0003רבן שמעון בן גמליאל,\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003יין נסך שנפל לבור\u0004 — היין שבבור \u0003כולו אסור בהנאה. רבן שמעון בן גמליאל אומר: ימכר\u0004 היין שבבור \u0003כולו לגוים, חוץ מדמי יין נסך שבו.\u0004","","\u0003על אלו מומין שוחטין את הבכור\u0004 (בכור הבהמה הטהורה) מחוץ למקדש? ותחילה מביאים את רשימת המומים שבאוזן: \u0003נפגמה\u0004 (חסרה מעט) \u0003אזנו מן החסחוס,\u0004 מן החלק הקשה יותר של האוזן, \u0003אבל לא\u0004 אם נפגמה מן \u0003העור\u0004 בלבד. וכן \u0003נסדקה\u0004 האוזן, \u0003אף על פי שלא חסרה.\u0004 וכן אם \u0003ניקבה\u0004 האוזן, וגודל הנקב הוא לפחות \u0003מלא כרשינה\u0004 (מין קיטנית), \u0003או שיבשה\u0004 האוזן. \u0003איזהו יבשה,\u0004 שאמרו חכמים שהוא מום? \u0003כל שתנקב ואינה מוציאה טיפת דם. ר' יוסי בן המשולם אומר: יבשה\u0004 היא זו \u0003שתהא נפרכת\u0004 (מתפוררת) כשממשמשים בה.","על רשימת המומים שבמשנה זו ובמשניות שלאחריה, שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 מותר לשחוט בגללם את הבכור ולאוכלו? הלא רק \u0003פסח ועור כתיב\u0004 \u0005[נאמר]\u0006 בענין זה — \"וכי יהיה בו מום פסח או עור כל מום רע לא תזבחנו לה' אלהיך. בשעריך תאכלנו\" וכו' (דברים טו, כא—כב)!","ומשיבים: \u0003כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 מתחילה \u0003\"כי יהיה בו מום\"\u0004 (דברים טו, כא—כב), ומשמע — גם מומים אחרים. ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ונדרוש כך את הכתוב: \u0003\"כי יהיה בו מום\"\u0004 — הרי זה \u0003כלל, \"פסח או עור\"\u0004 — \u0003פרט,\u0004 והרי לפי כללי מדרש ההלכה, \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט; פסח ועור\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","ומשיבים: מה שנאמר בהמשך \u0003\"כל מום רע\"\u0004 הרי בזה \u0003חזר וכלל,\u0004 ונמצא שיש שם \u0003כלל ופרט וכלל\u0004 (מום, פיסח ועיוור, מום), ולפי כללי מדרש ההלכה — \u0003אי אתה דן\u0004 מן הכללים \u0003אלא\u0004 לדבר שהוא \u0003כעין הפרט; מה הפרט מפורש\u0004 פיסח ועיוור — הם \u0003מומין שבגלוי, ואינן חוזרין,\u0004 אינם מתרפאים, \u0003אף כל\u0004 שאר המומים — \u0003מומין שבגלוי ואינן חוזרין.\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003מה הפרט מפורש,\u0004 פיסח ועיוור — הם \u0003מומין שבגלוי, ו\u0004בעל חיים \u0003בוטל ממלאכתו\u0004 בגללם, \u0003ו\u0004מום זה \u0003אינו חוזר\u0004 (מתרפא), \u0003אף כל\u0004 שאר המומים — \u0003מומין שבגלוי, ובוטל ממלאכתו, ואינו חוזר.\u0004 אבל מום שאין בו הגדרות אלו — אין שוחטים בגללו את הבכור! \u0003אלמה תנן\u0004 \u0005[ומפני מה שנינו]\u0006 במשנה: \u0003נפגמה אזנו מן החסחוס ולא מן העור?\u0004 והרי אין זה מבטל אותו מעבודה!","ומשיבים: מה שנאמר בפסוק זה \u0003\"כל מום רע\",\u0004 לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 לרבות כל מום, גם כשאינו כעין הפרט המפורש. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שיש פה ריבוי כולל, \u0003מומין שבסתר,\u0004 שאינם גלויים, \u0003נמי\u0004 \u0005[גם כן]\u0006 ייחשבו כמומים לענין זה! \u0003אלמה תנן\u0004 \u0005[מפני מה שנינו]\u0006 ברשימת המומים ששוחטים עליהם: \u0003חוטין\u0004 (חניכיים) \u0003החיצונות שנפגמו\u0004 ונחסרו, ושנגממו (שיש בהן חתכים), \u0003ו\u0004החניכיים \u0003הפנימיות שנעקרו\u0004 לגמרי;"],["ונדייק: \u0003נעקרו\u0004 הפנימיות — \u0003אין\u0004 \u0005[כן]\u0006 שוחטים את הבכור, אבל אם \u0003נפגמו ונגממו\u0004 — \u0003לא,\u0004 מפני שהוא מום שבסתר! ומשיבים: אין מרבים מ\"כל מום רע\" מומים שבסתר, משום ש\u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003\"מום רע\",\u0004 שנראה בגלוי, ויש בכך גנאי, \u0003ו\u0004כשהוא בסתר \u0003ליכא\u0004 \u0005[ואין כאן]\u0006 מום רע. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שכל המומים נתרבו מ\"כל מום רע\", חוץ ממומים שבסתר — \u0003מום עובר נמי\u0004 \u0005[גם כן]\u0006 יהיה מותר לשחוט בגללו את הבכור! \u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה\u0005]:\u0006 נפגמה אזנו מן החסחוס, שוחטים על כך את הבכור, \u0003ולא\u0004 אם נפגמה \u0003מן העור,\u0004 מפני שהוא מום עובר?","ומשיבים: \u0003מום עובר\u0004 אין למדים מריבוי הכתוב, משום ש\u0003סברא הוא: השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 על מום עובר אפילו \u0003מיפרק לא פרקינן עלויה\u0004 \u0005[לפדות אין אנו פודים עליו]\u0006 את הקרבן, \u0003משחט שחטינן עלויה\u0004 \u0005[\u0006וכי \u0005שוחטים אותו עליו]\u0006 מחוץ למקדש בלא פדיון? ומניין שאין פודים בהמה בגלל מום עובר — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בפרשת פדיון בהמה מיד ההקדש: \u0003\"ואם כל בהמה טמאה אשר לא יקריבו ממנה קרבן לה' \"\u0004(ויקרא כז, יא) — \u0003ב\u0004קרבנות טהורים \u0003בעלי מומין הכתוב מדבר.\u0004","ודנים: \u0003אתה אומר בבעלי מומין שנפדו הכתוב מדבר? או אינו\u0004 מדבר \u0003אלא בבהמה טמאה ממש,\u0004 כמו חמור וסוס, שהקדישם. אבל בהמה טהורה, גם אם נפל בה מום, שמא לא ניתן להוציאה מיד ההקדש בפדיון! ומשיבים: \u0003כשהוא אומר\u0004 בהמשך: \u0003\"ואם בבהמה הטמאה\"\u0004 (ויקרא כז, כז) — \u0003הרי בהמה טמאה אמור, הא מה אני מקיים \"אשר לא יקריבו ממנה\"\u0004 — \u0003הוי אומר: זה בעלי מומין שנפדו.\u0004 ומכאן למדנו שהם נפדים.","\u0003יכול יפדו\u0004 קרבנות \u0003על מום עובר\u0004 שנפל בהם? \u0003תלמוד לומר: \"אשר לא יקריבו ממנה קרבן לה' \"\u0004(ויקרא כז, יא) — \u0003מי שאינה קריבה כל עיקר\u0004 היא הנפדית, \u0003יצתה זו,\u0004 בעלת מום עובר, \u0003שאינה קריבה היום אלא למחר.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר, מדוע מום עובר אינו בכלל ריבוי הכתוב \"כל מום רע\" ששוחטים בגללו את הבכור: \u0003אם כן,\u0004 שגם על מום עובר שוחטים, \u0003פסח ועור\u0004 שהזכיר הכתוב \u0003למה לי?\u0004 די היה שיאמר הכתוב \"כל מום רע\"! אלא בא למעט מום עובר, שאינו כשני מומים אלה, שהם קבועים.","שנינו במשנה: אוזן הבכור ש\u0003נסדקה אף על פי שלא חסרה\u0004 שוחטים עליה את הבכור מחוץ למקדש. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: גודל \u0003הסדק\u0004 ששוחטים עליו — \u0003כל שהוא, הפגימה\u0004 — \u0003בין\u0004 שנעשתה \u0003בידי אדם, בין בידי שמים.\u0004 ושואלים: האם \u0003מכלל\u0004 הדברים אתה למד ש\u0003סדק בידי שמים לא\u0004 נחשב למום? והרי גם זה מום הנראה לעין!","\u0003אלא\u0004 כך צריך לומר: הסדק כל שהוא, \u0003סדק ופגימה\u0004 — \u0003בין בידי שמים בין בידי אדם.\u0004 ועוד שנו חכמים באותה ברייתא: \u0003וכמה שיעור פגימה? כדי שתחגור\u0004 (תתעכב) \u0003בה ציפורן,\u0004 שכשאדם מעביר ציפורנו על האוזן הריהי נכנסת שם.","שנינו במשנה כי אוזן הבכור ש\u0003נקבה מלא\u0004 כרשינה — שוחטים על כך את הבכור. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כמה נקיבת האוזן? מלא כרשינה. ר' יוסי בר' יהודה אומר: בכעדשה,\u0004 שהיא קטנה מעט ממנה. \u0003ואיזו היא יבשה? שאם תינקב אינה מוציאה טיפת דם. ר' יוסי בן המשולם אומר: יבשה כדי שתהא נפרכת\u0004 (מתפוררת).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003קרובין דבריהן להיות שוין\u0004 למעשה. ושואלים: \u0003דבריהן דמאן\u0004 \u0005[של מי]\u0006 קרובים להיות שווים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 דבריהם של \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003ור' יוסי בן המשולם\u0004 בענין אוזן שיבשה, האם כשאינה מוציאה דם, או כשהיא נפרכת — \u0003טובא איכא\u0004 \u0005[הרבה יש\u0006 ביניהם\u0005]!\u0006 \u0003אלא,\u0004 הכוונה היא לדבריהם של \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003ור' יוסי בר' יהודה,\u0004 שכן כרשינה ועדשה כמעט שוות בגודלן.","ועל דבריו של ר' יוסי בר' יהודה שואלים: ניקבה \u0003כעדשה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הרי זה מום, \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003מכעדשה\u0004 — \u0003לא? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא בענין עבד עברי שאינו רוצה לצאת לחפשי, ורוצעים את אזנו, כלומר, עושים בה נקב במרצע. נאמר: \"ולקחת את ה\u0003מרצע\u0004 ונתתה באזנו ובדלת\" (דברים טו, יז) — \u0003אין לי אלא\u0004 ב\u0003מרצע\u0004 בלבד, \u0003מנין לרבות\u0004 שאר דברים שיש להם חוד, \u0003הסול\u0004 (עץ מחודד), \u0003והסירה\u0004 (מין קוץ), \u0003והמחט, והמקדח, והמכתב\u0004 (חרט, שכותבים בו)?","\u0003תלמוד לומר: \"ולקחת\"\u0004 (דברים טו, יז) — \u0003כל דבר שנלקח ביד,\u0004 אלו \u0003דברי ר' יוסי בר' יהודה. רבי אומר,\u0004 כך יש לדרוש את המלה \u0003\"מרצע\": מה מרצע מיוחד של מתכת\u0004 — \u0003אף כל\u0004 דבר שרוצעים בו יהא \u0003של מתכת,\u0004 אבל לא סול וסירה.","\u0003וקתני סיפא\u0004 \u0005[והוא שונה בסוף]\u0006 אותה ברייתא: \u0003אמר רבי, יודן ברבי\u0004 (הגדול) \u0003היה דורש\u0004 כך: \u0003כשהן רוצעין\u0004 את אזנו של העבד — \u0003אין רוצעין אלא במילת,\u0004 בחלק הרך, התחתון של האוזן.","\u0003וחכמים אומרים:\u0004 אין לומר כן, שהרי מקובל בידינו ש\u0003אין עבד עברי כהן נרצע, מפני ש\u0004הוא \u0003נעשה\u0004 בכך \u0003בעל מום,\u0004 ונפסל לעבודת המקדש. \u0003ואם תאמר במילת היו רוצעין, היאך עבד כהן נעשה בעל מום\u0004 ברציעה? והרי נקב בחלק זה של האוזן חוזר ונרפא! \u0003הא\u0004 \u0005[הרי]\u0006 למדת מכאן ש\u0003אין רוצעין אלא בגובה של אוזן,\u0004 כלומר, בסחוס, שהוא גבוה מן המילת. על כל פנים, למדנו מדברי ר' יוסי בר' יהודה כי נקב שנעשה על ידי מחט, נחשב למום, למרות שהוא בוודאי פחות מכעדשה!","\u0003אמר רב חנא בר קטינא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמר ר' יוסי בר' יהודה בכעדשה — הרי זה שיעור כדי \u0003לשחוט\u0004 על ידו את הבהמה מחוץ למקדש, \u0003כאן,\u0004 שנקב כל שהוא נחשב למום — הרי זה כדי \u0003לפסול\u0004 את הבהמה להקרבה, כפי שהוא פוסל את הכהן לעבודה.","על שיעור הנקב באוזן הבכור, שלדעת חכמים הוא ככרשינה, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003כרשינה? אמר רב שרביא:\u0004 היא הקרויה בארמית \u0003\"הינדא\".\u0004","ובפרטי הלכה זו \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הושעיא מרב הונא רבה\u0004 \u0005[הגדול]:\u0006 האם הכוונה היא ל\u0003כרשינה הנכנסת ויוצאה\u0004 בנקב, והוא איפוא גדול מעט מן הכרשינה, \u0003או\u0004 ל\u0003כרשינה העומדת\u0004 בתוך החור, שהנקב הוא בדיוק ככרשינה? \u0003אמר לו: זו,\u0004 הלכה מפורשת בענין זה \u0003לא שמעתי,\u0004 אבל \u0003כיוצא בה שמעתי,\u0004 שלשון \"מלא (כרשינה)\" משמעה, שתהא נכנסת ויוצאת.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השדרה והגולגולת\u0004 של מת \u0003שחסרו,\u0004 אינן מטמאות טומאת אוהל. ושאלו במשנה: \u0003כמה חסרון בשדרה ולא יהא\u0004 \u0003מטמא באהל? בית שמאי אומרים:\u0004 אם היתה חסרה \u0003שתי חוליות, ובית הלל אומרים: חוליא אחת. ובגולגולת,\u0004 כמה תהא חסירה ולא תטמא? \u0003בית שמאי אומרים:\u0004 אם חסרה \u0003כמלא מקדח, ובית הלל אומרים:\u0004 אם הוא גדול עד \u0003כדי ש\u0004אם \u0003ינטל\u0004 חלק בגודל זה \u0003מן החי וימות.\u0004","ומסופר, \u0003ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003רב חסדא וקמיבעיא ליה\u0004 \u0005[ונשאלה לו]\u0006 שאלה זו: \u0003כדי שינטל מן החי\u0004 — \u0003וכמה?\u0004 מהו השיעור? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב תחליפא בר אבודימי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כ\u0004גודל מטבע הקרויה \u0003סלע.\u0004","ומעירים: \u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו אמוראים בשם מי אמר רב תחליפא דבר זה לרב חסדא, \u0003רב ספרא אמר: שמעתתא אמר ליה\u0004 \u0005[שמועה של\u0006 אמוראים \u0005אמר לו],\u0006 כפי שנאמר כאן, בשם שמואל. \u0003ורב שמואל בר יהודה אמר: מתניתא אמר ליה\u0004 \u0005[ברייתא אמר לו],\u0006 שנאמר שם ששיעור זה הוא כסלע. \u0003וסימניך,\u0004 שתזכור מה אמר כל אחד — הלשון המצויה בתלמוד \u0003\"תני רב שמואל בר יהודה\",\u0004 ויש בכך רמז שלדברי רב שמואל בר יהודה השיב רב תחליפא לרב חסדא מתוך ברייתא, ולדעת רב ספרא — מתוך שמועה של שמואל.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרב תחליפא: \u0003אם כן,\u0004 ששיעור החסרון לדעת בית הלל הוא כסלע, \u0003עשיתה דברי בית שמאי ודברי בית הלל אחד,\u0004 שהרי שיעור מקדח וסלע — שיעור אחד הם, וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מאור\u0004 (חלון) \u0003שלא נעשה בידי אדם,\u0004 אלא כגון שנפלה אבן מעצמה, \u0003שיעורו\u0004 כדי להביא את טומאת המת מחדר לחדר, הוא \u0003מלא אגרוף גדול, וזהו אגרופו של בן אבטיח,\u0004 שהיה ידוע כאיש גדול במיוחד. \u0003אמר ר' יוסי: וישנו\u0004 שיעור האגרוף הזה, \u0003כראש גדול של אדם.\u0004","אבל אם \u0003נעשה\u0004 החלון \u0003בידי אדם, שיערוהו\u0004 כמה יהא גדול ויביא את הטומאה — \u0003כמלא מקדח גדול של לשכה,\u0004 שהיה מונח בלשכה שבמקדש, \u0003שהוא כ\u0004גודל המטבע \u0003פונדיון של האיטלקי, ו\u0004הוא \u0003כ\u0004שיעור \u0003סלע נירונית\u0004 (של הקיסר נירון). \u0003וישנו,\u0004 ושיעורו —"]]};
